window.HB_TR["2-samuel"]["ks"]=["1.\\tوۅنۍ سپد ساؤل سٕندِ مرنہٕ پتہٕ ییلہ داؤد امالیکین ہٕندِ قتلہٕ نشہِ واپس آو تہٕ داؤد اوس زِکلاگس مَنٛز زٕ دۅہن روزان۔\n2.\\tتریمہِ دۅہہ سپد یہ زِ وُچھ اکھ انسان ساؤلس نشہِ خٲمہِ منزہ نیبر نیران تہ کلس پیٹھ میژِ ہیتھ تہ ییلہ سُہ داؤدس نِش آو، سہ پیوٚو زمینس پیٹھ تہ سجدہ کٔرِتھ۔\n3.\\tتہٕ داؤد ووٚن تٔمِس زِ ژیہ کتہِ پیٹھہٕ آو؟ تہٕ تٔمۍ ووٚن أمِس زِ بہٕ ژوٚل اسرٲیلِک خٲمہٕ منز۔\n4.\\tتہٕ داؤدَن ووٚن أمِس زِ معاملہٕ کِتھہ پٲٹھۍ؟ بہٕ چُھس ژےٚ دُعا کران، مے وَنُن۔ تہٕ تٔمۍ دیُت جواب، زِ لوٗکھ چھِ جنگہٕ نِش ژٔلۍمٕتۍ، تہٕ واریاہ لوٗکھ تہِ گٔیہِ مارٕ تہٕ مارٕ۔ تہٕ ساؤل تہٕ جوناتھن تہِ چُھ تٔمۍ سُند نیچو موٗدمُت۔ {کتھہ پاٹھۍ...: ہیب۔ کیا اوس وغیرہ}\n5. تہٕ داؤد ووٚن تٔمِس نوجوانَس یٔمۍ أمِس ووٚن، ژےٚ کِتھ کٔنۍ چُھ خبر زِ ساؤل تہٕ یوناتھن تٔمۍ سُنٛد نیچو چُھ موٗدمُت۔\n6.\\tتہٕ یُس نوجوان أمِس وَنُن ووٚن، یُتھ بہٕ اتفاقاً گلبوا پہاڑس پیٹھ سپدیومُت، وُچھ ساؤل پننِس نیزس پیٹھ تھوٚک۔ تہٕ لو، رتھ تہٕ گُرۍ سوار لٔگۍ أمِس پَتہٕ پَتہٕ۔\n7. تہٕ ییلہ تٔمۍ پانس پتھ کُن نظر دِژ، تٔمۍ وُچھ میہ تہٕ کوٚرُن میہ بلاو۔ تہٕ میہ دیت جواب، یتھے {am} I. {یتھ...: Heb. میہ وچھو}\n8.\\tتہٕ تٔمۍ ووٚن مے کُس چُھہ؟ تہٕ میہ دیت تس جواب، بہٕ چُھس اکھ امالیک۔\n9. تٔمۍ ووٚن میہ دُبارٕ، کھڑا روزُن، بہٕ چھُس ژے دُعا کران تہٕ مٲرِتھ کٔرِتھ، تکیازِ میانہِ زندگی چھے وُنہِ تہِ پورٕ۔ {دکھ ...: یا، میون کوٹ آف میل (یا، میون کڑھائی کوٹ) چھہ میہ رُکاوٹ کران، سہ میون بیترِ}\n10. تہٕ بہٕ ووت أمِس پیٹھ تہٕ مٲرِتھ تہٕ مٲرِتھ تہٕ میہ اوس یقین زِ سُہ ہیوٚک نہٕ زندٕ روزِتھ، تہٕ مے تُل سُہ تاج یُس تٔمۍ سٕندِس کلس پیٹھ اوس، تہٕ سُہ کٔرُن یُس تٔمۍ سٕندِس نرِ پیٹھ اوس، تہٕ یُس تٔمۍ سٕندِس نرِ پیٹھ اوس، تہٕ أنِم یِم پننِس مٲلکَس نِش۔\n11.\\tپَتہٕ رٔٹِتھ رٔٹِتھ تہٕ رٔٹِتھ رٔٹِتھ ۔ تہٕ یِتھے پٲٹھۍ تِم سٲری مرد یِم أمِس سٍتۍ ٲسۍ:\n12. تہٕ تِمو روُکھ ماتم تہٕ روُکھ تہٕ روزٕ روزُن، ساؤل سٕندِ خٲطرٕ، تہٕ تٔمۍ سٕندِس نیچوِس یوناتھن سٕندِ خٲطرٕ، تہٕ خداوند سٕندِ لوکن خٲطرٕ، تہٕ اسرٲیلِس کِس گھرس خٲطرٕ۔ تکیازِ تِم ٲسۍ تلوار سٍتۍ پیوٚمٕتۍ۔\n13.\\tتہٕ داؤد ووٚن تٔمِس نوجوانس یُس أمِس ووٚنمُت چھُ، کتہِ چُھہ؟ تہٕ تٔمۍ دیُت جواب، بہٕ چُھس أکِس اجنبی سُند نیچو، اکھ امالیکی۔\n14. تہٕ داؤدَن ووٚن أمِس زِ ژے کِتھ کٔنۍ کھوژٕ نہٕ خداوند سٕندِس مسح کرنہٕ مۅکھٕ پنُن اَتھٕ پٔھلاونہٕ خٲطرٕ؟\n15.\\tتہٕ داؤدن بُلوو أکِس نوجوانس منز، تہٕ ووٚنُن، نِش گژھ تہٕ أمِس پیٹھ پیوٚو۔ تہٕ تٔمۍ دِژ أمِس مارٕ زِ سُہ موٗد۔\n16.\\tتہٕ داؤدَن ووٚن تٔمِس زِ تُہُند خوُن گژھہِ تُہندِس کلس پیٹھ۔ تِکیازِ چُھہ چُھہ تۅہہِ خلاف گوٲہی دِژمٕژ زِ مے چُھہ خداوند سُند مسح کرنہٕ آمُت مٲرِمُت۔\n17. تہٕ داؤد کٔر ساؤل تہٕ پننِس نیچوِس یوناتھن سٕندِس سٍتـ̡ ماتم کٔرِتھ:\n18.\\t(بییہِ دِژ تِمن یہوداہ کین بچن کمان ہیچھناوُن: وُچھِو، {یہِ} چھُ یَشر سٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت۔) {جاشر سٕندِ: یا، سیدِ سٕندِ}\n19.\\tاسرٲیلٕچ خوبصورتی چھے تۅہہِ تھزرن پیٹھ مارنہٕ آمٕژ: طاقتور کِتھہ پٲٹھۍ!\n20. وَنُن {یہ} نہٕ گاتھس منز، شایع کرُن {یہ} نہٕ اسکلون کین سڑکن منز۔ یێلہِ گژھہِ فلسطینن ہٕنزِ کورِ خۅش گژھن، نتہٕ گژھن ختنہ سپدن واجنہِ کورِ ہٕنز۔\n21.\\tاے گلبوا ہٕندِس پہاڑَس مَنٛز گژھہِ نہٕ شُنمُن، تہٕ نہٕ آسُن تہٕ نذرانہٕ ہٕندِس کھہَس مَنٛز آسُن، تِکیازِ اَتہِ چھُ طاقتور سٕنز ڈھال گٔژھِتھ دِنہٕ آمٕژ، ساؤل سٕنز ڈھال، {یِتھٕ پٲٹھۍ چھُنہٕ تٔمِس تیٖلہٕ سٍتـ̡ مسح کرنہٕ آمُت۔\n22. مقتول سٕندِ خونہٕ سٍتـ̡ ، طاقتور سٕندِ چربی سٍتـ̡ گۆو نہٕ یوناتھن سٕنز کمان پتھ کُن تہٕ ساؤل سٕنز تلوار آو نہٕ خٲلی واپس۔\n23.\\tساؤل تہٕ یوناتھن ٲسۍ پننہِ زندگی منز پیاری تہٕ خۄشگوار تہٕ مرنس منز ٲسۍ نہٕ تِم تقسیم سپدان: تِم ٲسۍ عقاب کھۅتہٕ تیز تہٕ شیرن کھۅتہٕ زیادٕ مضبوط۔ {خوشگوار: یا، مٔٹھۍ}\n24. اے اسرٲیلٕچ کورِو، روو ساؤلس پیٹھ، یٔمۍ تۅہہِ سرخ پوشہٕ لٲگِتھ لٔگِتھ، یِمو تُہٕندِس پلوس پیٹھ سۄنہٕ سٕندِ زیور لٲگِتھ۔\n25.\\tجنگس منز کِتھہ پاٹھۍ چھہِ طاقتور پیوٚو! اے جوناتھن، {ژے چھُکھ پننین تھدٮ۪ن مقامن پیٹھ مارنہٕ آمُت۔\n26. بہٕ چُھس ژےٚ خٲطرٕ پریشان گومُت، میون بٲے جوناتھن: ژٕ چُھس میانہِ خٲطرٕ واریاہ خۅش گومُت: چانۍ محبت ٲس میانہِ خٲطرٕ حیرت انگیز، زنانن ہٕندِس محبتس سٍتۍ وابستہٕ۔\n27.\\tطاقتور کِتھہ پاٹھۍ گٔیہِ مارۍ تہٕ جنگکۍ ہتھیار گٔیہِ ختم!","1. تہٕ امہِ پتہٕ سپُد یہِ زِ داؤدَن پرژھ خداوند سٕندِس سٍتـ̡ یہوداہ کِس کُنہِ شہرس مَنٛز گژھُن؟ تہٕ خداوند ووٚن أمِس ہیوٚر ہیوٚر۔ تہٕ ڈیوڈس ووٚن، بہٕ کوٚت گژھہٕ ہیوٚر؟ تہٕ ووٚن ہیبرونس تام۔\n2. یێمہِ پٲٹھـ̡ ووت داؤد تتہِ تہٕ تٔمۍ سٕنزِ زٕ زنانہٕ تہِ، احینوم یزریلیٹس تہٕ ابیگیل نابل سٕنز زنانہٕ کارمیلیٹ ۔\n3.\\tتہٕ تٔمۍ سٕندِس نفرس یُس أمِس سٍتـ̡ اوس، تٔمۍ کٔر داؤد سٍتـ̡ پرٮ۪تھ أکِس نَفس سٍتـ̡ پَنٕنـ̡ گَرٕ سٍتـ̡ تہٕ تِم رودۍ حبرون کِس شہرن مَنٛز روزان۔\n4. تہٕ یہوداہٕکۍ مرد آیہ، تہٕ تتہِ کوٚر تِمو یہوداہ کِس گرس پیٹھ داؤد بادشاہ مسح کرنہٕ۔ تہٕ تِمو ووٚن داوُد، {یہ} یِمو یِمو ساؤل دفن کٔرۍ۔\n5.\\tتہٕ داؤدن سوٗزۍ یبیشگلعاد کین لوکن نِش قاصد تہٕ تِمن وونُن، خداوند سٕندِ سٍتـ̡ بابرکت چھُ، یێلہِ تہِ چُھہ ساؤلس سٍتـ̡ یێلہِ مہربانی ہٲومٕژ۔\n6. تہٕ وۅنۍ چُھہ خداوند ژے سٍتـ̡ مہربانی تہٕ سچائی ہاوان: تہٕ بہٕ کٔرٕ ژے یہ احسان تہٕ بدلہٕ، کیازِ ژے چھے یہ کٲم کٔرمٕژ۔\n7. تێمہِ کِنۍ گژھ پنٕنۍ اتھہٕ مضبوٗط تہٕ بہادر بٔنِو، تکیازِ تُہند آقا ساؤل چُھ موٗدمُت، تہٕ یہوداہ کِس گرن تہِ چُھ مے تمن پیٹھ بادشاہ مقرر کوٚرمُت۔ {بی یے...: ہیب۔ بہادری ہٕندۍ فرزند بٔنِو}\n8.\\tمگر نیر سٕندِس نیچِوِس ساؤل سٕندِس لشکرُک کپتان، نیُن ساؤل سُند نیچو اشبوشیت تہٕ أنِن مہانایمس نِش۔ {ساؤل سُند میزبان: حب۔ میزبان یُس ساؤل سُند اوس} {اشبوشیتھ: یا، اشبال}\n9. تہٕ بنووُن سُہ جلعادس پیٹھ، اشورین پیٹھ، یزریل، افرائیمس پیٹھ، تہٕ بنیامین تہٕ سارنٕے اسرٲیلِس پیٹھ بادشاہ۔\n10. اشبوشیت ساؤل سُند نیچو اوس ژتٲجی وُہُر ییلہ تٔمۍ اسرائیلس پیٹھ حکومت کرٕنۍ شروع کٔر، تہٕ دۄن ؤرین کٔرن حکومت۔ مگر یہوداہُک گرٕ آو داؤد سٕندِ پتہٕ۔\n11.\\tتہٕ یُس داؤد یہوداہ کِس گرس پیٹھ ہیبرونس مَنٛز بادشاہ اوس، ستھ ؤری تہٕ شیہ ریتھ۔ {وقت: ہیب۔ دۄہَن ہُنٛد تعداد}\n12. تہٕ نیر سُند نیچو ابنیر تہٕ شاؤل سُند نیچو اشبوشیت سٕندِ خادم گٔیہِ مہنایم پیٹھہٕ گِبیونس کُن۔\n13.\\tتہٕ زرویاہ سُند نیچو یوآب تہٕ داؤد سٕندِ نوکر دراو نیبر، تہٕ گٔیہِ جبیعون کِس تالابس نِش اِکہٕ وٹہٕ، تہٕ بیوٹھ تِم بیوٹھ، اَکھ تالابس اَکہِ طرفہٕ تہٕ بییِس طرفہٕ تالابَس کِس دوٚیمہِ طرفہٕ۔ {یکوٹہٕ: ہیب۔ تِم یکوٹہٕ}\n14.\\tتہٕ ابنیرن ووٚن یوآبس زِ جوان گژھن وۅنۍ وۅتھان تہٕ اسہِ برونہہ کنہِ گِندُن۔ تہٕ یوآبن ووٚن، تِم گژھن وۅتھنہٕ۔\n15.\\tپَتہٕ ووت بنیامین سٕندِس بارہ نمبرس سٍتـ̡ یُس ساؤل سٕندِس نیچوِس اشبوشیت تہٕ داؤد سٕندِس خادمَن سٍتـ̡ بَہہ سٍتـ̡ متعلق۔\n16.\\tتہٕ تِمو رٔٹِتھ پرٮ۪تھ أکِس سٲتھی سٕندِس کلہٕ پیٹھ، تہٕ لٔگِن تٔمۍ سٕنزِ تلوار تٔمِس سٲتھی سٕندِس طرفس منز۔ چنانچہ گٔیہِ تِم اَکہٕ وٹہٕ: اَمہِ مۄکھٕ اوس تتھ جایہِ ہلکتھزوریم وَننہٕ یُس گِبیونَس مَنٛز {چھُ}۔ {ہیلکتھزوریم: یعنی مضبوط مردن ہند میدان}\n17.\\tتہٕ تمہِ دۅہہ گۆو سٮ۪ٹھاہ خوفناک جنگ۔ تہٕ ابنیر آو داؤد سٕندِس خدمتگارس برونہہ کُن مار دِنہٕ۔\n18.\\tتہٕ اَتہِ ٲسۍ زرویاہ سٕندِ ترے نیچوۍ، یوآب تہٕ ابیشایی تہٕ عساہیل، تہٕ اَساہل اوس جنگلی گُرِ ہٕندۍ پٲٹھۍ۔ {کھۄر: ہیب۔ تٔمۍ سٕندِس قدمن ہُند} {بطور جنگلی...: ہیب۔ بطور اکھ رو یُس میدانس منز چُھ}\n19.\\tتہٕ اَساہل لوٚگ ابنرس پَتہٕ۔ تہٕ گژھنس منز پھیر نہ سُہ دٔچِھنہِ اتھس کُن تہٕ نہ کھوورِ کُن۔ {پیٹھ...: ہیب۔ ابنرس پتہٕ}\n20.\\tاَمہ پتہٕ وُچھُن اَبنَن پَتہٕ پَتہٕ تہٕ وُچھُن، {آر} تُہۍ چھُکھ اَسہیل؟ تہٕ تٔمۍ دیُت جواب، بہٕ {am}۔\n21.\\tتہٕ ابنرن ووٚن أمِس دٔچھنِس اتھس کُن یا کھوورِ طرفہٕ پھیُرُن تہٕ أکِس نوجوانَس تھپھ کٔرِتھ رٔٹِتھ تٔمۍ سُند ہتھیار رٔٹِتھ تٔمۍ سُند ہتھیار رٔٹِتھ۔ مگر اساہیل اوس نہٕ أمِس پتہٕ پتھ کُن۔ {آرمر: یا، خراب}\n22.\\tتہٕ ابنرن ووٚن اَسہیلس دُبارٕ زِ ژے کٔرِو میانہِ پتہٕ پَکناونہٕ نِش، بہٕ کیازِ دِیہٕ ژے زٔمیٖنس پیٹھ۔ تیلہِ کِتھہ پاٹھۍ تھپھ کٔرِتھ یوآب پننِس بٲیِس کُن۔\n23. توتہِ کوٚر تٔمۍ پتھ کُن پھیرنس انکار: کیازِ دِژ ابنیرن نیزٕ ہٕندِس پٔتمہِ اندس سٍتـ̡ پوٗنٛژمہِ رِب تَل تہٕ نیزٕ دراو أمِس پَتہٕ کُن نیبر۔ تہٕ سُہ پیوٚو تتہِ پیوٚو، تہٕ موٗد أتھۍ جایہ: تہٕ یہ سپُد، {یہ} تِمن ہٕندِس جایہِ وٲتِتھ ییتہِ آساہیل پیوٚو تہٕ موٗد روٗد۔\n24.\\tیوآب تہٕ ابیشایی تہِ لوٚگ ابنیرس پَتہٕ: تہٕ آفتاب لوسُن ییلہ تِم عمہ کِس بالس پیٹھ وٲتۍ، یُس گِبیونُک بیابان کِس وتہِ کِنۍ گیاہ برونہہ کُن اوس۔\n25.\\tتہٕ بنیامین سٕندِ شُرۍ گٔیہِ اَبنرس پَتہٕ جمع تہٕ بنییہِ اَکھ لشکر تہٕ أکِس بالہٕ کِس تینتٲلِس پیٹھ کھڑا۔\n26.\\tاَمہِ پَتہٕ ووٚن ابنیرن جوآبس تہٕ وونُن زِ تلوار گژھہِ ہمیشہٕ خٲطرٕ کھٮ۪نہٕ؟ ژیہ چھا نہ پتاہ زِ یہ آسہِ ٲخری اندس منز تلخی؟ تیلہِ کوتاہ کال روزِ تۅہہ لوکن پننین باین ہنز پیروی کرنہٕ نِش واپس یِنُک حکم دِنہٕ۔\n27.\\tتہ یوآب ووٚن زِ خدا زندہ، یوت تام نہ ژیہ کتھ آسہِ کٔرتھ، تیلہِ آسہِ صبحس لوکھ پننس بٲے سٍتـ̡ وۅتھان۔ {منز...: ہیب۔ صبحس پیٹھ} {گٔیہِ...: یا، گٔیہِ}\n28.\\tیَتھ کٔر یوآبن بُرٕ، تہٕ سارِوٕے لُکھ کھڑا تہٕ لوٚگ نہٕ اسرٲیلِس پَتہٕ پَتہٕ، تہٕ لوٚگ نہٕ تِمو پتہٕ۔\n29.\\tتہٕ ابنیر تہٕ تٔمۍ سٕندِس نفرس پٔکۍ سارِوٕے رٲژ میدانس مٔنٛزۍ، تہٕ اردن کِنۍ گٔیہِ، تہٕ سارِنٕے بِتھرون کِنۍ گٔیہِ، تہٕ تِم وٲتۍ مہانایم۔\n30.\\tتہٕ یوآب آو ابنرس پتہٕ واپس، تہٕ ییلہ تٔمۍ سارِنٕے لُکھ جمع کٔرۍ، تتہِ ٲس داؤد سٕندِس نوکرس کُنوُہ نفر تہٕ اساہیلٕچ کمی۔\n31.\\tمگر داؤد سٕندٮ۪و نوکرو اوس بنیامین تہٕ ابنرس سٕندِس نفرس مارمُت، {یێتھ] ترے ہتھ تریہ نفر مارٕ۔\n32.\\tتہٕ تِمو تُل اَساہل تہٕ دفن کٔرِکھ أمِس مٲلہِ سٕندِس قبرس مَنٛز، یُس بیت لحمس مَنٛز اوس۔ تہٕ یوآب تہٕ تٔمۍ سٕندۍ نفر گٔیہِ سارِوٕے رٲژ تہٕ تِم آیہ دۅہہ پھُلِتھ ہیبرون کُن۔","1. وۅنۍ اوس ساؤل سٕندِس گرس تہٕ داؤد سٕندِس گرس درمِیان واریاہس کالس جنگ سپدان مگر داؤد سُند گرٕ گوٚو زیادٕ مضبوط، تہٕ ساؤل سُند گرٕ گوٚو کمزور تہٕ کمزور۔\n2. تہٕ داؤدس ٲس ہیبرونس مَنٛز زامٕتـ̡ نیچوۍ، تہٕ تٔمۍ سُند گۄڈنیُک زامُت اوس امنون، یُس اہنوام یِزریلیتس سٍتـ̡ اوس۔\n3. تہٕ تٔمۍ سُند دوٚیِم چِلیاب، ابیگیل سٕنز زنانہٕ، یۄس نبل دی کارمیلیٹ سٕنز زنان ٲس۔ تہٕ تریٚیِم، گشور کِس بادشاہ تلمایی سٕنز کورِ ماکا سُند نیچو ابسالوم۔ {چِلیاب: یا، ڈینیئل}\n4. تہٕ ژوٗرِم، ہگِتھ سُند نیچو عدونیاہ ۔ تہٕ پٲنژم، شیفطیہ ابیتل سُند نیٚچُو۔\n5.\\tتہٕ شیٚیِم، اِتھریم، ایگلہ داؤد سٕنزِ زنانہِ۔ یِم ٲسۍ ہیبرونس منٛز ڈیوڈس زامٕتۍ۔\n6. تہٕ سپُد ساؤل سٕندِس گرس تہٕ داؤد سٕندِس گرس درمِیان جنگ سپُد، ابنرن بنوو ساؤل سٕندِس گرس خٲطرٕ مضبوط۔\n7.\\tتہٕ ساؤلس ٲس اکھ لونڈی، یٔمۍ سُند ناو اوس رِزپاہ، یُس آیہ سٕنز کورِ ٲس، تہٕ {اشبوشیتھ} ووٚن ابنرس زِ ژے کیازِ گٔیہٕ میٲنس مٲلہِ سٕنزِ لونڈی نِش۔\n8.\\tاَمہِ پَتہٕ آو اِشبوشتھ سٕندِس کلامَس سٍتـ̡ سٮ۪ٹھاہ شرارت تہٕ وونُن، {بہ} چُھس ہوُن سُند کلہٕ، یُس یہوداہ سٕندِس مٲلِس سٍتـ̡ از تہٕ تٔمۍ سٕندِس بٲے سٕندِس گرس سٍتـ̡ تہٕ تٔمۍ سٕندِس یارن سٍتـ̡ مہربانی کران چُھ، تہٕ چُھکھ نہٕ ژے داؤد سٕندِس اتھس مَنٛز دِژمُت، زِ ژے چُھہ از تہٕ یێمہِ زنانہِ ہٕندِس بارس مُتلق کُنہِ قصور ہُند الزام دِوان۔\n9. یِتھے پٲٹھۍ چُھہ خدا ابنرس سٍتـ̡ تہٕ زیادٕ تہِ، یێلہِ زن خداوند داؤدس سٍتـ̡ حلف کورمُت چُھ، یێلہِ چُھس بہٕ أمِس سٍتـ̡ تہِ کٔرِتھ۔\n10.\\tساؤل سٕندِ گرٕ پیٹھٕ بادشٲہی ہُند ترجمہٕ کرُن، تہٕ داؤد سُند تخت بٔنِتھ تہٕ یہوداہَس پؠٹھ تہٕ دان پیٹھٕ بیرشبع تام تہِ بٔنِتھ۔\n11.\\tتہِ ہیوٚک نہ ابنرس بییہ کانہہ لفظ جواب دِتھ، تکیازِ تس اوس تس کھوژان۔\n12.\\tتہٕ ابنیرن سوٗزۍ تٔمِس طرفہٕ داؤدس نِش قاصد تہٕ وونُن زِ یہِ زمین کٔمۍ سٕندِس {چِھ}؟ یہ تہِ ونان زِ میہ سٍتـ̡ رٔلِتھ رٔلِتھ تہٕ وُچھِو میون اَتھٕ ژے سٍتـ̡ سارِنٕے اسرٲیلِس پانس نِش اننہٕ۔\n13. تہٕ تٔمۍ ووٚن، خٲر۔ بہٕ کٔرٕ ژے سٍتۍ اکھ لیگ، مگر اکھ چیز یُس میہ ژے منگان چھُ، یعنی ژے گژھ نہ میون بُتھ وُچھن، یوٚت تام نہ ژیہ گۅڈٕ میکل ساؤل سنز کورِ أنِتھ، ییلہ ژے میون بُتھ وُچھِ۔ {یعنی: ہیب۔ وَنُن}\n14. تہٕ داؤدن سوٗز اشبوشیت ساؤل سٕندِس نیچوِس نِش قاصد تہٕ وونُن زِ میانہِ زنانہٕ میخال دِیُن یُس میہ فلسطینن ہٕندِس ہتھ کھالس مۅکھٕ دِنہٕ آمُت اوس۔\n15.\\tتہٕ اشبوشیتن سوٗز، تہٕ نِیوُن سُہ [پننِس} خانٛدارس نِش، حتیٰ کہ لیش سٕندِس نیچوِس پھالٹیئلس نِش۔ {Phaltiel: تہٕ چُھ ونان، Phalti}\n16.\\tتہٕ تٔمۍ سُند خانٛدار گوٚو أمِس سٍتـ̡ پَتہٕ وُنـ̡ بہوریم کُن۔ اَمہ پتہٕ ووٚن ابنرس أمِس گژھ واپس۔ تہٕ سُہ آو واپس۔ {اَلِتھ...: ہیب۔ گَژھُن تہٕ وَنُن}\n17.\\tتہٕ ابنرن کٔر اسرٲیلِہ کین بزرگن سٍتـ̡ کتھ باتھ کرنہٕ آمٕژ، یێلہِ تہٕ ژے اوس پتھ کالس مَنٛز داؤد سٕندِ خٲطرٕ بادشاہ بننٕچ تلاش کٔرمٕژ: {زمانہٕ...: حب۔ راتھ تہٕ تریم دۅہہ}\n18.\\tتێلہِ کٔرِو تہٕ یێلہِ خداوند داؤدٕچ کتھ کٔرِتھ چُھہ وَنُن زِ میانہِ خادم داؤد سٕندِ اتھہٕ سٍتـ̡ بہٕ بچاوٕ پننین لوکن ہٕندِ اتھہٕ نِش تہٕ تِہندِ سارِنٕے دُشمنن ہٕندِ اتھہٕ نِش بچاونہٕ۔\n19.\\tتہٕ عبنرن تہِ کٔر بنیامین سٕندِس کنن مَنٛز کتھ کرنہٕ، تہٕ ابنیر تہِ گۆو ہیبرونس مَنٛز داؤد سٕندِس کنن مَنٛز کتھ کرنہٕ خٲطرٕ، یُس سارِنٕے بنیامین سٕندِس گرس خٲطرٕ اصل باسان۔\n20.\\tیێلہِ آو عبنر داؤدس نِش ہیبرون تہٕ تس سٍتـ̡ وُہ نفر۔ تہٕ داؤدن بنوو ابنیر تہٕ تِمن نفرن ہٕنز دعوت یِم أمس سٍتـ̡ ٲسۍ۔\n21. تہٕ ابنرن ووٚن داوڈس زِ بہٕ وۅتھٕ تہٕ نیرٕ تہٕ سارنٕے اسرٲیلِس پننِس آقا بادشاہس نِش جمع کٔرِتھ، یُتھ تِم ژے سٍتـ̡ رٔلِتھ تہٕ تُہٕندِس دِلس سٍتـ̡ یێلہِ تُہٕندِس سارِنٕے سٍتـ̡ بادشاہس سٍتـ̡ بادشاہ سٍتـ̡ رٔلِتھ ۔ تہٕ ڈیوڈس سوٗز ابنیر۔ تہٕ سُہ گوٚو امن سان۔\n22.\\tتہٕ وُچھ داؤد تہٕ یوآب سٕندِ نوکر آیہ أکِس لشکر سٍتـ̡ تہٕ أنِکھ پانس سٍتـ̡ سٍتـ̡ لوُٹ لوُنـ̡ ۔ تکیازِ تٔمۍ اوس سُہ سوزمُت، تہٕ سُہ اوس امن سان ژوٚلمُت۔\n23.\\tییلہ یوآب تہٕ سٲری لشکر یُس أمِس سٍتـ̡ اوس، تِمو ووٚن یوآبس تہٕ وونُن زِ نیر سُند نیچو آو ابنیر بادشاہس نِش تہٕ سُہ گۆو سُہ\n24. پتہٕ آو یوآب بادشاہس نِش تہٕ وونُن، ژے کیا کوٚر ؟ وُچھ اَبنیر آو ژےٚ نِش۔ کیازِ چھُکھ یہِ {یہ} ژے سوزمُت، تہٕ سُہ چُھ بالکل ژٔلِمُت؟\n25. ژے چُھہ نیر سُند نیچو ابنیرس زانان زِ سُہ چُھ ژےٚ دھوکہٕ دِنہٕ خٲطرٕ آمُت تہٕ تُہند نیرُن تہٕ یِنہٕ خٲطرٕ تہٕ تُہند یِنہٕ خٲطرٕ تہٕ تُہٕندِس سارِنٕے سٍتـ̡ زاننہٕ خٲطرٕ آمُت۔\n26. تہٕ ییلہ یوآب داؤد نِش نیبر آو، تٔمۍ سوٗزۍ ابنرس پتہٕ قاصد، یُس سُہ سیرہ کِس کۅرٕ پیٹھٕ دُبارٕ أنِتھ، مگر داؤدس ٲس نہٕ خبر۔\n27.\\tتہٕ ییلہ ابنیر حبرون واپس آو تہٕ یوآبن نیو سُہ دروازس منز أکِس طرفہٕ أمس سٍتـ̡ ژھۅپہٕ سان کتھ کرنہٕ خٲطرٕ، تہٕ دِژُن تتہِ پوٗنٛژمہِ رِب تَل زِ سُہ موٗد تٔمِس بٲے اَساہیل سٕندِس خونس مۅکھہٕ۔ {خاموشی سان: یا، سُکون سان}\n28.\\tتہٕ امہ پتہ ییلہ داؤد بوٗز، تٔمۍ ووٚن، بہٕ تہٕ میٲنۍ بادشٲہی چُھس خداوند سٕندِ برونہہ کُن ہمیشہ خٲطرٕ بے قصور، نیر سٕندِس نیچو ابنیر سٕندِ خونس سٍتـ̡ {خون: حب۔ بلڈز}\n29.\\tیہِ گژھہِ یوآب سٕندِس کلس پیٹھ تہٕ تٔمۍ سٕندِس مٲلہِ سٕندِس سارِنٕے گرس پیٹھ۔ تہٕ یُس یوآب سٕندِس گرس سٍتـ̡ کانہہ مسلہٕ آسہِ، یا یُس کوڑھ آسہِ، یا یُس لٔرِس پیٹھ لٔگِتھ آسہِ، یا یُس تلوارس پیٹھ پیوٚو، یا یُس روٹی آسہِ نہٕ۔ {ناکام: ہیب۔ ژٹنہٕ یِو}\n30. یێمہِ سٕندِس بٲے یوآب تہٕ ابیشایی ین مور ابنیر، تکیازِ تٔمۍ اوس جنگس مَنٛز پنُن بوے عساہیل مارمُت۔\n31.\\tتہٕ داؤدس ووٚن یوآبس تہٕ تِمن سارِنٕے لُکن یِم أمِس سٍتـ̡ ٲسِتھ، پَنٕنۍ پلو ژٔٹِتھ تہٕ ژٔٹِھکھ پَنُن پلو لٲگِتھ تہٕ ابنرس برونہہ کُن ماتم کٔرِو۔ تہٕ بادشاہ داؤد {پانہٕ} کٔر بیئرس پتہٕ۔ {بیئر: ہیب۔ بستر}\n32.\\tتہٕ تِمو کٔر ابنیرس حبرونس مَنٛز دفن: تہٕ بادشاہن تُل پنٕنۍ آواز، تہٕ روُن ابنیر سٕنزِ قبرِ پیٹھ۔ تہٕ سارِوٕے لوکھ رووُن۔\n33.\\tتہٕ بادشاہن کٔر ابنرس پیٹھ ماتم تہٕ وونُن، ابنیر مٔر بیوقوف بٔنِتھ؟\n34.\\tتُہٕندِ اتھہٕ ٲسٕکھ نہٕ بٔنِتھ، تہٕ کھۅر ٲسٕکھ زنجیر کٔرِتھ، یِتھٕ پٲٹھۍ چھُکھ انسان بدکارن برونہہ کُن پٮ۪وان، تِتھے پٲٹھۍ چھُکھ ژے گٔژھان۔ تہٕ سارِوٕے لُکھ رووُن أمِس پیٹھ دُبارٕ۔ {بدکار...: ہیب۔ بدکاری ہٕندۍ بچہٕ}\n35.\\tتہٕ ییلہ سارِوٕے لُکھ داؤدس دۅہ آسنہٕ وِزِ ماز کھٮ۪نہٕ خٲطرٕ آۓ، داؤد ووٚن قسم، یێلہِ تہٕ یێلہِ بہٕ چُھس روٹی چکھُن، تہٕ بییہِ تہِ چُھس آفتاب لوسنہٕ تام۔\n36.\\tتہٕ سارِوٕے لُکو کٔر اَتھ کُن توجہ تہٕ یہِ کٔر تِمن خۅش۔ {خوش گٔژھمٕتۍ: ہیب۔ تہنزِ نظرِ منز اوس اصل}\n37.\\tسارِنٕے لُکھ تہٕ سارِنٕے اِسرٲیلِس اوس تمہِ دۅہہ سمجُن زِ نیر سُند نیچو ابنیر مارُن اوس نہٕ بادشاہ سُند۔\n38.\\tتہٕ بادشاہن ووٚن پننین خدمتگارن زِ کیا تۅہہ چھے نہٕ خبر زِ از کل چُھ اسرٲیلس منز اکھ شہزادہ تہٕ اکھ بٔڈ انسان پیوٚومُت۔\n39. تہٕ بہٕ چُھس از کل کمزور، حالانکہ بادشاہ مسح کرنہٕ آمُت۔ تہٕ یِم نفر زرویاہ سٕندِ نیٚچوۍ، میانہِ خٲطرٕ سٮ۪ٹھاہ مشکل: خداوند دِیہِ بدکار سٕندِس بدکار سٕندِس سٍتـ̡ بدلہٕ۔ {کمزور: ہیب۔ ٹینڈر}","1. تہٕ ییلہ ساؤل سٕندِس نیچوِس بوز زِ ابنیر چُھ ہیبرونس مَنٛز موٗدمُت، تٔمۍ سٕندِ اتھہٕ گٔیہِ کمزور، تہٕ سارِنٕے اسرٲیلِیو گٔیہِ پریشان۔\n2. تہٕ ساؤل سٕندِس نیچوِس ٲسۍ زٕ نفر {یِم} بینڈن ہٕندِ کپتان: أکِس سُند ناو اوس بعناہ، تہٕ بییِس رِچاب سُند ناو، یُس بنیامین سٕندِ شُرین ہُند نیچو اوس، یُس بنیامین سٕندِس شُرین ہُند اوس۔ دوٚیِم}\n3. تہٕ بیروتھیس ژٔل گِتایم کُن، تہٕ روٗد از تام اتہِ روزان۔)\n4.\\tتہٕ جوناتھن، ساؤل سٕندِس نیچوِس اوس اَکھ نیچو {یُس} تٔمۍ سٕندِس کھورِ سٍتـ̡ لوٚنگـ̡ اوس۔ سُہ اوس پانٛژ وُہُر ییٚلہِ ساؤل تہٕ یوناتھن سٕنز خبر یِزریلہٕ منزٕ آیہ، تہٕ تٔمۍ سٕنزِ نٔرس نِش تُلِتھ ژٔلِتھ گٔیہِ۔ تہٕ تٔمۍ سُنٛد ناو اوس میفیبوشیتھ۔ {میفیبوشیتھ: یا، مریبعل}\n5.\\tتہٕ رِمون بیروتھیٹ سٕندِ نیچوۍ، رِچاب تہٕ بانہ گٔیہِ دۅہہٕ کِس گرس منز، یُس دُپہرس بسترس پیٹھ لوٚگ۔\n6.\\tتہٕ تِم آیہِ تتہِ گرس منز، {یِتھٕ پٲٹھۍ} تِمو آسہ کٕنُک اَنان۔ تہٕ تِمو دِژ أمِس پوٗنٛژمِس رِبَس تَل تہٕ رِچاب تہٕ بَناہ ژٔلِتھ تٔمِس بٲے ژٔلِتھ۔\n7.\\tکیازِ ییلہ تِم گرس منز آیہ، سُہ لوٚگ پننِس بسترس منز بسترس پیٹھ، تہٕ تِمو لوٚگ أمِس مارُن، تہٕ کلہٕ ژٹُن تہٕ کلہٕ ژٹِتھ تہٕ سارِوٕے رٲژ مٲدانس منز ژٔلِتھ۔\n8.\\tتہٕ تِمو اوٚن اِشبوشیت سُند کلہٕ داؤد نِش ہیبرون کُن، تہٕ وونُن بادشاہس زِ وُچھِو شاؤل سٕندِس نیچوِس اشبوشیث سُند کلہٕ، یُس تُہند دُشمن ہُند دُشمن اوس۔ تہٕ خداوند چُھ از ساؤل سٕندِس بادشاہس تہٕ تٔمۍ سٕندِس اولادس سُند انتقام۔\n9. تہٕ داؤدن دیُت رِچاب تہٕ بعناہ پننِس بٲیِس یُس رِمون بیروتھیٹ سٕندِس نیچوِس جواب دِیُت، تہٕ تِمن وونُن زِ خداوند چُھ زندٕ، یٔمۍ میون روح تمام مُصیبتَو نِش نجات دِژمُت چُھ،\n10.\\tییلہ میہ ووٚن زِ وچھ ساؤل چُھ موٗدمُت، یہِ سونچِتھ زِ سُہ چُھس خوشخبری دِنہٕ آمُت، مے رٔٹتھ تہٕ مٲرِتھ زِکلاگس مَنٛز، یُس {سونچِتھ} زِ بہٕ دِیہ أمِس تٔمِس خبرن ہُند انعام: {سونچ...: ہیب۔ سُہ اوس پننین نظرن منز بٔنِتھ وغیرہ} {کُس...: یا، یُس انعام اوس میہ تس تٔمۍ سٕنزِ خبرن خٲطرٕ دِژمُت}\n11. بییہِ کوتاہ چُھہ ییلہ بدکار انسان پننِس گرس منز اکھ نیک شخص پننِس بسترس پیٹھ مارِ۔ تَمہِ کِنۍ کیا بہٕ چھُس نہٕ وۄنۍ تٔمۍ سٕنٛدِ اَتھٕ ہُنٛد خوٗن، تہٕ نِنہٕ ژےٚ زمینہٕ نِش؟\n12.\\tتہٕ داؤد دِژ پننین جوانن ہُند حُکُم، تہٕ تِمو مارِکھ تِمن ہٕندِس اتھہٕ تہٕ کھۅر ژٹِتھ تہٕ لٔٹِتھ لٔٹِتھ ہیبرونس کِس تالابس پیٹھ۔ مگر تِمو نیو اشبوشیت سُند کلہٕ، تہٕ کٔرٕکھ حبرون کِس ابنیر سٕندِس قبرس مَنٛز دفن۔","1. اَمہِ پَتہٕ وٲتِتھ آیہ اسرٲیلٕکۍ سٲری قبیلہٕ داؤد نِش حبرونس نِش، تہٕ وونُن زِ وُچھِو أسۍ تُہٕنز أڈجہِ تہٕ تُہُند ماز ۔ \n2. پتھ کالہِ ییلہ ساؤل اسہِ پیٹھ بادشاہ اوس، تہٕ تۅہہ ٲسکھ سُے یُس اسرٲیلِس مَنٛز نیران اوس، تہٕ خداوند ووٚن ژے میانین لوکن اسرٲیلس کھیٛان، تہٕ ژٕ بنہٕ اسرٲیلُک کپتان۔ \n3. یێمہِ پٲٹھـ̡ گٔیہِ اِسرٲیلٕکۍ سٲری زِٹھہٕ بادشاہس نِش ہیبرون کُن۔ تہٕ بادشاہ داوُد کٔر تِمن سٍتـ̡ ہیبرونس مَنٛز رٔلِتھ تہٕ تِمو بنوو داؤد اسرٲیلِس پیٹھ بادشاہ۔ \n4. داؤد اوس ترہ وُہُر ییلہ تٔمۍ حکومت شروع کٔر، {تہٕ} تٔمۍ کٔر ژتٲجی ؤرین حکومت۔ \n5. ہیبرونس مَنٛز کٔر تٔمۍ یہوداہَس پؠٹھ سَتھ ؤری تہٕ شیہ ریتن حکوٗمت۔ تہٕ یروشلمس مَنٛز کٔر تٔمۍ سارِنٕے اسرٲیلِس تہٕ یہوداہ ہس پیٹھ ترٕہ ترٕہ ؤرین حکوٗمت۔ \n6. تہٕ بادشاہ تہٕ تٔمۍ سٕندِ نفر گٔیہِ یروشلمس مَنٛز یِم زمینہٕ کین بسکینن نِش یِمو داؤدس سٍتـ̡ کتھ کٔرِتھ وۆن، یوتام نہٕ ژے انہِ تہٕ لنگڑن نِش نِنہٕ، تۅہہ گژھِو نہٕ یتہِ اژُن: سونچِتھ زِ داؤد ہیکہِ نہٕ یتہِ اژِتھ۔ {سونچِتھ...: یا یہ ونُن زِ داؤد کرِ نہٕ وغیرہ}\n7.\\tبہر حال رٔٹ داؤد صییونُک مضبوٗط: یۅہے شہر چھہ داؤد۔ \n8.\\tتہٕ داؤدن ووٚن تمہِ دۅہ، یُس یُس گٹہِ تام واتان چُھ، یُس داؤد سٕندِس روحس سٍتـ̡ نفرت کرن وٲلِس تہٕ لنگڑن تہٕ انہِ ہُند مارٕ دِیہِ، سُہ گژھہِ سردار تہٕ کپتان}۔ تێمہِ مۅکھہ وۆن، انہِ تہٕ لنگڑۍ گژھن نہٕ گرس مَنٛز اژُن۔ {تێلہِ...: یا کیازِ تِمو اوس ونمُت زِ انہِ تہٕ لنگڑن تہِ، سُہ گژھِ نہٕ سُہ\n9.\\tیێلہِ اوس داؤد قعلس مَنٛز روزان، تہٕ وونُن اتھ داؤد سُند شہر۔ تہٕ داؤد بنوو میلو پیٹھٕ تہٕ أنٛدرِم کُن۔ \n10.\\tتہٕ داؤد گۆو تہٕ بوٚڈ تہٕ لشکرن ہُند خداوند اوس أمِس سٍتـ̡ سٍتـ̡ ۔ {گۆو...: ہیب۔ گۆو گۆو تہٕ بڑاوُن}\n11.\\tتہٕ صور کِس بادشاہ ہیرمن سوُزۍ داؤدس نِش قاصد تہٕ دیودار کُلۍ، تہٕ چھان تہٕ معمار تہٕ تِمو بنوو داؤدس اکھ مکانہٕ۔ {معماری: حب۔ دیوار کِس کٔنہِ ہٕندِس کٔنِس سٍتـ̡ کٔرِتھ}\n12.\\tتہٕ داؤدس وُچھ زِ خداوند چُھ سُہ اسرٲیلِس پیٹھ بادشاہ مقرر کورمُت، تہٕ تٔمۍ کٔر پننین لوکن ہٕندِ خٲطرٕ پَنٕنـ̡ بادشاہت تھزراونہٕ۔ \n13.\\tتہٕ داؤد نیو ہیبرون پیٹھٕ یِنہٕ پتہٕ یروشلم منزٕ بییہ لونڈی تہٕ زنانہٕ، تہٕ داؤدس ٲس توتہِ نیچوۍ تہٕ کورِ زامٕتۍ۔ \n14.\\tتہٕ یِم چھِ تِمن ہٕندِ ناو یِم یروشلمس مَنٛز زامٕتۍ ٲسۍ۔ شموعہ، تہٕ شوباب، تہٕ ناتھن، تہٕ سلیمان، \n15.\\tاِبہار تہٕ الیشوا تہٕ نیفیگ تہٕ یافیہ، \n16. تہٕ الیشما، تہٕ الیاڈا، تہٕ ایلیفلیٹ۔ \n17. مگر ییلہ فلسطینیو یہ بوز زِ تِمو چُھ داؤد اسرٲیلِس پیٹھ بادشاہ مسح کورمُت، سٲری فلسطینی آیہِ داؤد سٍتـ̡ ژھانڈنہٕ خٲطرٕ۔ تہٕ داؤد بوز تہٕ ووت داؤدس کُن۔ \n18.\\tفلسطینی تہِ آیہ تہٕ پھٔہلِتھ وادی رفایمس مَنٛز۔ \n19.\\tتہٕ داؤدَن پرژھ رٔبِس نِش زِ بہٕ گژھٕ فلسطینن نِش؟ کیا ژٕ کٔرِکھ تِم میٲنِس اتھس مَنٛز؟ تہٕ خداوند ووٚن داؤدَس زِ ہیوٚر گژھُن، تِکیازِ بہٕ کَرٕ بلاشبہٕ فلسطینی پننِس اتھس مَنٛز۔ \n20.\\tتہٕ داؤد آو بعلپیرازمس نِش، تہٕ داؤدَن دِژ تِمن اَتہِ تہٕ وونُن، خداوند چُھ میانہِ برونہہ کُن میانین دُشمنن پیٹھ پھُٹمُت، یِتھ کٔنۍ آبہٕ پھُٹُن۔ تێمہِ کِنۍ ووٚن تٔمۍ اَتھ جایہِ ہُند ناو بَعلپیرازم۔ {بعلپرزم: یعنی دُبارن ہُند میدان}\n21.\\tتہٕ تتہِ ترٲوۍ تِمو پنٕنۍ شکلہٕ، تہٕ داؤد تہٕ تٔمۍ سٕندِس نفرو زٲلۍ۔ {زٲلِمُت...: یا نِتھ نِن}\n22. تہٕ فلسطینی آیہِ بییہِ اکہِ لٹہِ تہٕ پھٔہلِتھ وادی رِفیمس مَنٛز۔ \n23.\\tتہٕ ییلہ داود خداوند سٕندِس پرژھہٕ وُچھ، تٔمۍ ووٚن زِ ژیہ گژھ نہٕ ہیوٚر کھسُن۔ {مگر} تِمن پَتہٕ کُلِس پٔتِھہ اَنِتھ تہٕ تِمن پیٹھ وٲتِو شہتوت کُلِس پیٹھ۔ \n24.\\tتہٕ یێلہِ ژے شہتوت کُلٮ۪ن ہٕندِس تینتٲلِس مَنٛز گَژھنٕچ آواز بوٗزِو، تێلہِ گژھہِ تۅہہِ پَنُن پان بہتر، تکیازِ تیلہِ گژھہِ خداوند ژے برونہہ کُن نیرِ، فلسطینن ہٕندِس لشکرس مارنہٕ خٲطرٕ۔ \n25. تہٕ داؤد کٔر یۅہے کٔرِتھ، یُتھ زن خداوند أمِس حُکُم اوس دِتمُت۔ تہٕ ژے گیزرس نِش یِنہٕ وٲلِس فلسطینس پیٹھ مارُن۔ {گیبا: تہِ چُھہ گیبیون}","1.\\tدُبارٕ کٔر داؤد اِسرٲیلٕکۍ سارِنٕے ژارنہٕ آمٕتۍ {انسان} جمع کٔرِتھ ترہ ساس۔ \n2. تہٕ داؤد ووٚتھ، تہٕ گۆو تِمن سارِنٕے لُکن سٍتـ̡ یِم أمِس سٍتـ̡ یہوداہ کِس بعل پیٹھٕ ٲسۍ، تتہِ نِش خدایہِ سُند صندوق تُلنہٕ خٲطرٕ، یٔمِس ناوُک ناو لشکرن ہٕندِس خداوند سٕندِ ناوٕ سٍتـ̡ وننہٕ یوان چُھ، یُس کرُبِمن درمِیان روزان چُھ۔ {بعلے: یا، بعلہ، یعنی کرجاتجیریم} {یٔمۍ سُند ناو...: یا، یێمہِ ناو، حتیٰ کہ لشکرن ہُند ناو تہِ اوس وننہٕ آمُت}\n3.\\tتہٕ تِمو ترٛوو خدایہ سٕنز صندوق أکِس نٔوِس گاڑِس پیٹھ، تہٕ أنِکھ ابیناداب سٕندِ گرٕ منزٕ یُس گبیعہس مَنٛز {اوس} اوس، تہٕ عزا تہٕ احیو، ابیناداب سٕندِ نیچوۍ، نٔو گاڑِ لٔگِتھ۔ {سیٹ: حب۔ سوارِ خٲطرٕ بناونہٕ آمُت} {گِبعہ: یا، بال}\n4.\\tتہٕ تِمو أنۍ یہِ ابیناداب سٕندِ گرٕ منزٕ یُس خدا سٕندِس صندوقس سٍتـ̡ {اوس} گِبعاہس مَنٛز، تہٕ آہیو گۆو صندوقہٕ برونہہ کُن۔ {سٍتـ̡: عبرانی۔ سٍت}\n5. تہٕ داؤد تہٕ سارِنٕے اِسرٲیلِیَن گِندُکھ خداوند سٕندِ برونہہ کُن پرٮ۪تھ قٕسمٕکۍ لٔکرِ سٍتـ̡ ، حتیٰ کہ ہارپن پیٹھ، تہٕ زبورن پیٹھ، تہٕ ٹمبرن پیٹھ، تہٕ کارنیٹن پیٹھ، تہٕ کُنہِ کُنہِ پیٹھ۔ \n6. تہٕ ییلہ تِم ناچون سٕندِس تھِرِس پیٹھ وٲتۍ، عُزاہن ترووُن خدایہ سٕندِس صندوقس کُن اتھہٕ، تہٕ رٔٹِتھ تھپھ۔ تکیازِ بیلن ہِش ہِلٲوِتھ {یہ}۔ {ناچون: یتھ چِڈون تہِ ونان چھِ} {ہِلٲوِتھ: یا ٹھوکر}\n7.\\tتہٕ خداوند سُند غصہٕ گۆو عزاہَس سٍتـ̡ دِنہٕ۔ تہٕ خداین دِژ تٔمِس اَتہِ {تسٕن} غلطی خٲطرٕ۔ تہٕ تَتہِ موٗد سُہ خدایہ سٕندِ صندوقہٕ سٍتـ̡ ۔ {غلطی: یا، جلدبازی}\n8.\\tتہٕ داؤد گوٚو ناراض، تکیازِ خداوند اوس عزاہَس پیٹھ خلاف ورزی کٔرمٕژ، تہٕ تٔمۍ ووٚن از تام پیریزہ جایہِ ہُند ناو۔ {بنووُن: حب۔ پھُٹُن} {پیریزوزا: یعنی عزاہٕچ خلاف ورزی }\n9. تہٕ داؤد اوس تمہِ دۅہہ خداوند سٕندِ نِش کھوژان، تہٕ وونُن، خداوند سُند صندوق کِتھ کٔنۍ واتہِ میانہِ نِش۔ \n10.\\tتێلہِ نِیوو نہٕ داوُد سٕندِس صندوقس پانس کُن داؤد سٕندِس شہرس مَنٛز، مگر داؤد نِیوو سُہ اوبیدیدوم سٕندِس گَرَس مَنٛز۔ \n11.\\tتہٕ خداوند سُند صندوق روٗد اوبیڈوم سٕندِس گرس مَنٛز تریہ ریتھ جٲری: تہٕ خداوند کٔر اوبیڈوم تہٕ تٔمۍ سٕندِس سارِنٕے گرس برکت ۔ \n12.\\tتہٕ بادشاہ داؤدس وونُن زِ خداوند چُھ اوبیڈوم سٕندِس گرس تہٕ تٔمِس سٍتـ̡ برکت دِژمٕژ، یێمہِ سٍتـ̡ خدایہِ سٕندِ صندوقہٕ سٍتـ̡ ۔ چنانچہ داؤد گۆو تہٕ تُل خدایہِ سُند صندوق اوبیڈوم سٕندِ گرٕ پیٹھٕ خوشی سان داؤد سٕندِس شہرس مَنٛز۔ \n13. تہٕ یہٕ اوس {یِتھ} زِ ییلہِ تِم خداوند سٕندِ صندوقس نِش شیہ قدم پٔکِتھ، تٔمۍ کٔر بیل تہٕ موٚٹۍ قربان۔ \n14. تہٕ داؤد اوس خداوند سٕندِس برونہہ کُن نژان۔ تہٕ داؤد اوس کُنہِ سٍتـ̡ لٲگِتھ نژان۔ \n15. یێمہِ پٲٹھـ̡ داؤد تہٕ سارِنٕے اِسرٲیلِیَن ہٕندِس گرس سٍتـ̡ تُل خداوند سُند صندوق کرٛٮ۪کہٕ دِتھ تہٕ بُرٕچ آوازٕ سٍتـ̡ ۔ \n16. تہٕ یێلہِ خداوند سُند صندوق داؤد سٕندِس شہرس مَنٛز آو، میخال ساؤل سٕنزِ کورِ وُچھ دارِ منزہ تہٕ وُچھن بادشاہ داوود سٕندِ برونہہ کُن وۄٹھ دِوان تہٕ نژان وُچھان۔ تہٕ تٔمۍ کٔر أمِس دِلس منز حقارت ۔ \n17.\\tتہٕ تِمو اوٚن خداوند سُند صندوق، تہٕ تھووُن تٔمۍ سٕنزِ جایہ، خیمہ کِس درمِیان یُس داؤدُن امہِ خٲطرٕ دِژمُت اوس، تہٕ داؤدَن کٔر خداوند سٕندِ برونہہ کُن دزنہٕ نذرانہ تہٕ امن پیش کرنہٕ۔ {پِچ: حب۔ پھٔہلِتھ}\n18. یێلہِ داؤد سٕندِ دَزنہٕ نذرانہ تہٕ امن ہٕندِ نذرانہ پیش کرنہٕ ختم کٔر، تٔمۍ کٔر لُکن ہٕندِس رب سٕندِ ناوٕ سٍتـ̡ برکت۔ \n19.\\tتہٕ تٔمۍ کٔر سارنٕے لُکن منز، حتیٰ کہ سارِنٕے اِسرٲیلِس منز، زنانن تہٕ مردن سٍتـ̡ تہٕ پرٮ۪تھ أکِس سٍتـ̡ بٔرِتھ تہٕ اَکھ اَصٕل ماز تہٕ شرابُک جھنڈٕ۔ تێوَے گٔیہِ سارِنٕے لُکھ سارِنٕے أکِس سٕندِس گَرَس کُن۔ \n20. اَمہِ پَتہٕ آو داؤد پننِس گرس برکت دِنہٕ خٲطرٕ واپس۔ تہٕ ساؤل سٕنز کورِ میخال دراو داؤدس سمکھنہٕ خٲطرٕ، تہٕ وونُن، از کل اوس اسرٲیلُک بادشاہ کوتاہ شان اوس، یُس از تام پننین خدمتگارن ہٕنزِ دٲیرین ہٕنزِ نظرِ منز پنُن پان ظٲہر کٔرِتھ، یِتھ کٔنۍ اکھ بےٚ شرم سٍتـ̡ پنُن پان بے شرمی سان ظٲہر کران چُھ! {بے شرمی سٍتۍ: یا، کھلہٕ پٲٹھۍ}\n21.\\tتہٕ داؤدن ووٚن میکالس، {یہِ} اوس خداوند سٕندِس برونہہ کُن، یٔمۍ میہ پننِس مٲلس برونہہ تہٕ تٔمۍ سٕندِس سارِنٕے گرس برونہہ کُن ژٲرمُت، یُس بہٕ خداوند سٕندِس لُکن ہُند بادشاہ بنوو، یێمہِ مۅکھہ بہٕ کرٕ خداوند سٕندِس برونہہ کُن گِندُن۔ \n22.\\tتہٕ بہٕ آسہٕ توتہِ یِتھٕ کھۅتہٕ زیادٕ بدکار تہٕ پننہ نظرِ ہٕندِس نظرس منز تہٕ یِمن ہٕنزِ کتھ کٔرمٕژ چھےٚ، تِمن ہٕندِس بارس منز گژھہٕ بہٕ عزت کرنہٕ۔ {دِن...: یا میانین خادمَن ہٕنزِ دٲیرِس}\n23. تَمہِ کِنۍ اوس نہٕ ساؤل سٕنزِ کورِ میخالس مرنہٕ کہِ دۅہہٕ تام کانٛہہ تہِ شُر۔","1. تہٕ سپُد ییلہ بادشاہ پننِس گرس منز بِہتھ تہٕ خداوند اوس تس پننین سارِنٕے دُشمنن نِش آرام دِژمُت۔ \n2.\\tیہ زِ بادشاہن ووٚن ناتھن پیغمبرس زِ وُچھو، بہٕ چُھس دیودار کِس أکِس گرس مَنٛز روزان، مگر خدایہ سُند صندوق چھُ پردَن مَنٛز روزان۔ \n3.\\tتہٕ ناتھنن ووٚن بادشاہس زِ گژھ، یُس تہِ پننِس دِلس مَنٛز چُھہ یُس {چُھ} چُھ، تکیازِ خداوند چُھ توے سٍتـ̡ ۔ \n4.\\tتہٕ تمہِ رٲژ سپد یہ زِ خداوند سُند کلام آو ناتھنس نِش وونُن، \n5.\\tگژھ تہٕ وَنُن میٲنِس خادم داوُد، یِتھٕ پٲٹھۍ چُھ خداوند ونان زِ کیا ژٕ بناوٕ میانہِ خٲطرٕ اکھ مکانہٕ یَتھ مَنٛز روزنہٕ خٲطرٕ؟ {میون خادم...: ہیب۔ میٲنِس خادمَس سٍت، داؤدُس سٍتـ̡\n6. یێلہِ بہٕ چُھس نہٕ کُنہِ تہِ گرس مَنٛز روزمُت، یێلہِ بہٕ یێلہِ بہٕ یێلہِ تہِ أسـ̡ بنی اِسرٲیلـ̡ مصرہٕ منزٕ نِش پرورش کٔرِمٕژ، از تام چُھس نہٕ أکِس خیمہ تہٕ خیمہ خانس مَنٛز پکان ۔ \n7.\\tتِمن سارِنٕے جاین یَتھ مَنٛز بہٕ سارِنٕے بنی اِسرٲیلِس سٍتـ̡ پکان چُھس، یێمِس میہ پننین لوکن اسرٲیلس کھٮ۪وان دِنُک حُکُم دِیُتمُت چھُ، یہِ ونُن زِ ژے کیازِ بناوو نہٕ میانہِ خٲطرٕ دیودارُک مکانہٕ۔ {کانہہ تہِ...: کانہہ تہِ قاضی}\n8.\\tتێلہِ چُھہ تێلہِ وَنُن میٲنِس خادم داوڈس یِتھٕ پٲٹھۍ، یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہٕندِس خداوند سٍتـ̡ ونان، بہٕ چُھس ژے کۅکرِ پى۪ٹھہٕ پى۪ٹھہٕ پى۪ٹھ، میانین لوکن پى۪ٹھ، اسرٲیلـ̡ پى۪ٹھ۔ پَتہٕ پى۪ٹھہٕ پى۪ٹھ}\n9. تہٕ بہٕ اوسُس ژے سٍتـ̡ ییتہِ تہِ ژے گٔژِھھ، تہٕ ژے کٔرِکھ تُہٕندِس سارِنٕے دُشمن ہٕندِس ناوس نِش ژٹِمُت، تہٕ کورُکھ ژے اکھ بٔڈ ناو، یُس زمینس مَنٛز {چھُ} عظیم {انسان} ہٕندِس ناوُک پٲٹھۍ۔ {منز...: ہیب۔ تُہٕندِس بُتھِس پیٹھ}\n10. امہِ علاوٕ کَرٕ بہٕ پننین لوکن اسرٲیلـ̡ خٲطرٕ اکھ جاے مُقرر، تہٕ تِم کٔرِتھ کٔرِتھ یُتھ تِم پنٕنـ̡ کُنہِ جایہ روزن، تہٕ یێلہِ نہٕ یێلہِ پٲٹھـ̡ روزِ۔ نۂ بد کار بچہٕ یِمن سٍتـ̡ گۅڈٕ پٲٹھـ̡ تِمن دِنہٕ یِن، \n11. تہٕ یِتھٕ پٲٹھـ̡ یێلہِ میہ پننین لوکن اسرٲیلـ̡ پیٹھ قاضن ہُند حُکُم دِیُتمُت، تہٕ چُھکھ ژے سارِنٕے دُشمنن نِش آرام دِژمُت۔ تہٕ خداوند چُھ ژے ونان زِ سُہ بناوِ ژے اکھ گرٕ۔ \n12. تہٕ یێلہِ تُہٕندِس دۅہہٕ پوٗرٕ گَژھن، تہٕ ژٕ پنہٕ نِس مٲلِس سٍتـ̡ شۄنگنہٕ یِن، بہٕ کَرٕ تُہٕندِس پَتہٕ تُہٕندِس بُلِس سٍتـ̡ قٲیِم۔ \n13. سُہ بناوِ میانہِ ناوٕ خٲطرٕ اکھ مکانہٕ، تہٕ بہٕ کرٕ تٔمۍ سٕنزِ سلطنتُک تخت ہمیشہٕ خٲطرٕ قٲیم۔ \n14. بہٕ بنہٕ تٔمۍ سُند مول، تہٕ سُہ بنہٕ میون نیچو۔ اگر سُہ بدکار کرِ، بہٕ دِیہٕ أمِس انسانن ہٕنزِ لٔرِ تہٕ انسانن ہٕندِس بچن ہٕنزِ پٹیو سٍتـ̡ سزا۔ \n15. مگر میٲنۍ رحمت گژھِ نہٕ أمِس نِش ژٔلِتھ، یِتھ کٔنۍ مے ساؤلس نِش نِش یُس میہ ژےٚ برونہہ کُن تھوومُت اوس۔ \n16. تہٕ تُہُند گرٕ تہٕ تُہٕنٛز بادشاہت گژھہِ ہمیشہٕ خٲطرٕ قایم کرنہٕ۔ \n17.\\tیِمو سارِنٕے کلامَو مُطٲبِق تہٕ یِمن سارِنٕے وژنن مُطٲبِق کٔر ناتھن داؤدس سٍتـ̡ کتھ کرنہٕ۔ \n18.\\tاَمہِ پَتہٕ ووت بادشاہ داؤد، تہٕ بیوٹھ خداوند سٕندِس برونہہ کُن، تہٕ ووٚنُن، اے خداوند خدایہِ کُس چُھس؟ تہٕ میون گرٕ کیا چُھ، یُس ژے میہ وُنیُک تام أنِمُت چھُ؟ \n19.\\tتہٕ یہ اوس تۅہہِ ہٕندِس نظرس منز وُنہِ تہِ لۅکٹ چیز، اے خدایہ۔ مگر ژے چھے واریاہس کالس پننِس خادم سٕندِس گرس متلق تہِ کتھ کٔرمٕژ۔ تہٕ کیا یہ چُھہ انسان سُند طریقہٕ، اے خدایہ؟ {طریقہٕ: ہیب۔ شریعت}\n20. تہٕ داؤد کیاہ ہیکہِ ژے بییہِ ؤنِتھ؟ تِکیازِ چُھہ خداوند خدایہ، پنہٕ نِس بندس زانان۔ \n21.\\tپننہِ کلامہٕ خٲطرٕ، تہٕ پننہِ دِلہٕ مطٲبق، کٔر ژے یِم سٲری بٔڈ کٲم کٔرمٕژ، یُس پنہٕ نِس خادمس زاننہٕ مۅکھہٕ۔ \n22.\\tتێلہِ چُھہ تۅہہ عظیم ، اے خدایہ، تێلہِ چُھہ نہٕ ژے ہیو کانہہ تہِ خدا، تہٕ نہ چُھہ تۅہہِ سٍتـ̡ کانہہ خدا، یُس اسہِ پننیو کنو سٍتـ̡ بوزمُت چُھ۔ \n23.\\tتہٕ زمینس مَنٛز کُس قوم چُھہ تُہندِ لُکہٕ ہِش یُس تُہٕندِس لُکہٕ سٍتـ̡ چُھہ یُس خدایہِ پانس خٲطرٕ أکِس لُکہٕ خٲطرٕ چھُ، تہٕ تٔمِس ناو دِنہٕ خٲطرٕ، تہٕ تۅہہِ ہٕندِ خٲطرٕ بٔڈ تہٕ خوفناک کٲم کرنہٕ خٲطرٕ، تُہٕندِس قومس تہٕ تِہندین دیوتاہن سٍتـ̡ یُس تۅہہِ سٍتـ̡ مصر نِش تہٕ تِمن ہٕندِس دیوتاہن نِش نجات دِنہٕ خٲطرٕ۔ \n24. تِکیازِ ژے چُھہ پَنٕنـ̡ پَنٕنـ̡ لُکہٕ اِسرٲیلـ̡ ہمیشہٕ خٲطرٕ اکھ قوم بٔنِتھ تہٕ چُھہ، خداوند، تِہُند خدا بنیوو۔ \n25. تہٕ وۅنۍ اے خدایہ، یُس کلام ژے پننِس بندس مُتلق تہٕ تٔمۍ سٕندِس گرس مُتلق کتھ کورمُت چُھ، سُہ کرُن ہمیشہٕ خٲطرٕ قٲیم تہٕ یُس ژے وَنُن چُھ، سُہ کرُن یُس تۅہہ وَنُن چُھ۔ \n26. تہٕ تُہند ناو گژھہِ ہمیشہٕ خٲطرٕ بڑاونہٕ یُن، یہِ ؤنِتھ زِ لشکرن ہُند رب چُھہ اسرٲیلُک خدا، تہٕ تُہٕندِس خادم داؤد سُند گرٕ گژھہِ توے برونہہ کُن قایم کرنہٕ۔ \n27. اے لشکرن ہٕندِس خداوند، اسرٲیلُک خدا، چُھہ پننِس بندس وحی کورمُت زِ بہٕ بناوٕ ژے اکھ مکانہٕ، تێمہِ مۅکھہٕ چُھہ تۅہہِ سٕندِس دِلس مَنٛز یہِ دُعا دُعا دِنہٕ خٲطرٕ لبنہٕ آمُت۔ {ظٲہر سپُد: عبرانی۔ کَن کھولُن}\n28. تہٕ وُن، اے خدایہ، تہٕ تُہٕندِس کلامَس چھُ پٔزۍ پٲٹھۍ، تہٕ ژے چُھکھ پننِس خادمَس سٍتـ̡ یێلہِ نیکی ہُند وعدٕ کورمُت: \n29. تێلہِ گژھہِ وۅنۍ ژے پننہِ بندہ سٕندِس گرس برکت دِن، یُتھ روزِ تۅہہِ برونہہ کُن ہمیشہ روزُن: تکیازِ اے خدایہ، ژے چھے کتھ کٔرمٕژ، تہٕ پننہِ برکتہٕ سٍتـ̡ گژھہِ پننہِ بندہ سُند گرٕ ہمیشہٕ خٲطرٕ بابرکت روزُن۔ {یہِ گژھہِ...: حب۔ ژٕ گژھ خوش تہٕ برکت دِن}","1.\\tتہٕ امہ پتہ سپد یہ زِ داؤدن دیت فلسطینن تہ دپان تہ دپان فلسطینن ہندِ اتھہ نشہِ نِش نِش نِتھ تہ داؤد نِن میتھیگامہ فلسطینن ہٕندِ اتھہٕ نِش نیبر۔ {میتھیگامہ: یا، اماہ سٕنز لگام}\n2.\\tتہٕ تٔمۍ دِژ موآب تہٕ لٔگِتھ لٔگِتھ تہٕ دِژُن زٔمیٖنس پیٹھ۔ دۅن لٲنہٕ سٍتـ̡ تہٕ دِژُن سُہ مارنہٕ خٲطرٕ، تہٕ أکِس پوٗرٕ لٲرِس سٍتـ̡ زِندٕ تھاونہٕ خٲطرٕ۔ تہٕ {یِتھٕ پٲٹھۍ} موابی بنییہِ داؤد سٕندِ خدمتگار، {تہٕ} أنۍ تحفہٕ۔ \n3.\\tداؤدن دِژ زوبہ کِس بادشاہ رحوب سٕندِس نیچوِس حدادزر تہِ ییلہ سُہ دریائے فرات کِس کُن پنُن سرحد بازیافت کرنہٕ خٲطرٕ گٔیہِ۔ {ہدادیزر: یا، ہداریزر}\n4. تہٕ داؤد نِش نِش اکھ ساس {رتھ} تہٕ ستھ ہتھ گُرۍ سوار، تہٕ وُہ ساس پیدل تہٕ داؤد کٔر تمام رتھ {گُر}، مگر تمن منز تھووُن ہتھ رتھ۔ {منز...: یا، پننین رتھن منز}\n5.\\tییلہ دمشقٕکۍ شامی زوبہ کِس بادشاہ حدادزر سٕندِس مددتہٕ خٲطرٕ آیہ، داؤدن مارۍ شامی زٕ وُہ ساس نفر۔ \n6. پَتہٕ بَنوو داؤد دمشق کِس شامس مَنٛز چھاونی: تہٕ شامٕکۍ بنییہِ داؤد سٕندِ نوکر، {تہٕ} أنۍ تحفہٕ۔ تہٕ خداوند تھوو داؤد یَتہِ تہِ گٔیہِ۔ \n7. تہٕ داؤد نیو سونہٕ سٕنز ڈھال یُس حدادیزر سٕندِس نوکروں پیٹھ ٲس، تہٕ أنِن یروشلم۔ \n8.\\tتہٕ بیتاہ پیٹھٕ تہٕ بیروتھایی پیٹھ، ہدادیزر کِس شہرس پیٹھ، بادشاہ ڈیوڈس نیو واریاہ زیادٕ پیتل۔ \n9.\\tییلہ حمتُک بادشاہ توئی بوز زِ داوُد چھُ حدادزر سٕندِس سارِنٕے لشکرس مارمُت، \n10.\\tتمہِ پتہ سوز توئی پنُن نیچو جورام بادشاہ داوڈس نِش، تٔمِس سلامی دِنہٕ خٲطرٕ، تہٕ أمِس دُعا دِنہٕ خٲطرٕ، تکیازِ تٔمۍ اوس حدادیزرس سٍتۍ جنگ کورمُت، تہٕ مارُن تٔمِس سٍتـ̡ ۔ تہٕ {جورم} أنۍ پانس سٍتـ̡ رۄپہٕ ہٕندِ بانہٕ، تہٕ سۄنہٕ سٕندِ بانہٕ تہٕ پیتلٕکۍ بانہٕ: {Joram: تہٕ چُھہ Hadoram} {سلام...: Heb. أمِس سٍتـ̡ پرژھہٕ امن} {جنگ گٔیہِ...: حب۔ اوس جنگُک آدم} {اَن...: حب۔ تٔمۍ سٕندِس اتھس مَنٛز}\n11.\\tیُس بادشاہ داوُد تہِ اوس رۅپہٕ تہٕ سۄنہٕ سٍتـ̡ خداوند سٕندِ خٲطرٕ وقف کورمُت، یُس تٔمۍ سارِنٕے قومن ہٕندِ خٲطرٕ وقف کورمُت اوس۔ \n12. شامُک تہٕ موآب تہٕ عمون سٕندِس شُرین تہٕ فلسطینی سٕندِس تہٕ عمالیک سٕندِس اولادس سٍتـ̡ تہٕ زوبہ کِس بادشاہ رحاب سٕندِس نیچوِس حدادزر سٕندِس غنیمتُک ۔ \n13.\\tتہٕ داؤد گَٹ اَکھ ناو ییٚلہِ سُہ وادی نوٗنہٕ کِس شامس مَنٛز مارنہٕ نِش واپس آو، {آسنہٕ} ارداہ ساس {انسان}۔ {مارُن: حب۔ تٔمۍ سُند مارُن}\n14. تہٕ تٔمۍ تھوو ایڈومَس مَنٛز چھاوٕ۔ سارِنٕے ایڈومَس مَنٛز تھووُن أمِس چھاوُن، تہٕ یِم سارِوٕے بنییہِ داؤد سٕندِ خادم۔ تہٕ خداوند تھوو داؤد یَتہِ تہِ گٔیہِ۔ \n15. تہٕ داؤد کٔر سارِنٕے اسرٲیلس پیٹھ حکومت۔ تہٕ داؤد کٔر پننین سارنٕے لوکن ہُند فیصلہٕ تہٕ عدل۔ \n16.\\tتہٕ یوعب یُس زرویاہ سُند نیچو اوس، لشکرس پیٹھ۔ تہٕ یہوشافعت، احیلود سُند نیچو {اوس} ریکارڈر؛ {ریکارڈر: یا، یا، یا، تواریخ لیکھن}\n17.\\tتہٕ احیتوبس سُند نیچو زادوک تہٕ ابیاتھر سُند نیچو احیمیلک، {ٲس} پادٕرۍ۔ تہٕ سریاہ {اوس} کاتب۔ {کاتب: یا، سیکرٹری}\n18.\\tتہٕ یہوعیدہ سُند نیچو بنیاہ {اوس ختم} چیریتھیس تہٕ پیلیتھیس دۄشوٕے تہٕ داؤد سٕندِ نیچوۍ ٲسۍ اہم حکمران۔ {اہم حکمران: یا، شہزادٕ}","1. تہٕ داؤد ووٚن زِ کیا ساؤل سٕندِس گرس مَنٛز چھا وُنہِ تہِ کانہہ باقی، یُس بہٕ یوناتھن سٕندِ خٲطرٕ أمِس مہربانی ہٲوِتھ؟ \n2.\\tتہٕ ساؤل سٕندِس گرس مَنٛز اوس اکھ نوکر یٔمِس ناوُک {زیبا} اوس۔ تہٕ ییلہ تمو أمس داؤدس نِش بُلوو، بادشاہن ووٚن تٔمِس {آر} تُہۍ زیبا؟ تہٕ تٔمۍ ووٚن، تُہند خادم۔ \n3. تہٕ بادشاہن ووٚن زِ کیا وُنہِ تہِ چُھہ نہٕ ساؤل سٕندِس گرس منز کانہہ تہِ، یُس بہٕ ہٲوِتھ خدایہِ سٕنز مہربانی ہٲوِتھ؟ تہٕ زیبا ہن ووٚن بادشاہس زِ یوناتھن چُھ وُنہِ تہِ اکھ نیچو، یُس تٔمۍ سٕندِس کھورِ پیٹھ لوٚنگہٕ چُھ۔ \n4.\\tتہٕ بادشاہن ووٚن أمِس کَتہِ چھُ؟ تہٕ زیباہَن ووٚن بادشاہس زِ وُچھِو سُہ چھُ لودبارس مَنٛز امِیَل سٕندِس نیچوِس مَخیٖر سٕندِس گَرَس مَنٛز۔ \n5. پتہٕ سوٗز بادشاہ داوُد تہٕ أنِن سُہ اَمیِل سٕندِس نیچوِس ماکیر سٕندِ گَرٕ منزٕ لودبار پیٹھ۔ \n6.\\tییلہ ساؤل سُند نیچو یوناتھن سُند نیچو میفیبوشیٹھ آو داؤدس نِش، سُہ پیوٚو بُتھِس پیٹھ تہٕ کوٚرُن احترام۔ تہٕ داؤد ووٚن، میفیبوشیتھ۔ تہٕ تٔمۍ دیُت جواب، وُچھ پنُن خادم! {میفیبوشیتھ: یتھ مریبعل تہِ ونان چھِ}\n7. تہٕ داؤدن ووٚن أمِس زِ خوفہٕ نہٕ، تکیازِ بہٕ کرٕ ژے پنٕنِس مٲلہِ سٕندِ خٲطرٕ یٔقیٖنی طور تہٕ ژے پنٕنِس مٲلہِ سٕندِ خٲطرٕ رحمدٲری ہٲوِتھ تہٕ ژے کٔرٕ تُہٕندِس مٲلہِ سٕندِ خٲطرٕ ساؤل سٕنز سارِنٕے زمینہٕ واپس۔ تہٕ ژٕ کٔرٕ میٲنِس دسترس پیٹھ لگاتار روٹی کھٮ۪وان۔ \n8.\\tتہٕ تٔمۍ کٔر پانس نمُت تہٕ ووٚنن، تُہند خادم کیا چُھ، یُس میہ ہیوٗ مٔرِتھ ہوُن وُچھُن؟ \n9. اَمہِ پَتہٕ ووت بادشاہن ساؤل سٕندِس خادمَس زیبا سٕندِس نِش بُلاونہٕ تہٕ وونُن زِ مے چُھس تُہٕندِس آقا سٕندِس نیچوِس ساؤلس تہٕ تٔمۍ سٕندِس سارِنٕے گرس سٍتـ̡ دِژمُت۔ \n10. تێمہِ کِنۍ کٔرِو تُہۍ تہٕ تُہٕندِس نیچوِس تہٕ تُہٕندِس خادمَس سٍتـ̡ زمینہٕ ہٕندِس مۅکھہٕ کھٮ۪نہٕ خٲطرٕ، تہٕ تُہٕندِس آقا سٕندِس نیچوِس مِلہٕ کھٮ۪نہٕ خٲطرٕ کھٮ۪نہٕ خٲطرٕ، مگر میفیبوشیت چُھہ تُہٕندِس آقا سُند نیچو ہمیشہ میانہِ دسترس پیٹھ روٹی کھیوان۔ وۅنۍ ٲسۍ زیبا سٕندِس پنٛداہ نیچوۍ تہٕ وُہ نوکر۔ \n11.\\tاَمہِ پتہٕ ووٚن زیباہَن بادشاہس زِ یُس میانہِ آقا بادشاہن پننِس خادمَس حُکُم دِیُتمُت چھُ، تِتھۍ پٲٹھۍ کرِ تُہند خادم۔ یوتام میفیبوشیث سُہ چُھہ بادشاہ سٕندِس نیچوِس سٍتـ̡ کھٮ۪نہٕ یِوان۔ \n12.\\tتہٕ میفیبوشیتھس اوس اکھ جوان نیچو، یٔمۍ سُند ناو اوس میخا۔ تہٕ یِم سٲری زیبا سٕندِس گرس مَنٛز روزان ٲسۍ، تِم ٲسۍ میفیبوشیتھس سٕندِ نوکر۔ \n13.\\tیێلہِ اوس میفیبوشیتھ یروشلمس منز روزان، تکیازِ سُہ اوس بادشاہ سٕندِس دسترس پیٹھ لگاتار کھیوان۔ تہٕ اوس دۅشوٕے کھۅرن لوٚنگ۔","1. تہٕ امہِ پتہٕ سپُد یہِ زِ عمون سٕندٮ۪ن شُرین ہُند بادشاہ مٔرِتھ تہٕ تٔمۍ سُند نیچو حنون کٔر أمِس بدلہٕ حکوٗمت۔ \n2. اَمہِ پَتہٕ ووٚن داؤد، بہٕ کَرٕ نہش سٕندِس نیچوِس حنون سٍتـ̡ مہربانی کٔرِتھ، یِتھٕ کٔنۍ تٔمۍ سٕندِس مٲلہِ سٕندِس مٲلہِ سٍتـ̡ مہربانی کٔرِ۔ تہٕ داؤد سٕندِ نوکر آو أمِس مٲلہِ سٕندِ خٲطرٕ پننین نوکرَن ہٕندِ اتھہٕ سٍتـ̡ تسلی دِنہٕ خٲطرٕ۔ تہٕ داؤد سٕندِ خادم آیہِ عمون سٕندِس بچن ہٕندِس ملکس مَنٛز۔ \n3.\\tتہٕ عمون سٕندِس اولادَن ہٕندِس شہزادو ووٚن حنون پننِس مٲلکِس سٍتـ̡ زِ تۅہہِ چُھہ پننِس مٲلِس عزت کران، یێلہِ تٔمۍ سُہ چُھہ تۅہہِ نِش تسلی دِنہٕ وٲلِس سٍتـ̡ سوزمُت؟ کیا داؤد چُھہ نہٕ پَنٕنـ̡ نوکر سوٗزمٕتـ̡ تۅہہِ نِش شہرٕچ تلاشہٕ کرنہٕ خٲطرٕ، تہٕ اَتھ ہُند جاسوسی کرنہٕ خٲطرٕ، تہٕ اَتھ ہُند تختہٕ والہٕ دِنہٕ خٲطرٕ؟ {سونچ...: حب۔ تُہنزِ نظرِ منز چُھ داؤد}\n4. اَمہِ مۄکھٕ کٔرٕن حَنوُن داؤد سٕندِس نوکر تہٕ تِہٕندِس نٮ۪صٕف داڑھ ژٹِتھ ژٔٹِتھ تہٕ ژٔٹِن تِہٕندِس پَلَس منز، تہٕ ژٔٹِن تِمن ہٕندِس کُنہِ تہٕ ژٔٹِتھ تہٕ ژٔٹِتھ ۔ \n5.\\tییلہ تِمو داؤدس ووٚن، تٔمۍ سوٗز تِمن سمکھنہٕ خٲطرٕ، تکیازِ مرد ٲسۍ واریاہ شرمندہ گٔمٕتۍ، تہٕ بادشاہن ووٚن، یێرِحہس مَنٛز روزُن یوٚت تام تُہٕنز داڑھ بٔڈِتھ تہٕ یێلہِ واپس۔ \n6.\\tییلہ عمون سٕندیو اولادو وُچھ زِ تِم داؤدس برونہہ کنہِ بدبودار چِھہ، عمون سٕندیو اولادو سوٗزۍ بیتھرہوبٕکۍ شامی تہٕ زوبا ہٕندِس شامی تہٕ زوبا کِس شامی تہٕ بادشاہ معاکہ سٕندِ ساس نفر تہٕ اشتوب سٕندِ باہ ساس نفر۔ {اشتوب: یا توبٕکۍ مرد}\n7.\\tتہٕ ییلہ داؤدس یہِ خبر بوٗز، تٔمۍ سوٗزُن یوآب تہٕ سارِنٕے طاقتور نفرن ہُند لشکر۔ \n8.\\tتہٕ عمون سٕندِ شُرۍ دراو تہٕ دروازس منز اژنہٕ وِزِ لٔگِتھ جنگہٕ صفہٕ۔ تہٕ زوبا تہٕ رہوبٕکۍ شامٕکۍ تہٕ اشتوب تہٕ معاکہ ٲسۍ پانہٕ پانہٕ میدانس مَنٛز۔ \n9.\\tییلہ یوآبن وُچھ زِ جنگُک برونہہٕ حصہ چُھ تس برونہہ تہٕ پتھ کُن، تٔمۍ ژٲر سارِوٕے سارِوٕے ژٲر {انسان} تہٕ تھووُن شامس خلاف صفہٕ۔ \n10.\\tتہٕ باقٕے لُکھ یِم أمۍ پننِس بٲیِس ابیشایی سٕندِس اتھس مَنٛز دِنہٕ، یُتھ سُہ عمون سٕندِس شُرین خٕلاف صفہٕ کٔرِتھ۔ \n11.\\tتہٕ ووٚن یێلہِ شامٕکۍ بچہٕ میانہِ خٲطرٕ زیادٕ مضبوط آسن، تیلہِ کٔرِو ژے میانہِ مدد۔ \n12. اصل ہمت تھاوُن، تہٕ أسۍ کرو پننین لوکن ہٕندِ خٲطرٕ تہٕ پننِس خدایہ سٕندِ شہرن خٲطرٕ انسانس سٍتـ̡ گِندُن، تہٕ خداوند کرُن سُہ یُس أمِس اصل باسان۔ \n13.\\tتہٕ یوآب ووت نزدیک تہٕ أمِس سٍتـ̡ یِم لُکھ أمِس سٍتـ̡ شامِس خٕلاف جنگس مَنٛز گٔیہِ، تہٕ تِم ژٔلِتھ أمِس برونہہ کُن۔ \n14.\\tییلہ عمون سٕندیو شُرۍ وُچھ زِ شامٕکۍ لٔج ژٔلِتھ تہٕ ژٔلِتھ شہرس مَنٛز۔ یێلہِ آو یوآب عمون سٕندِس شُرِیو نِش واپس، تہٕ آو یروشلم۔ \n15.\\tتہٕ ییلہ شامیو وُچھ زِ تِم چھِ اسرٲیلِس برونہہ کُن مارنہٕ آمٕتۍ، تِمو کٔر پان اِکہٕ وٹہٕ۔ \n16.\\tتہٕ حداریزرن سوٗز، تہٕ أنِن شامی یِم دریاوس اپارِ ٲسۍ، تہٕ تِم آیہِ ہیلام۔ تہٕ شوباخ ہدارزر سٕندِس فوجُک کپتان {گٔیہ} تِمن برونہہ کُن۔ {دٔریاو: یعنی فرات} {شوباخ: یا، شوفاخ}\n17.\\tتہٕ ییلہ یہ داؤد وننہٕ آو، تٔمۍ کٔر سارِنٕے اسرٲیلِس جمع تہٕ اردن کِس پٲٹھۍ، تہٕ ووت ہیلام۔ تہٕ شامی لوٚگ داؤدس خلاف صفہٕ کھڑا تہٕ لوٚگ أمِس سٍتـ̡ ۔ \n18.\\tتہٕ شامٕکۍ ژٔل اسرٲیلِس برونہہ کُن۔ تہٕ داؤدن مارۍ شامی ہٕندِ سَتھ ہتھ رتھ، تہٕ ژتٲجی ساس گُرۍ سوار، تہٕ دِتُن تِہندِ لشکرُک کپتان شوباخس مارُن، یُس تتہِ موٗد۔ {گُرۍ سوار: پیدل تہِ ونان چھِ}\n19.\\tتہٕ یێلہِ سارِنٕے بادشاہو یِم حداریزٕکۍ خادم ٲسۍ، تِمو کٔر اسرٲیلِس سٍتـ̡ صلح تہٕ کٔرٕکھ تِمن ہٕنزِ خدمت۔ تێلہِ گۆو شامٕکۍ شُرین ہٕندِس مددٕ کرنہٕ سٍتـ̡ کھوژمُت۔","1. تہٕ ؤری مۄکلاونہٕ پَتہٕ، ییٚلہِ بادشاہن جنگہٕ خٲطرٕ نیران چُھ، داؤد سوٗز یوآب تہٕ تٔمۍ سٕندِس نوکر پانس سٍتـ̡ تہٕ سارِنٕے اسرٲیلِس سٍتـ̡۔ تہٕ تِمو کٔرِکھ عمونٕکۍ اولاد تباہ تہٕ رَبع ہُند محاصرٕ۔ مگر داؤد روٗد وُنہِ تہِ یروشلمس مَنٛز۔ {پَتہٕ...: عبرانی۔ ؤری کِس واپسس پیٹھ، یا بہارس مَنٛز}\n2.\\tتہٕ ووت شامس سٍتـ̡ زِ داؤد ووت پننہِ بسترہ پیٹھٕ تھوٚد، تہٕ ووت بادشاہ سٕندِس گرٕ کِس چھتس پیٹھ، تہٕ چھتہٕ پیٹھٕ وُچھ أمِس زنانہٕ پان چھلان۔ تہٕ زنانہٕ ٲس سٮ۪ٹھاہ خوبصورت۔ \n3.\\tتہٕ داؤدن سوز تہٕ پرژھ گٲر زنانہِ۔ تہٕ {اَکہ} ووٚن، {اَکہِ} چُھنہٕ یہِ بیت شیبا یُس ایلیام سٕنز کوٗر چُھ، یُس اوریاہ حِتِی سٕنزِ زنانہٕ چُھ؟ {بتشیبع: یا، بتشواہ} {ایلیام: یا عمییل}\n4. تہٕ داؤد سوٗزۍ قاصد تہٕ نِش نِیو۔ تہٕ سۄ آیہِ أمِس نِش، تہٕ سُہ لوٚگ أمِس سٍتـ̡ ۔ تِکیازِ سۄ گٔیہِ پننہِ ناپاکی نِش پاک تہٕ سُہ گٔیہِ پننِس گَرَس واپس۔ {تِکیازِ سُہ ...: یا، تہٕ ییلہ أمِس پان پاک کٔر، بیترِ، سُہ آو واپس}\n5.\\tتہٕ زنانہِ گٔیہِ حاملہٕ، تہٕ سوزُن تہٕ وونُن داؤد، تہٕ وونُن بہٕ چُھس بچہٕ۔ \n6. تہٕ داؤد سوٗز یوآبس نِش، {ونان}، سوز مے اوریاہ حتی۔ تہٕ یوآبن سوز اوریاہ داؤدس نِش۔ \n7.\\tییلہ اوریاہ أمِس نِش آو، داؤد دِژ أمِس پرژھان زِ یوآب کِتھہ پٲٹھۍ، تہٕ لوکو کِتھہ پٲٹھۍ، تہٕ جنگ کِتھہ پٲٹھۍسپُد ترقی۔ {یوآب﴾ کِتھہ پٲٹھۍ...: حب۔ امن بیترِ}\n8.\\tتہٕ داؤد ووٚن اوریاہَس زِ پَنٕنِس گَرَس مَنٛز گژھ تہٕ پَنٕنہِ کھۅر چھلناوُن۔ تہٕ دَرٕج درٛاو بادشاہ سٕندِ گَرٕ منزٕ تہٕ تَتہِ ووت أمِس پَتہٕ بادشاہ سٕندِ ماز سٍتـ̡ ۔ {پَتہٕ پَتہٕ...: ہیب۔ أمِس پَتہٕ درٛاو نیٚبر}\n9. مگر اوریاہ اوس بادشاہ سٕندِس دروازس پیٹھ پننِس آقا سٕندِس سارِنٕے خادمَن سٍتـ̡ شوٚنگتھ، تہٕ ووت نہٕ تٔمۍ سٕندِس گَرَس منز۔ \n10.\\tتہٕ یێلہِ یێلہِ تِمو داؤدس ووٚن زِ یوریاہ ووت نہٕ تٔمِس گَرَس منز، داؤدَن ووٚن یوریاہ زِ ژٕ چھُکھ نہٕ پننہِ سفرٕ پیٹھٕ آمُت؟ تێلہِ کیازِ گۆو نہٕ ژے پنہٕ نِس گَرَس مَنٛز؟ \n11. تہٕ اوریاہ ووٚن داؤد، صندوق، تہٕ اسرٲیل، تہٕ یہوداہ، خیمن مَنٛز روزُن۔ تہٕ میون آقا یوآب تہٕ میانہِ آقا سٕندِ خادم، کھٲلۍ کھاہن مَنٛز ڈیرٕ ترٲوِتھ۔ تیلہِ گژھٕ بہٕ پننِس گرس مَنٛز، کھٮ۪نہٕ تہٕ چیٚنہٕ خٲطرٕ، تہٕ پننہِ زنانہِ سٍتـ̡ روزنہٕ خٲطرٕ؟ {یێلہِ} ژٕ زندٕ روزُن، تہٕ {یێلہِ} تُہُند روح زندٕ چُھ، بہٕ کٔرٕ نہٕ یہِ کامہِ۔ \n12.\\tتہٕ داؤد ووٚن اوریاہَس زِ یێلہِ تہِ روزُن تہٕ پگہہ تہِ دِیہٕ بہٕ ژے نیرُن۔ تێوَے روٗد یوریاہ تمہِ دۅہہ تہٕ پگہہ یروشلمس مَنٛز۔ \n13. تہٕ ییلہ داؤد أمس بُلوو، تٔمۍ کٔر أمِس برونہہ کنہِ کھٮ۪وان تہٕ چیوٚن۔ تہٕ تٔمۍ کٔر أمِس شرابہٕ، تہٕ سُہ دراو پننِس آقا سٕندِس نوکرَن سٍتـ̡ بسترس پیٹھ لٔگِتھ، مگر ووت نہٕ پننِس گَرَس تام۔ \n14.\\tتہٕ صبحٲے سپُد زِ داؤد لیوکھ یوآبس اکھ چِٹھہِ، تہٕ سوٗزُن یوریاہ سٕندِ اتھہٕ سٍتـ̡ ۔ \n15.\\tتہٕ تٔمۍ لیوٗکھ چِٹھہِ مَنٛز وَنُن، یُس یوریاہ سارِوٕے کھۄتہٕ برٛونٛہہ، تہٕ أمِس نِش کٔرِو تہٕ أمِس نِش کٔرِو مَرُن، یُتھ سُہ گژھہِ مارنہٕ تہٕ مَرُن۔ {گرم ترین: ہیب۔ مضبوط} {أمِس سٍتـ̡ ہیب۔ أمِس پَتہٕ پَتہٕ}\n16.\\tتہ سپد ییلہ یوآب شہر وُچھان اوس، تمٔۍ دِژ اوریاہ تتھ جایہ مقرر ییتہِ تس پتاہ زِ بہادر انسان چھہِ۔ \n17.\\tتہٕ شہرٕکۍ نفر دراو نیٚبر، تہٕ لوٚگ یوآبس سٍتـ̡ جنگ، تہٕ داؤد سٕندِس خادمَن ہٕندِس لُکہٕ سٍتـ̡ گٔیہٕ کیٚنٛہہ۔ تہٕ اوریاہ حِتِی تہِ موٗد۔ \n18.\\tپتہٕ سوٗز یوآبن تہٕ وونُن داؤدس جنگس مُتلِق سٲری چیز۔ \n19.\\tتہٕ دِتُن رسولس حکم دِتھ زِ ییلہ ژے بادشاہس جنگُک معاملہٕ ونُن بند کٔرِو، \n20. تہٕ اگر بادشاہ سُند غصہٕ ووٚتھ، تہٕ سُہ وَنُن چُھ، ییلہ تہٕ لڑٲے کٔرِو تہٕ کیازِ گٔیہٕ شہرس نزدیک؟ ژیہ ٲس نہٕ خبر زِ تم کرن دیوارٕ پیٹھٕ گولہٕ؟ \n21.\\tیروبیشیث سٕندِس نیچوِس کٔمۍ دِژ ابیمیلخس مارٕ؟ کُنہِ زنانہِ اوس نہٕ دیوارٕ پیٹھٕ أمِس ملہِ ہُند اکھ ٹُکرٕ تراومُت، یُس سُہ تھیبیزس مَنٛز موٗد؟ ژیہ کیازِ گٔیہِ دیوارس نزدیک؟ تیلہِ وَنُن چُھہ تُہند خادم اوریاہ حِطیت تہِ موٗدمُت۔ {یروبیشیتھ: یَتھ تہِ وَننہٕ یِوان چھُ}\n22.\\tتێلہِ آو رسول تہٕ ہٲوِن داؤدس سُہ سورُے یُس یوآبن أمس سوزمُت اوس۔ \n23. تہٕ رسولن ووٚن داؤدس زِ یٔقیٖنی طور لٔگۍ اسہِ خٕلاف، تہٕ درٛاو اسہِ نِش مٲدانس مَنٛز، تہٕ أسۍ ٲسۍ تِمن پیٹھ دروازٕ کِس اژنس تام تہِ۔ \n24.\\tتہٕ گولہِ چلاون والیو گولہِ دیوارٕ پیٹھٕ تہندٮ۪ن خادمَن پیٹھ گولہِ۔ تہٕ بادشاہ سٕندِس نوکرس منز گٔیہِ کینہہ مٔرۍ، تہٕ تُہند خادم اوریاہ ہِٹی تہِ چُھ موٗدمُت۔ \n25. اَمہِ پَتہٕ ووٚن داؤد رسولس زِ یِتھٕ پٲٹھـ̡ ژے وَنُن یوآبس زِ یہِ چیز گژھہِ نہٕ ژے ناراض کٔرِتھ، تکیازِ تلوار چھے اَکھ أکِس سٍتـ̡ کھٮ۪وان: شہرس خلاف کرو پنُن جنگ زیادٕ مضبوط، تہٕ سُہ کرُن اَکھ تہٕ أمِس حوصلہٕ افزٲیی۔ {ناپسند...: ہیب۔ پنہٕ نِس نظرن منز بد کار گژھُن} {اَکھ...: حب۔ یِتھے پٲٹھۍ تہٕ یِتھٕ پٲٹھۍ}\n26.\\tتہٕ ییلہ اوریاہ سٕنزِ زنانہِ بوٗز زِ یوریاہ سُند خانٛدار چُھ موٗدمُت، تٔمۍ کٔر پننِس خاوندس خٲطرٕ ماتم ۔ \n27.\\tتہٕ ییلہ ماتم ختم سپُد، داؤد سوٗز تہٕ أنِن أمِس پَنٕنِس گَرَس کُن، تہٕ سۄ بنییہِ أمِس خانٛدارِنۍ تہٕ دِژُن أمِس اکھ نیٚچُو۔ مگر یُس کتھ داؤدَن کٔرمٕژ ٲس، سُہ اوس خداوند ناراض۔ {ناراض: حب۔ اوس بُرٕ سٕندِس نظرس منز}","1. تہٕ خداوند سوٗز ناتھن داؤدس نِش۔ تہٕ سُہ آو أمِس نِش تہٕ وونُن أکِس شہرس مَنٛز زٕ نفر۔ اکھ امیر تہٕ بیٛاکھ غریب۔ \n2.\\tامیر {انسان} ٲسۍ واریاہ کھۅلہٕ تہٕ کھورِ کھۅلہٕ: \n3.\\tمگر غریبس اوس نہٕ کیٚنٛہہ تہِ، أکِس لۄکٹِس کۅکرِ ہٕندِس کۅکرس علاوٕ، یُس أمِس ہیوٚتمُت تہٕ رچھمُت اوس، تہٕ سُہ اوس أمِس سٍتـ̡ تہٕ پننین شُرین سٍتـ̡ رٔلِتھ بٔڑِتھ۔ سُہ اوس پننِس ماز سٍتـ̡ کھٮ۪وان، تہٕ پنہٕ نِس پیالہٕ سٍتـ̡ چُھہ تہٕ أمِس کورِ ہٕندِس پٲٹھۍ۔ {ماز:Heb. مَژ}\n4.\\tتہٕ اَکھ مسافر آو امیر شخصس نِش، تہٕ تٔمۍ دِژ پنُن پَنُن تہٕ پنُن کھیٚلہٕ نِنہٕ خٲطرٕ، یُس أمِس نِش یِنہٕ وٲلِس سٕندِ خٲطرٕ پَلَو لاگُن۔ مگر تٔمِس نِش یُس أمِس نِش یِنہٕ وٲلِس شخصہٕ سٕندِ خٲطرٕ پَلو۔ \n5.\\tتہٕ داؤد سُند غصہٕ گۆو أمِس شخصس سٍتـ̡ سٮ۪ٹھاہ دِنہٕ۔ تہٕ تٔمۍ ووٚن ناتھنس {یێلہِ}خداوند زندٕ چُھ، یێلہِ یہِ {کٲم} کرِ، سُہ گژھہِ یقینا مرُن: {شُل...: یا، چُھہ مرنس لایق، یا چُھہ مرُن نیچو}\n6. تہٕ سُہ کرِ کۅکرِ ژۅن لٹہِ دُبارٕ دِنہٕ، تکیازِ أمِس اوس نہٕ یہِ کٲم کٔرمٕژ، تہٕ کیازِ أمِس اوس نہٕ کانہہ رحم کٔرِتھ۔ \n7. تہٕ ناتھنن ووٚن داوڈس زِ تہٕ چُھہ تُہۍ انسان چُھ۔ یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند خدا، مے چُھہ تُہٕے اسرٲیلِس پیٹھ بادشاہ مقرر کرنہٕ آمُت، تہٕ مے کٔرٕکھ ژے ساؤل سٕندِ اتھہٕ نِش نِش نجات دِنہٕ۔ \n8. تہٕ میہ دِژ ژے پنُن آقا سُند گرٕ تہٕ تہندِس آقا سٕنزِ زنانہٕ تہٕ دِژٕ ژے اسرٲیلُک تہٕ یہوداہُک گرٕ دِنہٕ۔ تہٕ یێلہِ سٍتـ̡ کم آسہِ، بہٕ ہا ہا ژے یِتھٕ پٲٹھـ̡ چیز دِنہٕ۔ \n9. کیازِ کٔر ژے رب سٕندِس حُکمس حقارت کٔرِتھ تہٕ تٔمۍ سٕندِس نظرِ منز بد کار کرنٕچ حقارت کٔرٕن؟ ژے کٔر اوریاہ حِتِس تلوار سٍتـ̡ مٲرِتھ تہٕ تٔمۍ سٕنزِ زنانہِ ہٕنزِ زنانہٕ بنیومٕژ تہٕ عمون سٕندِ شُرین ہٕنزِ تلوار سٍتـ̡ مٲرِتھ ۔ \n10.\\tتێلہِ گژھہِ نہ تلوار زانہہ تہِ پننہِ گرِ منزہ نیرِ۔ تکیازِ ژے چھے میہ حقارت کٔرمٕژ، تہٕ کٔرٕن یوریاہ ہِٹی سٕنزِ زنانہِ پنٕنۍ زنانہٕ۔ \n11. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، وُچھ، بہٕ کَرٕ تُہٕندِس گَرٕ منزٕ بُرٕ تُلنہٕ، تہٕ بہٕ نِیہٕ چانہِ زنانہٕ تہٕ تُہٕندِس ہمساین دِنہٕ، تہٕ سُہ کرِ تُہنزن زنانن سٍتـ̡ یَتھ آفتابس کِس نظرس منز۔ \n12. تکیازِ ژے کٔر ژوٗرِ پٲٹھۍ، مگر بہٕ کٔرٕ یہ کٲم سارنٕے اسرٲیلِس برونہہ تہٕ آفتابس برونہہ کُن۔ \n13. تہٕ داؤدن ووٚن ناتھنس زِ میہ چُھ خداوند سٕندِس خلاف گۅناہ کورمُت۔ تہٕ ناتھنن ووٚن داوڈس زِ خداوند تہِ چُھ تُہند گۅناہ دوٗر کوٚرمُت۔ ژٕ گژھ نہٕ مرُن۔ \n14. توتہِ، کیازِ اَمہِ عملہٕ سٍتـ̡ چُھہ ژے خداوند سٕندِس دُشمنن کُفر کرنُک بۆڈ موقعہٕ دِژمُت، سُہ بچہ تہِ یُس تۅہہِ خٲطرٕ زامُت چُھ، سُہ تہِ گژھہِ یٔقیٖنی طور مرُن۔ \n15.\\tتہٕ ناتھن دراو پننِس گرس کُن۔ تہٕ خداوند دِژ سُہ شُر یُس اوریاہ سٕنزِ زنانہِ داؤدس نِش زیٚو، تہٕ سُہ اوس سٮ۪ٹھاہ بیمار۔ \n16.\\tداؤد کٔر شُرِ خٲطرٕ خدایہِ سٕندِ خٲطرٕ التجا ۔ تہٕ داؤد کٔر روزٕ تہٕ ژاو تہٕ ژاو سارِوٕے رٲژ زمینس پیٹھ۔ {روزُن: عبرانی۔ روزُن روزُن}\n17.\\tتہٕ تٔمۍ سٕندِس گرٕکۍ زِٹھۍ گٔیہِ أمِس نِش، تہٕ گٔیہِ أمِس زمینہٕ پیٹھٕ تُلنہٕ خٲطرٕ، مگر سُہ اوس نہٕ تِمن سٍتـ̡ روٹی کھٮ۪وان۔ \n18.\\tتہٕ سٔتِمہِ دۅہہ سپُد شُر مٔرِتھ۔ تہٕ داؤد سٕندِس نوکرَس گٔیہِ أمِس یہ ونُن زِ شُر چُھ موٗدمُت، تِکیازِ تِمو ووٚن، وُچھِو، یێلہِ شُر وُنہِ زِندٕ اوس، أسۍ کٔر أمِس سٍتـ̡ کتھ تہٕ سُہ بوزِ نہٕ سانہِ آوازٕ: تیلہِ کِتھہ کٔنۍ کرِ سُہ پانس پریشان، اگر أسۍ أمِس ؤنِو زِ شُر چُھ موٗدمُت؟ {vex: Heb. دَگ دِیُو}\n19.\\tمگر ییلہ داؤد وُچھ زِ تٔمۍ سٕندِس خادمَن چُھ سرگوشی کٔرِتھ، داؤد وُچھ زِ شُر چُھ موٗدمُت، تێمہِ کِنۍ ووٚن داؤد پننین خادمَن زِ شُر چھا موٗدمُت؟ تہٕ تِمو ووٚن، سُہ چُھ موٗدمُت۔ \n20. پَتہٕ ووت داؤد زمینہٕ پیٹھٕ تہٕ واش کٔرِن تہٕ کوٚرُن پانس مسح تہٕ بدلٲوُن پَنُن پَنُن پَلَو، تہٕ آو خداوند سٕندِس گرس مَنٛز، تہٕ کٔرٕن عبادت کرنہٕ۔ تہٕ ییلہ أمِس ضرورت پیٚیہِ، تِمو تھوو أمِس برونہہ کُن روٹی تہٕ تٔمۍ کھیوٚن۔ \n21.\\tاَمہِ پتہٕ ووٚن تٔمِس خادمَو زِ یہِ کیا چُھہ ژے کٔرِمُت؟ ژے کٔرٕکھ شُرِ سٕندِ خٲطرٕ روزٕ تہٕ رووُن، {ییلہ سُہ زندٕ اوس}۔ مگر ییلہ شُر مٔرِتھ اوس، تۅہہ ووٚتھ تہٕ کھیوٚو روٹ۔ \n22.\\tتہٕ تٔمۍ ووٚن، ییٚلہِ شُر وُنہِ زندٕ اوس، بہٕ کٔر روزٕ تہٕ رووُن، تکیازِ مےٚ ووٚن، کُس ہیکہِ ؤنِتھ زِ خدا کرِ میانہِ خٲطرٕ مہربان، یُتھ شُر زندٕ روزِ۔ \n23.\\tمگر وۅنۍ چُھس سُہ موٗدمُت، بہٕ کیازِ روزٕ روزُن؟ بہٕ ہیکہٕ سُہ دُبارٕ واپس أنِتھ؟ بہٕ گژھٕ أمِس نِش، مگر سُہ گژھِ نہٕ مےٚ نِش واپس۔ \n24.\\tتہٕ داؤدن دیت پننہِ زنانہِ باتھ شیبا تسلی دِنہٕ، تہٕ ووت أمِس نِش تہٕ لوٚگ أمِس سٍتـ̡ تہٕ تٔمِس زاے اکھ نیٚچُو، تہٕ تٔمۍ ووٚن پنُن ناو سُلیمان، تہٕ خداوند کٔر أمِس محبت۔ \n25.\\tتہٕ تٔمۍ سوز ناتھن پیغمبر سٕندِ اتھہٕ سٍتـ̡ ۔ تہٕ تٔمۍ ووٚن خداوند سٕندِ سٍتـ̡ پنُن ناو Jedidiah۔ {Jedidiah: یعنی خداوند سُند محبوب}\n26.\\tتہٕ یوآب لوٚگ عمون سٕندِس اولادس رَباہس سٍتـ̡ تہٕ کوٚرُن شٲہی شہرس پیٹھ قبضہٕ۔ \n27.\\tتہٕ یوآبن سوٗزۍ داؤدس نِش قاصد تہٕ وونُن زِ میہ چُھ ربعس خلاف جنگ کورمُت تہٕ آبُک شہر چھُکھ قبضہٕ کورمُت۔ \n28. تَمہِ کِنۍ کٔرِو باقٕے لُکھ جمع تہٕ شہرس خلاف ڈیرٕ ترٲوِو، تہٕ رٔٹِتھ رٔٹِو، نِش گژھہِ بہٕ شہر رٔٹِتھ تہٕ یِہ یِیہِ میانہِ ناوٕ سٍتـ̡ وننہٕ یُن۔ {یہِ گژھہِ وننہٕ یُن...: حب۔ میون ناو گژھہِ اَتھ پٲٹھـ̡ وَننہٕ یُن}\n29.\\tتہٕ داؤد کٔر سارِنٕے لُکھ جمع تہٕ رَبَس نِش لوٚگ تہٕ لوٚگ أمِس خٕلاف۔ \n30. تہٕ تٔمۍ تُل تِہُند بادشاہ سُند تاج پننِس کلہٕ پیٹھ، یُس وزنُک {اوس} قیمتی پتھرن سٍتـ̡ سۄنہٕ ہُند ٹیلنٹ اوس، تہٕ یہِ اوس داؤد سٕندِس کلس پیٹھ {قٲیم} کرنہٕ۔ تہٕ تٔمۍ کٔر شہرُک غُنیمت سٮ۪ٹھاہ زیادٕ سٍتـ̡ نیران۔ {بٔڈِس منز...: عبری۔ واریاہ عظیم}\n31. تہٕ تِمو کٔرِن تِم لُکھ یِم اَتھ مَنٛز ٲسۍ، تہٕ تِم تھووُن لُکھ تہٕ ششتٕرٕچ کلہٕ تَل تہٕ شِشتٕرٕچ کلہٕ تَل تہٕ تِم کٔرِن سیرن ہٕندِس بٹھس منز، تہٕ یِتھٕ پٲٹھۍ کٔرٕن أمِس عمون کین بُلٮ۪ن ہٕندِس سارِنٕے شہرن کُن۔ یِتھٕ کٔنۍ گٔیہِ داؤد تہٕ سارِنٕے لُکھ یروشلم کُن واپس۔","1. تہٕ امہِ پتہٕ سپُد یہِ زِ داؤد سٕندِس نیچوِس ابسالوم سٕنز ٲس اکھ خوبصورت بینہِ، یٔمۍ سُند ناو اوس تمر۔ تہٕ داؤد سُند نیچو اوس أمِس محبت کران۔ \n2.\\tتہٕ امنون گوو تیوٗت پریشان زِ سُہ گوو پننہِ بینہِ تامرس خٲطرٕ بیمار۔ تکیازِ سۅ ٲس کنواری۔ تہٕ امنون باسیوو أمِس سٍتـ̡ کانہہ تہِ کٲم کرُن مشکل۔ {امنون سونچ...: ہیب۔ یہ اوس حیرت انگیز، یا، امنون سٕنزِ نظرن منز پوشیدٕ}\n3.\\tمگر امنون اوس اکھ دوس، یُس شمیعہ داؤد سٕندِس بٲے سُند نیچو جوناداب اوس، تہٕ جوناداب اوس سٮ۪ٹھاہ لطیف انسان۔ \n4. تہٕ تٔمۍ ووٚن أمِس زِ ژٕ کیازِ چُھکھ بادشاہ سُند نیچو روزان، دۅہہٕ پتہٕ دۅہہٕ دۅہہٕ دِنہٕ آمُت؟ ژٕ چھکھ نہٕ مے وَنُن؟ تہٕ امنون ووٚن أمِس زِ بہٕ چُھس پننِس بٲے ابسالوم سٕنزِ بینہِ تامار سٕنز محبت۔ {دُہلہٕ: ہیب۔ صبحس سٍتـ̡ چُھہ صبح̡\n5.\\tتہٕ جونادابن ووٚن أمِس زِ ژٕ لٔگِتھ پنہٕ نِس بسترس پیٹھ، تہٕ پَنُن پان بٮ۪مار کرُن، تہٕ ییلہ تُہند مول ژےٚ نِش یِیہِ، تٔمِس وَنُن زِ بہٕ دُعا کٔرِتھ میانہِ بینہِ تامار یِن، تہٕ ماز دِیُن میانہِ نظرِ برونہہ کُن، یُتھ بہٕ وُچھِتھ تہٕ تٔمۍ سٕندِس اتھہٕ سٍتۍ کھیوٚن۔ \n6.\\tتہٕ لوٚگ امنون تہٕ بٮ۪مار، تہٕ ییلہ بادشاہ أمِس نِش آو، امنون ووٚن بادشاہس زِ بہٕ چُھس دُعا کٔرِتھ، تمر یِن میانہِ بینہِ یِن، تہٕ میانہِ نظرِ برونہہ کُن کینہہ کیک بناوُن، یُتھ بہٕ تٔمۍ سٕندِس اتھہٕ کھٮ۪نہٕ خٲطرٕ۔ \n7. پتہٕ سوٗز داؤد تامرس نِش گرٕ تہٕ وونُن زِ وۄنۍ گژھ پننِس بٲیِس امنون سٕندِس گَرٕ تہٕ أمِس ماز لاگُن۔ \n8.\\tتہ گٔیہِ تمر پننِس بٲے امنون سٕندِس گَرَس منز۔ تہٕ سُہ آو لوٚگ۔ تہٕ تٔمۍ رٔٹِتھ آٹ، تہٕ گُنُن تہٕ بنووُن أمِس نظرِ تل کیک تہٕ کٔرٕن کیک بٔنِتھ۔ {آٹ: یا، پیسٹ}\n9.\\tتہٕ تٔمۍ تُل اکھ پین، تہٕ ترووُن أمِس برونہہ کُن۔ مگر تٔمۍ کٔر کھٮ۪نہٕ نِش انکار۔ تہٕ امنون ووٚن، میہ نِش کٔرِو سارِنٕے نفر۔ تہٕ تِمو کٔر أمِس نِش پرٮ۪تھ کانہہ نفر۔ \n10.\\tتہٕ امنون ووٚن تمارس زِ ماز أنِن کمرس منز، یُتھ بہٕ چانہِ اتھہٕ سٍتۍ کھٮ۪تھ۔ تہٕ تمرن نِش یُس تٔمۍ بنوومُت اوس، تہٕ أنِن خانس منز پننِس بٲیِس امنونَس نِش۔ \n11.\\tتہٕ ییلہ سۅ أمِس نِش کھٮ۪نہٕ خٲطرٕ أنِتھ، تٔمۍ رٔٹ أمِس تھپھ تہٕ وونُن أمِس سٍتـ̡ یێلہِ میانہِ سٍتـ̡ بێنہِ۔ \n12.\\tتہٕ تٔمۍ دِژ أمِس جواب، نہٕ میانہِ بٲے، مے کٔر نہٕ زبردستی کرنہٕ۔ تکیازِ اسرٲیلِس مَنٛز گژھِ نہٕ یِتھ کُنہِ تہِ کُنہِ تہِ کرنہٕ یُن: ژے کٔرِو نہٕ یہِ بیوقوفی۔ {زبردست...: ہیب۔ میہ کٔرِو عاجز} {یِتھٕ کُن...: ہیب۔ یہِ گژھہِ نہٕ یُتھ کرنہٕ یُن}\n13. تہٕ بہٕ کوٚت کُن گژھہٕ بہٕ پنٕنۍ شرم کُن نیرُن؟ تہٕ تۅہہِ گژھہِ اسرٲیلِس مَنٛز بیوقوفن ہٕندۍ پٲٹھۍ۔ تَمہِ مۄکھٕ چُھس بہٕ ژے دُعا کٔرِتھ بادشاہس سٍتـ̡ کتھ کٔرِتھ۔ تکیازِ سُہ کرِ نہٕ میہ ژے نِش رُکاونہٕ۔ \n14.\\tتوتہِ اوس نہ تس تسنز آواز بوزان مگر تس کھوتہ زیادہ طاقتور آسنہ کنۍ کورُن أمس مجبور تہ لوٚگ أمس سٍتۍ۔ \n15.\\tاَمہ پَتہٕ کٔر امنون أمِس سٍتـ̡ سٮ۪ٹھاہ نفرت۔ یێلہِ سُہ نفرت، یێمہِ سٍتـ̡ أمِس سٍتـ̡ نفرت ٲس سٍتـ̡ نفرتـ̡ سٍتـ̡ س�\n16.\\tتہٕ تٔمۍ ووٚن أمِس {اَتھ کُنہِ وجہ} چُھنہٕ: یہِ بُرٕ چُھہ میہ دِنہٕ خٲطرٕ بٔڈ یُس ژے میانہِ خٲطرٕ کورمُت۔ مگر سُہ اوس نہٕ أمِس بوزان۔ \n17.\\tتمہِ پتہ بُلوو پننِس خادمس یُس أمِس خدمت کران اوس، تہٕ وونُن، یہِ زنانہٕ کٔرِن میانہِ نِش تہٕ دروازٕ بند کٔرِتھ۔ \n18.\\tتہٕ تٔمِس اوس مختلف رنگن ہُند پلو لٲگِتھ، تکیازِ یِتھٕ پوشہٕ لٲگِتھ آسہٕ بادشاہ سٕنزِ کورِ یِمن ہٕندِس پَلَو لٲگِتھ۔ اَمہ پتہٕ أنۍ أمۍ سٕندِس نوکرس نٮ۪بر تہٕ دروازٕ بند کٔرِتھ۔ \n19.\\tتہٕ تَمرَن ترٛٲوٕن أمِس کلَس پٮ۪ٹھ سوٗر، تہٕ ژٔٹِن أمِس مُختلِف رنگن ہُنٛد پلو یُس أمِس پٮ۪ٹھ اوس، تہٕ تھووُن أمِس کلَس پٮ۪ٹھ اتھہٕ، تہٕ وَنُن وَنُن۔ \n20.\\tتہٕ اَبسالوم تٔمۍ سٕندِس بٲے ووٚن تٔمِس زِ اَمنون چُھہ تُہُند بٲے چُھہ ژےٚ سٍتـ̡ سٍتـ̡ چُھہ؟ مَگَر پَنُن پَنُن رٔٹِتھ رٔٹِو، میانہِ بینہِ: سُہ چُھ تُہُند بٲے ۔ یێمہِ سٍتـ̡ چُھہ نہٕ تُہٕندِس بٲیِس سٍتـ̡ بٲے سٍتـ̡ وُچھمُت۔ یێمہِ سٍتـ̡ چُھہ تٔمـ̡ بٲے سٍتـ̡ یێلہِ سٍتـ̡ بێیہِ سٍتـ̡ بٲے سٍتـ̡ سٍتـ̡ پۯاونہٕ آمُت۔ ﴿Amnon: Heb. Aminon} {وُچھِو...: حب۔ پَنُن دِل کٔرِو نہٕ تھاوُن} {ویران کٔرِتھ: حب۔ تہٕ ویران کٔرِو}\n21.\\tمگر ییلہ بادشاہ ڈیوڈس یِم سارِنٕے کتھٕ بوز، سُہ گوٚو سٮ۪ٹھاہ شرارت۔ \n22.\\tتہٕ ابسالوم کٔر پننِس بٲیِس امنون سٍتـ̡ نہ خیر تہٕ بُر، تکیازِ ابسالوم اوس امنون سٍتـ̡ نفرت، تکیازِ تٔمۍ ٲس پننہِ بینہِ تامرس زبردستی کٔرمٕژ۔ \n23.\\tتہٕ پوٗرٕ دۄیو ؤریو پَتہٕ سپُد زِ ابسالوم سٕندِس بعلحزورس مَنٛز ٲس کۅکرِ ژٹنہٕ وٲلۍ، یُس افرائیمس سٍتـ̡ {چُھ} تہٕ ابسالومَن کٔر بادشاہ سٕندِس سارِنٕے نیٚچوِس دعوت دِنہٕ۔ \n24. تہٕ ابسالوم آو بادشاہس نِش، تہٕ ووٚنُن، وُچھ، وُچھ، چانہِ خادمَس چُھہ کۅکرِ ژٹان۔ بادشاہس گژھ تہٕ تٔمۍ سٕندِس خادمَس سٍتـ̡ نیرُن۔ \n25.\\tتہٕ بادشاہن ووٚن ابسالوم، نہ، میانہِ نیچو، اسہِ سارِوٕے گژھ نہٕ وۅنۍ نیرُن، نتہٕ گژھہِ أسۍ ژےٚ ذمہٕ دار۔ تہٕ تٔمۍ دِژ أمِس دباو: بہرحال سُہ گژھِ نہٕ نیرُن، مگر دِتُن أمِس دُعا دِنہٕ۔ \n26. اَمہِ پتہٕ ووٚن ابسالوم، اگر نہٕ تہٕ بہٕ ژےٚ دُعا کٔرِتھ زِ میون بٲے امنون گژھہِ اسہِ سٍتـ̡ نیرُن۔ تہٕ بادشاہن ووٚن أمِس زِ سُہ کیازِ گژھِ ژےٚ سٍتـ̡ نیرُن؟ \n27. مگر ابسالومن دِژ أمِس دباو، زِ تٔمۍ دِژ امنون تہٕ بادشاہ سٕندِس سارِنٕے نیچوِس پانس سٍتـ̡ نیرُن۔ \n28.\\tوۅنۍ اوس ابسالومن پننین خدمتگارن حکم دِتمُت، وونُن زِ وُنہِ تہِ ییلہ امنون سُند دِل شرابہٕ سٍتـ̡ خۅش چُھ، تہٕ ییلہ بہٕ ژے وَنُن، اَمنون سُند دِل چُھہ مارُن، تیلہٕ کٔرِو أمِس مٲرِتھ، خوفہٕ نہٕ کٔرِتھ: کیا مے چُھہ نہٕ حُکُم دِژمُت؟ بہادر تہٕ بہادر بٔنِو۔ {بہادر: ہیب۔ بہادری ہٕندِس نیٚچو}\n29.\\tتہٕ ابسالوم سٕندِس خادمَو کٔر اَمنونَس سٍتـ̡ یُس ابسالوم سُند حُکُم اوس دِژمُت۔ تێمہِ پَتہٕ گٔیہِ بادشاہ سٕندِ سارِنٕے نیچِوِ ؤتھ، تہٕ پرٮ۪تھ أکِس نِش ژٔلِتھ ۔ {گاٹ...: حب۔ سوار}\n30.\\tتہٕ ییلہ تِم وتہِ وتہِ ٲسۍ، داؤدس ووت خبر زِ ابسالوم چُھ بادشاہ سٕندِ سارِنٕے نیچوۍ مٲرۍمٕتۍ، تہٕ یِمو منزٕ چُھنہٕ کانہہ تہِ باقٕے۔ \n31. پتہٕ ووٚتھ بادشاہ تہٕ لوٚگ پَنٕنۍ پلو تہٕ لوٚگ زمینس پیٹھ۔ تہٕ تٔمۍ سٕندۍ سٲری خادم ٲسۍ پَنٕنۍ پلو پھٔٹِتھ کھڑا۔ \n32.\\tتہٕ شمیعہ داؤد سٕندِس بٲے سٕندِس نیچوِس جوناداب دِژ جواب تہٕ وونُن، میانہِ آقا گژھہِ نہٕ یہِ خیال زِ تِمو چھِ بادشاہ سٕندِ نیچوۍ سارِنٕے جوان مارۍمٕتۍ۔ تکیازِ اَمنون چُھ صرف موٗدمُت، تکیازِ ابسالوم سٕندِ تعینہٕ سٍتـ̡ چُھ یہِ طے سپدان ییمہِ دۅہہ تٔمۍ پننہِ بینہِ تامار زبردستی کٔر۔ {تقرری: عبرانی۔ ٲس} {مُقرر: یا، آباد سپُد}\n33.\\tتێلہِ گژھہِ نہ میانہِ آقا بادشاہس یہ چیز پننس دلس پیٹھ نِن، یہ سونچُن زِ بادشاہ سٕندِ سٲری نیچوۍ چھِ مٔرۍمٕتۍ، تکیازِ امنون چُھ صرف موٗدمُت۔ \n34.\\tمگر ابسالوم ژوٚل۔ تہٕ یُس جوان نظر تھاوان اوس، تُل أچھ تُلِتھ تہٕ وُچھن أمِس پَتہٕ کُن بالہٕ کِس وتہِ کِنۍ واریاہ لوُکھ آمٕتۍ۔ \n35.\\tتہٕ جونادابن ووٚن بادشاہس زِ وُچھ، بادشاہ سٕندِ نیچوۍ یِوان یِتھٕ پٲٹھۍ تُہٕندِس خادمَن ووٚنمُت، تِتھے پٲٹھۍ چُھ یہِ۔ {یِتھٕ پٲٹھۍ...: ہیب۔ تُہٕندِس خادمہ سٕندِ کلامٕ مُطٲبق}\n36.\\tتہٕ سپُد یُتھ زن أمِس کتھ ختم کٔرِتھ، وُچھِتھ آو بادشاہ سٕندِ نیچوۍ تہٕ تُلِتھ وُنُن، تہٕ بادشاہ تہٕ تٔمۍ سٕندِس سارِنٕے نوکر تہِ رودُن سٮ۪ٹھاہ دَرٕ۔ {سٮ۪ٹھاہ...: ہیب۔ سٮ۪ٹھاہ وُدٕ سٍتۍ}\n37.\\tمگر ابسالوم ژوٚل تہٕ گشور کِس بادشاہ امیہود سٕندِس نیچوِس تلمایی نِش گۆو۔ تہٕ {داؤد} اوس پریتھ دۅہہ پننِس نیچوِس خٲطرٕ ماتم کران۔ {امیہود: یا، امیہور}\n38.\\tتہٕ ژوٚل ابسالوم تہٕ گوٚو گیشور کُن، تہٕ روٗد تریہ ؤری۔ \n39.\\tتہٕ {بادشاہ داؤد سُند روح} اوس ابسالوم نِش نیرُن خۅش گومُت، تکیازِ أمِس اوس امنون سٍتـ̡ تسلی دِنہٕ آمُت، یێلہِ سُہ اوس موٗدمُت۔ {Longed: یا، آو کھٮ۪نہٕ}","1. وۅنۍ زریاہ سٕندِس نیچوِس یوآبن وُچھ زِ بادشاہ سُند دِل اوس ابسالوم کُن۔ \n2. تہٕ یوآبن سوز تیکوہس نِش، تہٕ اَتھ نِش أنِن اکھ عقلمند زنانہٕ، تہٕ وونُن تٔمِس زِ بہٕ چھُس ژےٚ دُعا کران، تہٕ وُنہِ لاگُن ماتم کرن وول پَلَو، تہٕ پَنُن پان تیٖلہٕ سٍتـ̡ مسح کٔرِتھ، بٔلکہِ بٔنِتھ یٔمِس واریاہ کالہٕ مُردن ہٕندِ خٲطرٕ ماتم کٔرِتھ: \n3.\\tتہٕ یِمو بادشاہس نِش تہٕ أمِس سٍتـ̡ یِتھٕ پٲٹھۍ کتھ کٔرٕنـ̡ ۔ یێمہِ سٍتـ̡ کٔرِن یوآب سٕندِس ٲسس مَنٛز۔ \n4.\\tتہٕ ییلہ تیکواہٕچ زنانہِ بادشاہس سٍتـ̡ کتھ کٔر، سۅ پیوٚو بُتھِس پٲٹھـ̡ زمینس پیٹھ، تہٕ سجدہ کٔرٕن تہٕ وونُن، اے بادشاہ کٔرٕن مدد۔ {مدد: حب۔ بچٲوِو}\n5. تہٕ بادشاہن ووٚن أمِس زِ ژےٚ کیا چُھ؟ تہٕ تٔمۍ دیُت جواب، بہٕ چُھس پٔزۍ پٲٹھۍ اکھ بیواہ زنانہٕ، تہٕ میون خانٛدار چُھ موٗدمُت۔ \n6.\\tتہٕ تۅہہِ ہٕنزِ دٲیرِ زٕ نیچوۍ، تہٕ یِمو دۅشوے لٔگۍ کھاہس مَنٛز اِکہٕ وٹہٕ، تہٕ {تِمَن} اوس نہٕ یِمن الگ کرنہٕ خٲطرٕ، مگر أکِس لوٚگ بییِس تہٕ مارُن۔ {نہٕ...: ہیب۔ یِمن درمِیان اوس نہٕ کانہہ نجات دِنہٕ وول}\n7.\\tتہٕ وُچھِو سورُے عیال تُہنزِ دٲیرِ سٍتـ̡ بٔرِتھ تہٕ تِمو وۆن، یُس أمِس بٲے سٕندِس بٲے سٕندِس زُو سٍتـ̡ مارٕ دِنہٕ آمُت چھُ، یُس أسـ̡ أمِس بٲے سٕندِس زُو سٍتـ̡ مٲرِتھ دِنہٕ آمُت۔ تہٕ أسـ̡ وٲرِث تہِ تباہ کٔرِتھ، تہٕ یِتھٕ پٲٹھـ̡ کٔرِو تِم میانہِ خانٛدارس سٍتـ̡ {تہٕ} ناو تہٕ نہ باقٕے زمینس پیٹھ۔ {پیٹھ...: ہیب۔ زمینہِ پیٹھ}\n8.\\tتہٕ بادشاہن ووٚن زنانہِ زِ گژھ پننہِ گرس منز، تہٕ بہٕ کرٕ چانہِ ہُند ذمہٕ۔ \n9.\\tتہٕ تیکواہٕچ زنانہِ ووٚن بادشاہس زِ اے بادشاہ، اے بادشاہ، میہ تہٕ میٲنس مٲلہِ سٕندِس گرس پیٹھ گژھ بدکار تہٕ بادشاہ تہٕ تٔمۍ سٕندِس تختس پیٹھ تہٕ بےٚ قصور۔ \n10. تہٕ بادشاہن ووٚن، یُس تہٕ یُس تہٕ تۅہہِ وَنُن چُھ، سُہ أنِو سُہ میانہِ نِش، تہٕ سُہ کرِ نہٕ تۅہہِ سٍتـ̡ اَتھٕ لاگُن۔ \n11.\\tتێلہِ ووٚن تٔمۍ دُعا کٔرِتھ زِ بادشاہ گژھہِ خداوند پنُن خدایہ یاد تھاوُن، یێلہِ ژے گژھہِ نہٕ خونُک بدلہٕ نِنہٕ والٮ۪ن مزید تباہ کرنُک دِنہٕ، یێلہِ تِم گژھن میون نیچو تباہ کٔرِتھ۔ تہٕ وۆنُن یێلہِ خداوند زندٕ چُھ، تێلہِ گژھہِ نہٕ تۅہہِ نیچوۍ سُند اکھ مس تہِ زمینس پیٹھ پیوٚو۔ {یہ...: ہیب۔ یُس خونُک انتقام لینے وول گژھہِ نہٕ تباہ کرنہٕ خٲطرٕ بڑاوُن}\n12. اَمہِ پتہٕ ووٚن زنانہِ زِ چانہِ دٲیر، بہٕ چھُس ژےٚ دُعا کٔرِتھ میٲنِس آقا بادشاہس سٍتـ̡ کتھ کٔرِتھ۔ تہٕ تٔمۍ ووٚن، وَنُن۔ \n13.\\tتہٕ زنانہِ ووٚن، تیلہِ کیازِ کور ژے خدایہ سٕندِس لوکن سٍتـ̡ یۅہے کتھ سوچمٕژ؟ تکیازِ بادشاہ چُھ یہِ کتھ غلط کتھ کران یُس نہٕ بادشاہ دُبارٕ دُبارٕ گَرٕ اَنان۔ \n14.\\tاسہِ پزِ مرُن، تہٕ یُس نہٕ دُبارٕ جمع سپدِتھ چھُ، یُس نہٕ دُبارٕ جمع کٔرِتھ چھُ۔ نَہ چُھ خدایہ شخصس عزت کران، توتہِ چُھ سُہ وَتھ بناوان، یُس نہٕ أمِس نِش کڈنہٕ یُن۔ {تہٕ نہٕ...: یا کیازِ خداین چُھ نہٕ تٔمِس زُو نِش نِنہٕ آمُت، تٔمۍ تہِ چھُ وَتھ تہِ وَننہٕ آمُت، بیترِ}\n15.\\tتێلہِ چُھس بہٕ پننِس آقا بادشاہس سٍتـ̡ یہِ کتھ کرنہٕ خٲطرٕ آمُت، {یہِ} کیازِ لوکو چُھس بہٕ خوفزدہ کورمُت: تہٕ تُہنزِ دٲیرِ ووٚن، بہٕ کَرٕ وۄنۍ بادشاہس سٍتـ̡ کتھ کرنہٕ۔ یہِ ہیکہِ ٲسِتھ زِ بادشاہ کرِ پننہِ دٲیرِ ہٕنز درخواست پورٕ۔ \n16.\\tکیازِ بادشاہ بوزِہِ پنٕنۍ دٲیرِ انسان سٕندِ اتھہٕ نِش نجات دِنہٕ یُس میہ تہٕ میون نیچو خدایہ سٕندِ وٲرثہٕ سٍتـ̡ تباہ کرِ۔ \n17.\\tتێلہِ وۆن، میانہِ آقا بادشاہ سُند کلام گژھہِ وۅنۍ آرام دِنہٕ، تکیازِ خدایہ سُند فرشتہٕ پٲٹھۍ، تِتھے پٲٹھۍ چُھہ میون رب بادشاہ نیکی تہٕ بد سمجھنہٕ خٲطرٕ، تێلہِ آسہِ خداوند تُہند خدا توے سٍتـ̡ ۔ {آرام دِنہٕ: ہیب۔ آرام خٲطرٕ} {سمجھنہٕ خٲطرٕ: ہیب۔ بوزنہٕ خٲطرٕ}\n18.\\tپتہٕ دِژ بادشاہن جواب تہٕ وونُن زنانہِ زِ میہ نِش مہ ژوٗرِ روزُن، بہٕ چھُس ژےٚ پرژھان۔ تہٕ زنانہِ ووٚن، میانہِ آقا بادشاہ گژھہِ وۅنۍ کتھ کرنہٕ۔ \n19.\\tتہٕ بادشاہن ووٚن، {کیا چُھنہ} اتھ سارِنٕے مَنٛز یوآب سُند اَتھٕ چُھنہٕ؟ تہٕ زنانہِ دیُت جواب تہٕ وونُن، {یُتھ} تُہند روح زندٕ چُھ، میانہِ آقا بادشاہ، کانہہ تہِ ہیکہِ نہٕ دٔچھنِس یا کھوورِ کُن پھیرِتھ، یُس میانہِ آقا بادشاہن کتھ کٔرمٕژ چُھ، تہٕ تٔمۍ تھوو یِم سٲری لفظ چانہِ خادمہِ ہٕندِس ٲسس منز۔ \n20.\\tاَمہ کتھہِ ہٕندِس صورتس مُتلق چُھہ تُہند خادم یوآبن یہ کٲم کٔرمٕژ: تہٕ میانہِ آقا چُھہ خدایہ سٕندِ فرشتہٕ سٕنزِ حکمت مطٲبق عقلمند زِ سُہ چُھ سارِنٕے {چیز} زانان یُس زمینس مَنٛز چُھ۔ \n21. تہٕ بادشاہن ووٚن یوآبس زِ وُچھو وُنہِ میہ یہ کتھ کٔرمٕژ: تێلہِ گژھ جوان ابسالوم دُبارٕ أنِتھ۔ \n22.\\tتہٕ یوآب پیوٚو بُتھِس پیٹھ زمینس پیٹھ، تہٕ کٔرُن نَم تہٕ کٔرُن بادشاہس شُکریہ ادا۔ تہٕ یوآبن ووٚن، از تام چُھہ چانہِ خادمس پتاہ زِ میہ چُھہ چانہِ نظرِ منز فضل میلمُت، اے بادشاہ، یێمہِ سٍتـ̡ بادشاہن کٔر پننِس خادمس سٕنز درخواست پورٕ۔ {شُکر: حب۔ بابرکت } {تٔمۍ سُند خادم: یا، تُہند خادم}\n23.\\tیێلہِ یۆو یوآب ووٚتھ تہٕ گۆو گیشور کُن تہٕ اَنُن ابسالوم یروشلم۔ \n24. تہٕ بادشاہن ووٚن، سُہ گژھ پننِس گرس کُن پھیرُن، تہٕ سُہ گژھ نہٕ میون بُتھ وُچھُن۔ یێلہِ ووت ابسالوم پننِس گرس منز، تہٕ وُچھُن نہٕ بادشاہ سُند بُتھ۔ \n25. مگر سارِنٕے اسرٲیلس مَنٛز اوس نہٕ کانہہ تہِ ابسالوم سٕندِ خوٗبصوٗرتی ہٕندِس تعریفس سٍتـ̡ تسٕندِس کھورِ پیٹھٕ کلہٕ کِس تاجس تام کُنہِ تہِ داغ۔ {مگر...: حب۔ تہٕ ابسالوم سٕندِس پٲٹھۍ، سارِنٕے اسرٲیلِس مَنٛز اوس نہٕ کانہہ خوٗبصوٗرت انسان یُس زیادٕ تعریف}\n26.\\tتہٕ ییلہ أمس کلہٕ دِوان اوس، (تکیازِ پرٮ۪تھ ؤری کِس ٲخرس پیٹھ اوس أمِس کلہٕ دِوان: کیازِ {مَس} اوس أمِس پیٹھ گوٚب، امہِ کِنۍ اوس أمِس کلہٕ سُند وزن بادشاہ سٕندِ وزنہٕ پتہٕ زٕ ہتھ شیکل۔ \n27.\\tتہٕ ابسالومَس زاے ترے نیچوۍ تہٕ اکھ کور، یٔمۍ سُند ناو اوس تمر: سۅ ٲس خوبصورت زنانہٕ۔ \n28.\\tیێلہِ روٗد ابسالوم یروشلمس مَنٛز پوٗرٕ زٕ ؤری روزان، تہٕ وُچھُن نہٕ بادشاہ سُند بُتھ ۔ \n29.\\tلہذا سوٗز ابسالوم یوآبس نِش سُہ بادشاہس نِش سوزنہٕ۔ مگر سُہ آو نہٕ أمِس نِش: تہٕ ییلہ تٔمۍ دُبارٕ دُبارٕ سوزُن سُہ آو نہٕ۔ \n30. تێمہِ کِنۍ ووٚن تٔمۍ پننین خادمَن وُچھِو، وُچھِو، یوآب سُند کھیت چُھہ میانہِ نزدیک، تہٕ أمِس چُھ اتہِ جو۔ گژھ تہٕ دِیُن اتھ نار۔ تہٕ ابسالوم سٕندیو نوکرو دِژ کھہس نار۔ {نزدیک...: حب۔ میانہِ جایہِ نزدیک}\n31.\\tاَمہِ پَتہٕ ووت یوآب تہٕ ووت ابسالوم نِش تہٕ وونُن تٔمِس زِ چُھہ تۅہِ ہٕندِس خادمَس کیازِ دِیُت میانہِ کھاہس نار۔ \n32.\\tتہٕ ابسالومن دیُت یوآبس جواب، وُچھ، مے سوزمُت ژے نِش تہٕ وونُن، یێلہِ یێلہِ بہٕ ژے بادشاہس نِش سوزُن، تہٕ وَنُن زِ بہٕ کیازِ چُھس گیشور پٮ۪ٹھٕ آمُت؟ {یہٕ} اوس میانہِ خٲطرٕ اصل {یێلہِ} وُنہِ تہِ روزُن، تێمہِ مۄکھٕ دِیُن بہٕ بادشاہ سُند بُتھ وُچھُن۔ تہٕ اگر میہ مَنٛز کانہہ بُد کار آسہِ، سُہ گژھ مے مٲرِتھ۔ \n33.\\tیێلہِ آو یوآب بادشاہس نِش، تہٕ وونُن أمِس تہٕ ییلہ تٔمۍ ابسالوم بُلاونہٕ آو، سُہ آو بادشاہس نِش، تہٕ کٔرٕن بادشاہس برونہہ کُن بُتھِس پٲٹھۍ، تہٕ بادشاہن کٔر ابسالوم بوس۔","1. تہٕ امہِ پتہٕ سپُد یہِ زِ ابسالومن کٔر أمِس رتھٕ تہٕ گُرِ تہٕ پانژاہ نفر پانس برونہہ کُن پکناونہٕ خٲطرٕ تیار۔ \n2. تہٕ ابسالوم ووٚتھ سُلہِ تہٕ ووت دروازٕ کِس وتہِ نِش کھڑا۔ تہٕ یہِ اوس {یِتھ} زِ ییلہ کانہہ نفر یُس کانہہ تنازعہ اوس بادشاہس نِش فیصلہ کرنہٕ خٲطرٕ آو، تہٕ ووٚنُن ابسالوم أمِس نِش بُلاونہٕ تہٕ وونُن، تہٕ تُہہِ کُس شہرُک چُھہ؟ تہٕ تٔمۍ ووٚن، تُہند خادم چُھہ اِسرٲیلِس کِس أکِس قبیلس منز۔ {آو: ہیب۔ یِنہٕ خٲطرٕ}\n3. تہٕ ابسالومن ووٚن أمِس وُچھ، وُچھ، تُہند معاملہٕ چُھ اصل تہٕ صحیح۔ مگر {بادشاہ سُندٕ چُھنہٕ کانہہ نفر {مُقرر} چُھہ تۅہہ بوزنہٕ خٲطرٕ۔ {تتہِ...: نتہٕ چُھہ نہٕ بادشاہ سٕندِ طرفہٕ بۄن کُن کانہہ تہِ بوزنہٕ}\n4.\\tابسالومن ووٚن بییہ تہِ، اے کاش بہٕ گژھہِ اتھ زمینس مَنٛز قاضی بناونہٕ آمُت، یُس کانہہ تہِ مقدمہ یا وجہ آسہِ سُہ گژھہِ میانہِ نِش یِنہٕ، تہٕ بہٕ کٔرٕ تس سٍتـ̡ انصاف کرنہٕ۔ \n5.\\tتہٕ یہِ اوس {یِتھ} زِ ییلہ کانہہ انسان أمِس نِش سجدہ کرنہٕ خٲطرٕ آو، تٔمۍ کٔر پنُن اتھہٕ تہٕ رٔٹِتھ بوسہ دِوان۔ \n6. تہٕ یِتھٕ پٲٹھـ̡ کٔر ابسالوم سارِنٕے اسرٲیلِس سٍتـ̡ یُس بادشاہس نِش فیصلہٕ کرنہٕ خٲطرٕ آو، یێتھـ̡ کٔر ابسالوم سٍتـ̡ اِسرٲیلـ̡ ہُند دِل ژورِ۔ \n7. تہٕ ژتٲجی ؤری پَتہٕ سپُد ابسالوم بادشاہس وونُن، بہٕ چُھس ژے دُعا کٔرِتھ، بہٕ گژھ تہٕ پنُن عہد ادا کرُن، یُس میہ ہیبرونس منز خداوند سٍتـ̡ عہد کورمُت چُھ۔ \n8.\\tتێلہِ چُھہ چانہِ خادمَن عہد کٔرِتھ یێلہِ بہٕ شامس مَنٛز گیشورس مَنٛز روزان اوسس، تہٕ وونُن، یێلہِ خداوند یێلہِ بہٕ یێلہِ یێلہِ \n9. تہٕ بادشاہن ووٚن أمِس سُہ ووٚتھ، تہٕ گوٚو ہیبرون کُن۔ \n10. مگر ابسالومن سوٗزۍ اسرٲیلٕکۍ سارنٕے قبیلن مَنٛز جاسوس، یہِ وَنُن زِ یێلہِ یێلہِ بُرٕچ آواز بوٗزِو، تیلہِ وَنُن زِ ابسالوم چُھ حبرونس مَنٛز بادشاہی کران۔ \n11.\\tتہٕ ابسالوم سٍتـ̡ دراو یروشلمس منزٕ زٕ ہتھ نفر، {یُس} وننہٕ آو۔ تہٕ تِم گٔیہِ پننہِ سادگی سٍتـ̡ تہٕ تِمن ٲس نہٕ کانہہ تہِ خبر۔ \n12. تہٕ ابسالومن سوُز داؤد سُند مُشیر احیتھوفیل پننہِ شہرٕ پیٹھ، یُس داؤد سُند مُشیر اوس، یێلہِ زن تٔمۍ قربانی دِژ۔ تہٕ سٲزش ٲس مضبوط۔ تکیازِ لُکن ہُند ہُریر اوس ابسالوم سٍتـ̡ ہُریر۔ \n13.\\tتہٕ آو داؤدس نِش اکھ قاصد یُس وونُن زِ اسرائیلٕکۍ دِل چھِ ابسالوم پَتہٕ۔ \n14.\\tتہٕ داؤدن ووٚن پننین سارنٕے خادمَن زِ یروشلمس مَنٛز چُھہ أمِس سٍتـ̡ وۅتھان تہٕ ژٔلِو أسـ̡۔ تِکیازِ أسـ̡ ہێکہِ نہٕ ابسالوم نِش ژلِتھ ژٔلِتھ، یێلہِ سُہ اچانک اسہِ پۯاوُن، تہٕ اسہِ پیٹھ بُرٕ واتہِ، تہٕ شہر کرِ تلوار ہٕندِس کنارس سٍتـ̡ مارنہٕ۔ {اَنِن: ہیب۔ زور}\n15.\\tتہٕ بادشاہ سٕندٮ۪و خادمَو ووٚن بادشاہس زِ وُچھِو تُہٕندِس خادمَس {یُس تہِ میانہِ آقا بادشاہ مقرر کرِ}۔ {مُقرر کٔرِو: ہیب۔ ژٲرِو}\n16.\\tتہٕ بادشاہ دراو تہٕ أمۍ سُند سارِوٕے گرٕ أمِس پَتہٕ۔ تہٕ بادشاہن ترٲوۍ داہ زنانہٕ، یِم رژھرِ رژھراونہٕ خٲطرٕ۔ {پتہٕ...: حب۔ تٔمۍ سٕندِس قدمن پیٹھ}\n17. تہٕ بادشاہ دراو تہٕ أمِس پَتہٕ سٲری لُکھ تہٕ روٗد أکِس دوٗر جایہِ رُکاونہٕ۔ \n18.\\tتہٕ تٔمۍ سٕندِ سٲری خادم گٔیہِ أمِس نِش گٔیہِ۔ تہٕ سارِنٕے چیریتھیٹ، تہٕ سارِنٕے پیلیتھیٹ، تہٕ سارِنٕے گِتِٹۍ، یِم أمِس پتہٕ گاتھ پٮ۪ٹھٕ آمٕتۍ ٲسۍ، گٔیہِ بادشاہس برونہہ کُن۔ \n19.\\tپتہٕ ووٚن بادشاہن اِتایی گِتِس سٍتـ̡ تہٕ کیازِ چُھکھ اسہِ سٍتـ̡ نیران۔ پننہِ جایہ واپس، تہٕ بادشاہس سٍتـ̡ روزُن، تکیازِ تہٕ چُھکھ اَکھ اجنبی تہٕ جلاوطن تہِ۔ \n20. ییلہ ژے راتھ آو، کیا بہٕ از دۅہہ ژے اسہِ سٍتـ̡ ہیوٚر بۄن کٔرِتھ؟ بہٕ وُچھِتھ یێلہِ بہٕ یێلہِ تہِ گژھُن، ژے واپس، تہٕ پنٕنۍ بٲے واپس نِن: رحم تہٕ سچائی {بٔنِ} پانس سٍتـ̡ ۔ {ہیوٚر گٔژھو...: ہیب۔ گَژھِو گَژھُن}\n21.\\tتہٕ اِتایی دِیُت بادشاہس جواب تہٕ وونُن، یُتھ زن خداوند زندٕ چُھ، تہٕ یِتھٕ پٲٹھۍ میون آقا بادشاہ روزان چُھ، یێلہِ تہِ آسہِ میون آقا بادشاہ کُنہِ جایہ آسہِ، چاہے مرنس منز آسہِ یا زندگی، تتہِ آسہِ تُہند خادم تہِ۔ \n22.\\tتہٕ داؤدَن ووٚن اِتایی یَس گٔژھِتھ گٔژھِتھ گٔژھِ۔ تہٕ اِتایی گِتِی گٔیہِ تہٕ تٔمۍ سٕندِ سارِنٕے نفر تہٕ سارِنٕے لۄکٕٹۍ یِم أمِس سٍتـ̡ ٲسۍ۔ \n23.\\tتہٕ سارِوٕے مُلُک ووٚتھ بَڑِ آوازٕ سٍتـ̡ تہٕ سارِنٕے لُکھ گٔیہِ اَکہِ پٲٹھۍ، تہٕ سارِنٕے لُکھ گٔیہِ بیابان کِس وتہِ کُن۔ {Kidron: Gr. Cedron}\n24.\\tتہٕ لوو زادوک تہٕ سٲری لاوی تہِ ٲسۍ أمِس سٍتۍ، خدایہ سٕندِ عہدُک صندوق ہٮ۪تھ، تہٕ تِمو ترٛوو خدایہِ سُند صندوق۔ تہٕ ابیاتھر ووت توٚت تام یوٚت تام سارِوٕے لُکھ شہرٕ منزٕ نیبر نیرِ۔ \n25. تہٕ بادشاہن ووٚن زادوکس زِ خدایہ سُند صندوق نِن شہرس مَنٛز، یێلہِ بہٕ خداوند سٕندِس نظرس منز عنایت میلہِ، سُہ کرِ مے دُبارٕ تہٕ ہاوِ یہِ تہٕ تٔمۍ سٕندِس روزن وٲلِس روزنس منز۔ \n26.\\tمگر اگر سُہ یِتھٕ پٲٹھۍ وَنُن چُھ، بہٕ چُھس نہٕ ژے سٍتـ̡ خۅش گٔژھان۔ وُچھِو، {یێتہِ} بہٕ چُھس سُہ میانہِ سٍتـ̡ سٍتـ̡ سٍتـ̡ یێلہِ سٍتـ̡ سٍتـ̡ خیر باسان۔ \n27.\\tبادشاہن ووٚن پادٕرۍ زادوکس تہِ، {کیا تُہۍ چھُکھ نہٕ غیب گومُت؟ شہرس منز گژھ امن سان واپس، تہٕ پنٕنۍ زٕ نیچوۍ تہٕ ابیاتھر سُند نیچو احیماز تہٕ ابیاتھر سُند نیچو جوناتھن۔ \n28. وُچھ، بہٕ روزٕ بیابان کِس مٲدانس مَنٛز، یوٚت تام نہٕ ژےٚ طرفہٕ میانہِ تصدیق کرنُک لفظ ییہِ۔ \n29.\\tتَمہِ کِنۍ نِیہِ صَدوق تہٕ ابیاتھر نِیہِ خدایہِ سُند صندوق دُبارٕ یروشلمس کُن، تہٕ تِم روٗدۍ اَتہِ روٗدۍ۔ \n30.\\tتہٕ داؤد ووت زیتون کِس کھسنہٕ سٍتـ̡ تہٕ ووت وُن ہیوٚر تہٕ کلہٕ تھوٚپ کٔرِتھ تہٕ سُہ ووت نَنہٕ پٲٹھۍ، تہٕ سارِوٕے لُکھ یِمو سٍتـ̡ أمِس سٍتـ̡ ٲس، تہٕ تِم گٔیہِ ہیوٚر ہیوٚر وُنـ̡ وُچھان۔ {تہٕ رووُن...: ہیب۔ ہیوٚر ہیوٚر تہٕ رووُن}\n31.\\tتہٕ {أکہِ} ووٚن داؤدس زِ احیتھوفیل {چُھ} ابسالوم سٍتـ̡ سٲزِش کرن والٮ۪ن مَنٛز شٲمِل۔ تہٕ داؤدَن ووٚن، اے خداوند، بہٕ چُھس ژے دُعا کران زِ احیتھوفیل سٕندِس مشورس کٔرِن بیوقوف۔ \n32.\\tتہ سپد یہ زِ {ییلہ} داؤد پہاڑ کِس تھزرس پیٹھ ووت، ییتہِ سُہ خدایہ سٕنز عبادت کران اوس، وُچھِتھ آو ہوشایی آرکی أمِس مِلنہِ پَنُن کوٹ پھٔٹِتھ تہٕ کَلس پیٹھ میٚژِ ہٮ۪تھ: \n33.\\tداؤدس ووٚن زِ اگر تہٕ ژٕ میانہِ سٍتـ̡ نیرِو، تێلہِ گژھہِ میانہِ خٲطرٕ بوج۔ \n34.\\tمگر اگر ژٕ شہرس منز واپس گژھِتھ ابسالومس ونُن، اے بادشاہ بہٕ بنہٕ تُہند خادم۔ {as} بہٕ چُھس وُنیُک تام تہندِس مٲلہِ سُند خادم اوسمُت، یێلہِ بہٕ تہِ بنہٕ تُہند خادم، تیلہِ کٔرِکھ ژٕ میانہِ خٲطرٕ احیتھوفیل سٕندِس مشورس شکست دِتھ۔ \n35.\\tتہٕ کیا ژے چھُنہٕ ژے سٍتـ̡ زادوک تہٕ ابیاتھر پادٕرۍ سٍتـ̡ کُنہِ \n36.\\tوُچھِو تِمن سٍتـ̡ تِہٕندِ زٕ نیچوۍ، احیماز زادوک سُند {نیٚچُو} تہٕ جوناتھن ابیاتھر سُند {نیٚچُو}۔ تہٕ یِمو سٍتـ̡ سوزِو مے نِش پریتھ کانہہ چیز یُس ژے بوزان چھُ۔ \n37.\\tیێمہِ سٍتـ̡ آو ہوشایی داؤد سُند دوس شہرس مَنٛز، تہٕ ابسالوم آو یروشلمس مَنٛز۔","1.\\tتہ ییلہ داوود بالہٕ پیٹھٕ رژھ کھنڈ نیبر ووت، وچھ زیبا، میفیبوشیتھُک خادم زیبہ أمِس سمکھیوٚو، زٕ گَرٕ کٔرِتھ تہٕ تِمن پیٹھ زٕ ہتھ روٹی تہٕ کشمش ہٕندۍ ہتھ گٔنڈۍ، تہٕ اکھ ہتھ ریتہٕ کالہٕ مٮ۪وٕ تہٕ اکھ بوتل شراب۔ \n2.\\tتہٕ بادشاہن ووٚن زیباہس زِ تۅہہ کیا چُھکھ یِمن مَنٛز سوارِ ہُند مطلب۔ تہٕ زیباہَن ووٚن زِ گَرٕ بادشاہ سٕندِس گرس سٍتـ̡ سوارِ خٲطرٕ۔ تہٕ جوانن ہٕندِ خٲطرٕ روٹی تہٕ ریتہٕ کالہٕ مٮ۪وٕ کھٮ۪نہٕ خٲطرٕ۔ تہٕ شراب، یُس بیابانن مَنٛز بے ہوش آسہِ تِمن چیٚنہٕ۔ \n3. تہٕ بادشاہن ووٚن، تہٕ کتہِ چُھہ تُہند آقا سُند نیچو؟ تہٕ زیباہَن ووٚن بادشاہس زِ وُچھِو سُہ یروشلمس مَنٛز روزان، تکیازِ تٔمۍ ووٚن زِ از دۅہہ کرِ اسرٲیلُک گرٕ میانہِ مٲلہِ سٕنز بادشٲہی بحال کرنہٕ۔ \n4.\\tاَمہِ پتہٕ ووٚن بادشاہن زیباہَس سٍت، وُچھِو تۅہہِ سُہ {مُتعلق} یُس مفیبوشیتھس سٍتـ̡ {متعلق} چھُ۔ تہٕ زیباہَن ووٚن، بہٕ چھُس عاجزی سان ژےٚ عاجزی سان التجا کران {یُتھ} بہٕ میلہٕ چانہِ نظرِ مَنٛز رحمت، اے بادشاہ۔ {بہٕ چُھس عاجزی سان...: حب۔ بہٕ چُھس سجد کران}\n5.\\tتہٕ ییلہ بادشاہ داوود بہوریمس نِش آو، وُچھ تتہِ دراو ساؤل سٕندِس خاندانُک اکھ شخٕص، یٔمۍ سُند ناو اوس شِمیعی، یُس گیرا سُند نیچو اوس، سُہ آو برونہہ کُن، تہٕ یُس وُنہِ تہِ آو لعنت۔ {سُہ آو نٮ۪بر...: یا سُہ آو توتہِ تہٕ دُعا دِژُن}\n6. تہٕ تٔمۍ لگٲوۍ داؤدس تہٕ بادشاہ داؤد سٕندِس سارِنٕے خادمَن پیٹھ کٔنہِ۔ \n7.\\tتہٕ یِتھٕ پٲٹھۍ ووٚن شِمیعی یَتھ مَنٛز تٔمۍ بد دعا کٔرِتھ، نیٚبر نیٚبر، نیٚبر، اے خونی انسان، تہٕ ژے بِلیالُک انسان: {خون...: حب۔ خونُک انسان}\n8. خداوند چُھ ساؤل سٕندِس گھرُک سورُے خوُن توے پیٹھ واپس، یٔمۍ سٕندِ بدلہٕ ژے بادشاہی کٔرمٕژ۔ تہٕ خداوند چُھہ بادشاہت تُہندِس نیچوِس ابسالوم سٕندِس اتھس مَنٛز دِژمٕژ، تہٕ وُچھِو، تہٕ وُچھِو، تُہہِ چُھکھ پننہِ شرارتس مَنٛز نِنہٕ آمُت، کیازِکہِ تہٕ چُھکھ اَکھ خونریز انسان۔ {وُچھو...: حب۔ وُچھو پنہٕ نِس بُرِس مَنٛز}\n9.\\tاَمہِ پتہٕ ووٚن زرویاہ سٕندِ نیچو ابیشایی بادشاہس زِ یہِ موٗدمُت ہوُن کیازِ دِیہِ میٲنِس مالہٕ بادشاہس بد دُعا کٔرِتھ؟ بہٕ چھُس ژےٚ دُعا کٔرِتھ تٔمۍ سُند کلہٕ ژٔٹِتھ۔ \n10. تہٕ بادشاہن ووٚن، اے زرویاہ سٕندِ نیچو، مے کیا چُھہ ژےٚ سٍتـ̡ واٹھ دِنہٕ۔ تێلہِ گژھہِ أمِس بد دُعا دِنہٕ، کیازِ خداوند چُھ أمِس ووٚنمُت، داؤدُک لعنت۔ تیلہِ کُس وَنُن زِ ژے کیازِ چُھہ یہِ کورمُت؟ \n11.\\tتہٕ داؤدن ووٚن ابیشایی تہٕ پننین سارِنٕے خادمَن ووٚن، وُچھِو، میانہِ نیچو، یُس میانہِ یٔژ نِش نیران چھُ، میانہِ زُو ژھاران چھُ: وُنۍ کوتاہ بییہ {یہِ} بنیجمیت {کرُن}؟ أمِس تراوُن تہٕ دُعا دِیُن۔ کیازِ خداوند چُھ أمِس حُکُم دِژمُت۔ \n12. یہ ہیکہِ ٲسِتھ زِ خداوند کرِ میانہِ عذابس پیٹھ نظر، تہٕ خداوند کرِ میہ از دۅہہ پننہِ لعنتُک بدلہٕ۔ {مصیبت: یا، اوٚش: ہیب۔ أچھ}\n13.\\tییلہ داؤد تہٕ تٔمۍ سٕندِ نفر وتہِ پٔکۍ، شِمیعی ووت بالہٕ کِس طرفہٕ أمِس کُن تہٕ دِژُن أمِس کُن کٔرِتھ کٔرٕن کٔنہِ تہٕ دِژٕن گرد۔ {کاسٹ ...: حب۔ أمِس کٔرٕن گردِ سٍتۍ}\n14.\\tتہٕ بادشاہ تہٕ سٲری لُکھ یِم أمِس سٍتـ̡ ٲسۍ، تٔمِس سٍتـ̡ گٔیہِ تَتہِ تازٕ۔ \n15. تہٕ ابسالوم تہٕ سارِنٕے لُکھ یِم اِسرٲیلِکۍ لُکھ یِمن سٍتـ̡ یِمن سٍتـ� \n16.\\tتہٕ سپُد یہِ سپدُن، ییلہ ہوشایی آرکیٹ، یُس داؤد سُند دوس اوس، ابسالوم نِش آو تہ ہوشایی ین ووٚن ابسالوم، خدایہ رژھ بادشاہ، خدایہ رژھرِ بادشاہ۔ {خدا...: ہیب۔ بادشاہ گژھہِ زندٕ}\n17. تہٕ ابسالوم ووٚن ہوشایی یس زِ کیا یہ چھُکھ تۅہہِ پننِس یارس سٍتـ̡ مہربانی کٔرِتھ؟ ژے کیازِ چُھہ نہٕ پننِس یارس سٍتـ̡ سٍتـ̡ مہربانی کٔرِتھ؟ \n18.\\tتہٕ ہوشایی ین ووٚن ابسالوم، نہ۔ مگر یُس خداوند تہٕ یہِ قوم تہٕ سارِنٕے اسرٲیلِکۍ انسان چُھ، بہٕ چُھس تٔمِس سٍتـ̡ روزُن، تہٕ بہٕ روزٕ تس سٍتـ̡ روزُن۔ \n19.\\tتہٕ بییہِ بہٕ کٔمِس سٕنز خدمت کرٕنۍ؟ {بہٕ پزِ} نہٕ تٔمۍ سٕندِس نیچوِس سٕنزِ موجودگی منز خدمت کرٕنۍ؟ یِتھٕ پٲٹھۍ بہٕ چُھس تہندِس مٲلہِ سٕنزِ موجودگی منز خدمت کٔرمٕژ، تِتھے کٔنۍ روزٕ بہٕ تہٕ چانہِ ہٕندِس حضورس منز۔ \n20. اَمہِ پتہٕ ووٚن ابسالوم اہیتھوفیلس زِ أسۍ کیا کرو پانس مَنٛز مشورٕ۔ \n21. تہٕ احیتھوفیلن ووٚن ابسالومَس زِ گژھ پننِس مٲلہِ سٕنزِ لونڈین نِش، یُس تٔمۍ گرٕ رژھراونہٕ خٲطرٕ ترٲومُت چھُ۔ تہٕ سارِنٕے اِسرٲیلِس بوزُن زِ تُہۍ چھِو پننِس مٲلِس سٍتـ̡ نفرت کران، تیلہٕ گژھن سارِنٕے سارِنٕے ہٕندِس اتھہٕ مضبوط۔ \n22. یێمہِ کِنۍ لوٚگ تِمو اَبسالوم سٕندِس گَرٕ کِس پیٹھمِس پٲٹھـ̡ خیمہ ۔ تہٕ اَبسلوم گۆو سارِنٕے اِسرٲیلِس ہٕندِس نظرس مَنٛز پننِس مٲلہِ سٕنزِ لونڈین نِش۔ \n23.\\tتہٕ احیتھوفیل سُند مشورٕ، یُس تِمن دۅہن مشورٕ دِوان اوس، {اوس} یُس زن کٲنسہِ شخصہٕ خدایہ سٕندِس نصیبس سٍتـ̡ پرژھہٕ گٲر کورمُت: یِتھے پٲٹھۍ اوس احیتھوفیل سُند سورے مشورٕ داؤد تہٕ ابسالوم سٍتـ̡ ۔ {اوریکل: حب۔ لفظ}","1. امہِ علاوٕ ووٚن اِہِتھوفیلَن ابسالومَس زِ بہٕ کٔرِو وۅنۍ باہ ساس نفر ژٲرِتھ، تہٕ بہٕ کَرٕ از رٲژ داؤد سٕندِس پتہٕ پَتہٕ پَتہٕ: \n2. تہٕ بہٕ یِم أمِس نِش یِم تھکان تہٕ کمزور آسہِ، تہٕ بہٕ کرٕ أمِس خوفزدہ کرنہٕ: تہٕ یِم سٲری لُکھ أمِس سٍتـ̡ چِھہ ژلان۔ تہٕ بہٕ کٔرٕ صرف بادشاہس مارٕ: \n3.\\tتہٕ بہٕ اَنِہ سارِنٕے لُکھ ژے نِش واپس: سُہ شخٕص یُس ژے ژھاران چھُ، سُہ چھُ یِتھٕ پٲٹھۍ سارِنٕے لوُکھ واپس آمُت۔ \n4.\\tتہٕ یہ قول آو ابسالوم تہٕ اسرٲیلٕکۍ سارِنٕے بزرگن خۅش کرنہٕ۔ {خۄش...: ہیب۔ اوس صحیح، بیترِ}\n5.\\tاَمہِ پَتہٕ ووٚن ابسالوم، وُنہِ وُنہِ ہوشایی تہِ وَنُن تہٕ یِتھے پٲٹھۍ بوزُن تٔمۍ سُند کیا وَنُن۔ {کیا...: حب۔ تٔمۍ سٕندِس ٲسس مَنٛز کیا چُھ}\n6.\\tییلہ ہوشایی ابسالوم نِش آو، ابسالوم وۆن أمِس سٍتـ̡ کتھ کٔرِتھ وونُن، اہیتوفیلن چُھ یِتھٕ پٲٹھـ̡ کتھ کٔرمٕژ: أسـ̡ تٔمۍ سٕندِس کَتھٕ پَتہٕ کٔرِو؟ اگر نہٕ چُھہ نہٕ؛ کَتھ کٔرِو۔ {تٔمۍ سُند کلام: حب۔ تٔمۍ سُند کلام}\n7. تہٕ حشایی ین ووٚن ابسالومس زِ یُس مشورٕ احیتھوفیلن دِژمُت چُھ، سُہ چُھ نہٕ وٕنکینس اصل ۔ {دِنہٕ: حب۔ مشورٕ}\n8.\\tتِکیازِ تُہۍ چھِو پنُن مول تہٕ تٔمۍ سٕندِس نفرس زانان، زِ تِم چھِ طاقتور انسان تہٕ تِم چھِ پننِس ذہنس مَنٛز ژٔلِتھ، یِتھٕ پٲٹھۍ چھُ کھہَس مَنٛز لُٹنہٕ آمُت، تہٕ تُہند مول چھُ جنگی شخص، تہٕ روزِ نہٕ لوٗکن سٍتـ̡ روزُن۔ {چُھس...: ہیب۔ روح ہُند تلخ}\n9.\\tوُچھِو سُہ چُھہ وُنہِ کُنہِ کھۅڈس مَنٛز، یا کُنہِ {بییِہ} جایہِ ژوٗرِتھ، تہٕ یێلہِ یێلہِ یِمو منزٕ کینہہ گۅڈنچہ لٹہِ والہِ یِن تہٕ یێلہِ یہِ بوزِتھ آسہِ سُہ وَنُن زِ یِمن لُکن مَنٛز چُھ ذبح سپدان یُس ابسالوم سٕندِس پٲروکارس سٍتـ̡ چُھہ ذبح سپدان۔ {الٹاونہٕ: حب۔ پۯاوُن}\n10. تہٕ سُہ تہِ چُھہ بہادُر، یٔمۍ سُند دِل شیر سُند دِل چُھ، سُہ گژھہِ پوٗرٕ پٲٹھـ̡ پۯاوُن: تکیازِ سارِنٕے اسرٲیلِس چُھ زانان زِ تُہند مول چُھ اکھ طاقتور انسان، تہٕ {تِم} یُس أمِس سٍتـ̡ بہادر چُھ۔ \n11. تێمہِ کِنۍ چُھس بہٕ مشورٕ دِوان زِ سارِنٕے اِسرٲیلِس گژھہِ عام طور ژے سٍتـ̡ جمع کرنہٕ، دان پیٹھٕ بیرشبع تام، یُس سمندرس سٍتـ̡ بٔڈِس سٍتـ̡ بٔڈِتھ چُھ۔ تہٕ یێلہِ تہٕ ژے گژھہِ پننِس شخصس سٍتـ̡ جنگس مَنٛز گژھُن۔ {یُس تُہہ...: حب۔ یُس تُہُند بُتھ، نتہٕ، حٲضِر گژھُن، بیترِ}\n12. یِتھے پٲٹھۍ گژھو أسۍ أمِس کُنہِ جایہِ یُتھ سُہ لبنہٕ ییہِ، تہٕ أسۍ کرو أمِس سٍتـ̡ یِتھٕ پٲٹھۍ شبنم زمینس پیٹھ پٮ۪وان: تہٕ أمِس تہٕ أمِس سٍتـ̡ سارِنٕے نفرن ہٕندِس سٍتـ̡ گژھہِ نہٕ أکِس سٍتـ̡ تہٕ یێلہِ سٍتـ̡ سٍت \n13.\\tامہِ علاوہ اگر سُہ کُنہِ شہرس مَنٛز اَننہٕ یِیہ، تیلہِ گژھن سارِوٕے اِسرٲیلِس اَتھ شہرس مَنٛز رزٕ أنِتھ، تہٕ أسۍ کٔرِو یہِ دریاوس مَنٛز، یوٚت تام نہٕ اَتہِ اکھ لۄکُٹ کٔنہِ لبنہٕ ییہِ۔ \n14.\\tتہٕ ابسالوم تہٕ سارِنٕے اسرٲیلِیو ووٚن زِ ہوشایی آرکیت سُند مشورٕ چُھ اہیتوفیل سٕندِ مشورٕ کھوتہٕ بہتر۔ تکیازِ خداوند اوس احیتھوفیل سٕندِس نیک مشورس شکست دِنہٕ خٲطرٕ مقرر کورمُت، یُس خداوند کرِ ابسلومس پیٹھ بد کار۔ {مُقرر: حب۔ حُکُم}\n15.\\tاَمہِ پَتہٕ ووٚن ہوشایی زادوک تہٕ ابیاتھر پادٕرَن سٍت، یِتھٕ پٲٹھۍ کٔر اہیتھوفیلن ابسالوم تہٕ اسرٲیلٕکۍ بزرگن مشورٕ۔ تہٕ یِتھٕ پٲٹھۍ کٔر میہ مشورٕ۔ \n16.\\tلہذا سوز جلدی تہٕ داؤدس ونُن زِ از رٲژ روزُن نہٕ بیابان کین مٲدانن مَنٛز، بلکہ گژھہِ جلدٕے نیرُن۔ یُس بادشاہ تہٕ سارِنٕے لُکھ یِم أمِس سٍتـ̡ چھِ۔ \n17.\\tوۅنۍ رودۍ جوناتھن تہٕ احیماز اینروگلس نِش۔ تکیازِ تِم ٲسۍ نہٕ شہرس منز یِنہٕ وچھنہٕ آمٕتۍ، تہٕ اَکھ وُچھن تہٕ تِمن وونُن۔ تہٕ تِم گٔیہِ تہٕ ووٚن بادشاہ داوُد۔ \n18.\\tبہر حال وُچھ أکۍ لڑکہٕ تِم تہٕ وونُن ابسالوم: مگر تِم گٔیہِ دۅشوے جلدی ژٔلِتھ تہٕ آیہِ بہوریمس منز أکِس شخصہٕ سٕندِس مکانس منز، یُس تٔمۍ سٕندِس دربارس مَنٛز اکھ کۄر اوس۔ کتہِ گٔیہِ تِم بۄن۔ \n19.\\tتہٕ زنانہِ رٔٹِتھ کُنہِ \n20.\\tتہٕ ییلہ ابسالوم سٕندِ نوکر زنانہِ نِش گرس منز آیہ، تِمو ووٚن، احیماز تہٕ جوناتھن کتہِ چھِ؟ تہٕ زنانہِ ووٚن تِمن آبہٕ کِس نالہِ پیٹھ۔ تہٕ ییلہ تِمو ژھانڈان تہٕ لٔبِتھ نہٕ، تِم گٔیہِ یروشلم واپس۔ \n21.\\tتہٕ یِمن ہٕندِ نیرنہٕ پَتہٕ آو تِم کۅرٕ منزٕ نیرِتھ تہٕ گٔیہِ بادشاہ ڈیوڈس وَنُن، تہٕ وونُن داوڈس زِ وۅتھٕ وُچھِو تہٕ آبس اپارِ نیرُن، تِکیازِ یِتھٕ پٲٹھۍ چھُ اہیتھوفیلن توے خلاف مشورٕ دِژمُت۔ \n22.\\tپَتہٕ ووت داؤد تہٕ تِم سٲری لُکھ یِم أمِس سٍتـ̡ ٲسۍ، تہٕ تِم گٔیہِ اردن کِس گاشس سٍتـ̡ یِمو منزٕ کانہہ تہِ نہٕ یُس اردنس پیٹھ گٔژھمُت اوس۔ \n23.\\tتہٕ ییلہ اہیتھوفیلن وُچھ زِ تٔمۍ سٕندِس مشورس پیٹھ آو نہٕ عمل کرنہٕ، تٔمۍ کٔر پنہٕ نِس گَرٕ کُن، تہٕ ووٚتھ، تہٕ کوٚرُن پنُن گرٕ پننِس گھرس منز، پننِس شہرس منز، تہٕ کوٚرُن پنُن گرٕ ترتیب دِنہٕ، تہٕ پھٲنسی دِژُن تہٕ موٗدُن تہٕ سپُد پننِس مٲلہِ سٕندِس قبرس مَنٛز دفن۔ {پتہٕ: ہیب۔ ﴿پَنٕنـ̡ ہٕندِس گَرٕ سٍتـ̡ دِیُتُن دِنہٕ}\n24. پَتہٕ آو داؤد مہانایمس نِش۔ تہٕ ابسالوم ووت اردن پیٹھ، سُہ تہٕ سارِنٕے اسرٲیلِکۍ مرد أمِس سٍتـ̡ ۔ \n25.\\tتہٕ ابسالوم بنوو عماسہ یوآب سٕندِ بدلہٕ میزبانُک کپتان، یُس عماسہ اوس أکِس انسانس سُند نیچو، یُس اِتھرا سُند ناو اوس، یُس زرویاہ یوآب سٕنزِ ماجہ ہٕنز بینہِ ٲس۔ {اِتھرا اَن اسرٲیلِی: یا، یتھر اِسماعیلِی} {ابیگیل: حب۔ ابیگل} {ناحش: یا، یسی}\n26.\\tیێلہِ گٔیہِ اسرٲیلِس تہٕ ابسالوم گلعاد کِس سرزمینس مَنٛز۔ \n27.\\tتہٕ سپُد ییلہ داؤد مہانیم آو زِ شوبی یُس ربہ کِس ناہش سُند نیچو آمون سٕندِس اولادُک تہٕ ماکیر یُس لودبار کِس امیلس سُند نیچو اوس، تہٕ روجیلیم سُند گلعاد برزِلای، \n28.\\tبستر، تہٕ بیسن، تہٕ میژِ بانہٕ، تہٕ کٕنٕک، تہٕ جو، تہٕ اوٹ، تہٕ خشک {مکایہ}، تہٕ پھلۍ، تہٕ دال، تہٕ خشک {نبض}، {بیسن: یا، پیالہ}\n29. تہٕ ماچھ، تہٕ تھنہٕ، تہٕ کۅکر، تہٕ کۅکرِ ہُند پنیر، داؤد سٕندِ خٲطرٕ، تہٕ تِمن لُکن ہٕندِ خٲطرٕ یِم أمِس سٍتـ̡ ٲسۍ، کھٮ۪نہٕ خٲطرٕ، تِکیازِ تِمو وَنُن زِ لُکھ چُھہ بیابانن مَنٛز فاقہٕ تہٕ تھکان تہٕ ترش۔","1. تہٕ داؤد کٔرِن تِمن لُکن ہُند شُمار یِم أمِس سٍتـ̡ ٲسۍ، تہٕ تِمن پیٹھ تھووُن ساسہٕ بٔدۍ تہٕ ہتہٕ بٔدۍ کپتان۔ \n2. تہٕ داؤدن سوُز لُکن ہُند تریم حصہٕ یوآب سٕندِس اتھس تل تہٕ تریم حصہٕ یوآب سٕندِس بٲے زرویاہ سٕندِس نیچوِس ابیشایی سٕندِس اتھس تل تہٕ تریم حصہٕ اِتایی گیتِس سٕندِس اتھس منز۔ تہٕ بادشاہن ووٚن لُکن زِ بہٕ نیرٕ یٔقیٖنی طور تہِ ژےٚ سٍتـ̡ نیران۔ \n3.\\tمگر لوکو دیت جواب، ژیہ گژھ نہٕ نیرُن، تکیازِ اگر أسۍ ژلِو، تِم گژھن نہٕ اسہِ پرواہ کٔرِتھ۔ نَہ اگر اسہِ منزٕ نصف مٔرِتھ، تِم کرِ نہٕ اسہِ ہُند خیال تھاوُن: مگر وۅنۍ چُھہ {تُہہ} اسہِ دَہ ساس ہٕندِس قٲبل: لہذا چُھہ وۅنۍ بہتر زِ ژے کٔرِو اسہِ شہرٕ منزٕ نِش مدد۔ {پرواہ...: ہیب۔ تِہُند دِل تھاوُن اسہِ کُن} {قٲبل...: ہیب۔ اسہِ منزٕ دَہ ساس ہٕندِس پٲٹھۍ} {مدد: ہیب۔ مدد کرُن یا مدد کرُن}\n4. تہٕ بادشاہن ووٚن تِمَن، بہٕ کَرٕ بہٕ کَرُن۔ تہٕ بادشاہ کھڑا دروازٕ نِش تہٕ سارِوٕے لُکھ دٔسۍ ہتہٕ بٔدۍ تہٕ ساسہٕ بٔدۍ دٔسۍ درٛایہِ۔ \n5.\\tتہٕ بادشاہن دِیُت یوآب تہٕ ابیشایی تہٕ اِتایی ہُند حُکُم تہٕ وونُن زِ میانہِ خٲطرٕ کٔرِو نوجوانَس سٍتـ̡ تہٕ اَبسلومس سٍتـ̡ \n6.\\tتہ لُکھ دراو اسرٲیلِس خلاف میدانس منز، تہٕ جنگ سپُد افرایم سٕندِس جنگلس منز۔ \n7. ییتہِ اسرٲیلٕکۍ قوم داؤد سٕندِس خدمتگارن برونہہ کنہِ مارنہٕ آیہ، تہٕ تمہِ دۅہہ سپُد وُہن ساس نفرن ہُند اکھ بٔڈ قتل۔ \n8.\\tتکیازِ جنگ اوس سارِنٕے ملکس کِس بُتھِس پیٹھ پھٔہلِتھ: تہٕ لٔکرِ کھیوٚو تمہِ دۅہہ تلوار کھٮ۪نہٕ کھوتہٕ زیادٕ لُکھ کھٮ۪وان۔ {کھٮ۪نہٕ: ہیب۔ کھٮ۪نہٕ خٲطرٕ گٔیہِ}\n9. تہٕ ابسالوم سمکھیوو داؤد سٕندِس خادمَن سٍتـ̡ ۔ تہٕ ابسالوم گۆو أکِس خچرس پیٹھ سوار تہٕ خچر ژاو أکِس بٔڈِس بلوط کِس گٔنِس لٔنڈِس تَل تہٕ تٔمۍ سُند کلہٕ روٚٹ تہٕ سُہ آو آسمانس تہٕ زمینس درمیان تُلنہٕ۔ تہٕ سُہ خچر یُس أمِس تل اوس، ژٔلِتھ ژٔلِتھ ۔ \n10.\\tتہٕ أکِس شخصس وُچھ تہٕ وُچھُن یوآبس تہٕ وونُن وُچھمُت ابسالوم أکِس بلوطس مَنٛز لوٚٹان۔ \n11.\\tتہٕ یوآبن ووٚن أمِس شخصس یُس أمِس ووٚنمُت اوس، تہٕ وُچھکھ ژے وُچھمُت، تہٕ ژے کیازِ دِژ نہٕ أمِس تتہِ زمینس پیٹھ۔ تہٕ بہٕ ہا ہا ژے دَہ شیکل رۄپہٕ تہٕ اکھ لٔٹۍ۔ \n12.\\tتہٕ أمِس ووٚن یوآبس زِ یۆدوے میہ اتھس منز اکھ ساس شیکل رۄپہٕ میلہِ، {توتہِ} بہٕ کٔرٕ نہٕ بادشاہ سٕندِس نیچوِس خلاف پنُن اتھہٕ، تکیازِ سٲنِس بوزنس مَنٛز دِژ بادشاہن تہٕ ابیشایی تہٕ اِتایی ہُند حکم زِ خبر تھاوُن زِ کانہہ تہِ گژھہِ نہٕ جوان ابسالوم سٕندِس اتھہٕ لاگنہٕ۔ {رٔٹِو: حب۔ میٲنِس اتھس پیٹھ وزن تھاوُن} {خبردار...: حب۔ یُس تہِ تہِ آسہِ، وغیرہ}\n13.\\tنتہٕ ہا ہا میہ پننہِ زُوِ سٍتـ̡ اپُز کٔرِتھ، تکیازِ بادشاہس نِش چھُنہٕ کانہہ تہِ معاملہٕ ژوٗرِ روزان، تہٕ ژے ہا پانس پانس خٕلاف۔ \n14.\\tپتہٕ ووٚن یوآب، بہٕ ہیوٚک نہٕ ژے سٍتـ̡ یِتھٕ پٲٹھۍ روزُن۔ تہٕ تٔمۍ رٔٹِتھ تریہ ڈارٹ پننِس اتھس منز، تہٕ ترووُن ابسالوم سٕندِس دِلس منز، ییلہ سُہ وُنہِ تہِ زِندٕ اوس۔ {سٍت...: حب۔ ژے برونہہ کُن} {درمیان: ہیب۔ دِل}\n15.\\tتہٕ داہ جوان یِمو یوآب سٕندِ ہتھیار نِش لٔگِتھ مارُکھ سُہ مٲرِتھ۔ \n16.\\tتہٕ یوآبن وُپھ بُر، تہٕ لُکھ آو اسرٲیلِس پَتہٕ پَتہٕ واپس، تِکیازِ یوآب رُکٲوِتھ لُکھ رُکاونہٕ۔ \n17. تہٕ تِمو رٔٹِتھ ابسالوم تہٕ ترٛٲوِکھ سُہ لٔڈِس أکِس بٔڈِس گڑھس مَنٛز، تہٕ تھووُکھ أمِس سٍتـ̡ س� \n18.\\tوۅنۍ اوس ابسالوم پننہِ زندگی منز پانس خٲطرٕ اکھ ستون رٹمُت، یُس بادشاہ سٕندِس دلس مَنٛز چُھ، تکیازِ تٔمۍ ووٚن، میہ چُھنہٕ کانہہ نیچو یُس پنُن ناو یاد تھاوُن چُھ، تہٕ تٔمۍ ووٚن اتھ تھمس پننہِ ناوٕ سٍتـ̡ تہٕ از تام چُھ اتھ ابسالوم سٕنز جاے وننہٕ یوان۔ \n19.\\tاَمہِ پَتہٕ ووٚن زادوک سٕندِس نیچوِس احیماز، بہٕ ژلُن تہٕ بادشاہس دِژ خبر زِ کِتھہ پٲٹھـ̡ چُھہ خداوند پننین دُشمنن ہُند انتقام۔ {انتقام...: ہیب۔ أمِس دِژ اَتھٕ سٍتـ̡ فٲصلہٕ، بیترِ}\n20.\\tتہٕ یوآبن ووٚن أمِس زِ ژے گژھِ نہٕ از دۅہہ خبر دِنہٕ، مگر از دۅہہ گژھِ نہٕ ژے خبر دِنہٕ، تکیازِ بادشاہ سُند نیچو چُھ موٗدمُت۔ {یہِ خبر دِیُن: حب۔ بشارت دِنہٕ وول انسان بٔنِتھ بیترِ}\n21.\\tپتہٕ ووٚن یوآب کُشیَس زِ ژے کیا وُچھمُت چھُ۔ تہٕ کُشی ووٚن جوآبس کُن نمُن تہٕ ژوٚلُن۔ \n22.\\tاَمہِ پتہٕ ووٚن صدوق سٕندِس نیچوِس احیماز یُس بییہ اکہِ لٹہِ یوآبس سٍتـ̡ ژلہِ، مگر بہٕ تہِ دُعا کٔرِتھ ژٔل\n23.\\tمگر بہرحال، {ووٚن}، میہ ژلُن۔ تہٕ تٔمۍ ووٚن أمِس ژلُن۔ پتہٕ ژوٚل احیماز میدانی وتہِ کِنۍ تہٕ کُشی ژٔلِتھ۔ \n24.\\tتہٕ داؤد بیوٹھ دۅن دروازن درمِیان تہٕ چوکیدار ووت دیوارس کُن دروازس پیٹھ چھتس پیٹھ، تہٕ تُلِن پنٕنۍ أچھ تُلِتھ تہٕ وُچھُن اکھ نفر کُنی زُن ژلان۔ \n25.\\tتہٕ چوکیدارَن ووٚتھ تہٕ ووٚن بادشاہس ۔ تہٕ بادشاہن ووٚن، اگر سُہ کُنی آسہِ، تٔمِس ٲس ٲسِس مَنٛز خبر دِنہٕ۔ تہٕ سُہ آو جلدٕے تہٕ نزدیک ووتُن۔ \n26.\\tتہٕ چوکیدارن وُچھ بیاکھ نفر ژلان، تہٕ چوکیدارن وُچھ بُلِتھ تہٕ وُچھِو بیاکھ نفر کُنی زُن ژلان۔ تہٕ بادشاہن ووٚن، سُہ تہِ چُھ خبر دِوان۔ \n27.\\tتہٕ چوکیدارن ووٚن، میہ چُھس خیال زِ سارِوٕے کھۄتہٕ زیادٕ سُند دوڑُن چُھ صدوق سٕندِس نیچوِس احیماز سٕندِس دورس ہٕندۍ پٲٹھۍ۔ تہٕ بادشاہن ووٚن سُہ چُھ اَکھ اصل انسان تہٕ بشارت ہیتھ یوان۔ {مے...: حب۔ بہٕ چُھس دوڑان وُچھان}\n28.\\tتہٕ احیماز ووٚن بادشاہس تہٕ وونُن بادشاہس سٍتـ̡ سارِوٕے پٲٹھۍ۔ تہٕ سُہ پیوٚو بادشاہس برونہہ کُن بُتھِس پیٹھ زمینس پیٹھ، تہٕ وونُن، خداوند پنُن خدا، یٔمۍ تِم نفر دِژمٕژ یِمو میٲنِس آقا بادشاہس خلاف اتھہٕ تُلِتھ دِژمٕژ چھِ۔ {سارِنٕے...: یا، سُہ آسُن تُہٕندِس خداہس سٍتـ̡ سلام۔ سُہ چُھہ سُہ سُہ بُتھِس پٲٹھـ̡ بُتھِس پیٹھ پۯاوُن، تہٕ وونُن زِ خداوند چُھس تُہند خدا، یٔمۍ تِمن لُکن دِژ یِمو میٲنِس آقا بادشاہس خٕلاف اتھہٕ تُلِتھ دِژمٕژ۔ {سارِنٕے...: یا، سُہ چُھہ تُہٕندِس خداہس سٍتـ̡ تُلِتھ دِژمُتـ̡ ۔ {سارِنٕے سٍتـ̡ چُھہ تُہُند خدا، یێمہِ سٍتـ̡ چُھ\n29.\\tتہٕ بادشاہن ووٚن، کیا جوان ابسالوم چھا محفوٗظ؟ تہٕ احیماز دیت جواب، ییلہ یوآبن بادشاہ سُند خادم تہٕ میہ تُہند خادم سوزمُت، مے وُچھ اکھ زبردست ہنگامہٕ، مگر میہ ٲس نہٕ خبرے زِ یہِ کیا چُھ۔ {اَہ...: حب۔ کیا امن چھُ؟}\n30.\\tتہٕ بادشاہن ووٚن {أمِس}، پھیُرِو، {تہٕ} کھڑا یَتہِ۔ تہٕ سُہ پھیُر أکِس طرف، تہٕ کھڑا کھڑا۔ \n31.\\tتہٕ وُچھِتھ آو کُشی ۔ تہٕ کُشی ووٚن خبر ، میانہِ مالہِ بادشاہ: کیازِ خداوند چُھ ژے اَز دۅہہ تِمن سارِنٕے سٍتـ̡ یُس ژے خلاف کھڑا سپدِ۔ {بشارت: ہیب۔ خبر چھے دِنہٕ آمٕژ}\n32.\\tتہٕ بادشاہن ووٚن کُشیَس زِ کیا جوان چھَا اَبسلوم محفوٗظ؟ تہٕ کُشی دِیُت جواب، میانہِ آقا بادشاہ سٕندِ دُشمن تہٕ یُس تۅہہِ خلاف یُس تۅہہِ دُکھ دِنہٕ خٲطرٕ کھڑا سپدان چھُ، تِتھۍ گژھُن یُتھ {یہ} جوان {چُھ}۔ \n33.\\tتہٕ بادشاہ گۆو سٮ۪ٹھاہ ہُرر، تہٕ ووت دروازس پیٹھ کمرس کُن تہٕ ووٚنُن، تہٕ یِتھٕ پٲٹھۍ ووٚنُن، اے میون نیچو ابسالوم، میون نیچو، میون نیچو ابسالوم! کاش بہٕ آسہ ہا چانہِ خٲطرٕ مرُن، اے ابسالوم، میون نیچو، میون نیچو!","1. تہٕ یہِ آو وَننہٕ یوآب، وُچھو، بادشاہ چُھ روُن تہٕ ابسالوم سٕندِ خٲطرٕ ماتم کران۔ \n2. تہٕ تمہِ دۅہہ فتح سپٕز سارنٕے لُکن ہٕندِ خٲطرٕ ماتم کرنہٕ: تکیازِ لوکو بوز تمہِ دۅہہ کِتھہ پٲٹھـ̡ بادشاہ پننِس نیچوِس خٲطرٕ غم۔ {فتح: حب۔ نجات یا، نجات دِنہٕ}\n3.\\tتہٕ لُکھ چھِ تمہِ دۅہہ شہرس منز ژوٗرِ پٲٹھۍ، تِکیازِ لُکھ چھِ ژوٗرِ ژٔلِتھ ژٔلِتھ۔ \n4.\\tمگر بادشاہن کٔر پَنُن بُتھ تھوٚپ، تہٕ بادشاہن کٔر بَڑِ آوازٕ سٍتـ̡ وۆن، اے میانہِ نیچو ابسالوم، اے ابسالوم، میون نیچو، میون نیچو! \n5. تہٕ یوآب آو بادشاہس نِش گرس منز، تہٕ وونُن، ژے چُھ از دۅہہ پننین سارِنٕے خادمَن ہٕندِس بُتھِس شرمندٕ کٔرمٕژ، یِمو از تُہٕندِس نیچوِس تہٕ کورِ ہٕنز زُو بچٲومٕژ چھِ، تہٕ چُھہ تُہٕنزِ زنانہٕ ہٕنز زُو بچٲومٕژ۔ \n6. یتھ مَنٛز چُھکھ ژے پَنٕنـ̡ دُشمن سٍتـ̡ محبت کران، تہٕ پَنٕنـ̡ یارن سٍتـ̡ چُھہ نفرت کران۔ تکیازِ ژے چُھہ از دۅہہٕ اعلان کورمُت زِ ژے چُھہ نہٕ شہزادن تہٕ خادمَن ہُند خیال تھاوان: اَمہ دۅہہ چُھس بہٕ وُچھان زِ اگر ابسالوم زندٕ آسہِ، تہٕ أسۍ سارِوٕے از دۅہہ مٔرِتھ آسہِ، تیلہِ آسہِ ژے خۅش گٔژھمٕژ۔ {منز...: حب۔ محبتہٕ سٍتـ̡ بیترِ} {یُس ژے سمجھان چُھ...: ہیب۔ زِ شہزادٕ تہٕ خادم چِھہ نہٕ تۅہہِ خٲطرٕ}\n7.\\tتێلہِ وۆتھ، نیرِو تہٕ پننین خادمَن سٍتـ̡ آرام سان کتھ کرٕن، کیازِ بہٕ چُھس خداوند سٕندِ قسم، یێلہِ نہٕ ژے نیرِو، تێلہِ گژھہِ نہٕ ژے سٍتـ̡ رٲژ تہٕ یُس ژے سٍتـ̡ بێیہِ سٍتـ̡ بێیہِ سٍتـ̡ زیادٕ بدتر آسہِ۔ {آرام سان...: ہیب۔ پننین خادمَن ہٕندِس دلس تام}\n8. پتہٕ ووٚتھ بادشاہ تہٕ بیوٹھ دروازس پیٹھ۔ تہٕ تِمو ووٚن سارنٕے لُکن زِ وُچھ، بادشاہ چُھ دروازس منز بِہان۔ تہٕ سٲری لُکھ وٲتۍ بادشاہس برونہہ کُن، تکیازِ اسرٲیل اوس پرٮ۪تھ کانہہ نفر پننِس خیمس کُن ژلان۔ \n9.\\tتہٕ سارِنٕے لُکھ أسـ̡ اِسرٲیلـ̡ سٍتـ̡ سارِنٕے قبیلن سٍتـ̡ لڑایہِ، یہِ وَنُن زِ بادشاہن بچٲو اسہِ دُشمن ہٕندِ اتھہٕ نِش تہٕ بێیہِ أسـ̡ فلسطینن ہٕندِ اتھہٕ نِش بچٲوِتھ ۔ تہٕ وُنہِ چُھ سُہ اَبسالوم سٕندِ خٲطرٕ زمینہٕ نِش ژلان۔ \n10. تہٕ ابسالوم، یُس أسۍ پانس پیٹھ مسح کورمُت، چُھ جنگس مَنٛز موٗدمُت۔ تێلہِ کیازِ چُھہ نہٕ بادشاہس واپس اننٕچ کتھ کٔرِتھ؟ {کتھ کٔرِو...: ہیب۔ کیا تُہۍ چھوا ژھۄپہٕ کٔرِتھ؟}\n11. تہٕ بادشاہ داوُد سوٗز زادوک تہٕ ابیاتھرس نِش پادٕرۍ، یہوداہ کین بزرگن سٍتـ̡ کتھ کرٕن، تہٕ وونُن زِ تُہۍ کیازِ چُھکھ ٲخری بادشاہ سٕندِس گرس منز واپس انان۔ سارِنٕے اسرٲیلٕچ کتھ وُچھِتھ چُھ بادشاہس نِش آمُت، حتیٰ کہ تٔمۍ سٕندِس گرس مَنٛز۔ \n12. تُہۍ چھِو میٲنۍ بٲے تہٕ میٲنۍ ماز تہٕ میٲنۍ ماز چھِو: تیلہِ کیازِ چھِو تُہۍ ٲخری بادشاہ واپس انن؟ \n13.\\tتہٕ چُھکھ اماساہَس وَنُن، کیا تُہۍ چھُکھ نہٕ میانہِ أڈجہِ تہٕ میانہِ مازُک تہٕ میانہِ مازُک؟ خدایہ کٔرِکھ میانہِ سٍتـ̡ یێلہِ تہٕ زیادٕ تہِ، یێلہِ نہٕ ژٕ میہ برونہہ کُن لگاتار یوآب سٕندِس کمرس مَنٛز لگاتار میزبانُک کپتان آسہِ۔ \n14.\\tتہٕ تٔمۍ کٔر یہوداہ کین سارنٕے نفرن ہُند دِل نمُن، یێلہِ سٍتـ̡ اَکہِ شخصہٕ سُند دِل اوس۔ یێلہِ تِمو سوزُکھ {یہِ لفظ} بادشاہس نِش، تہٕ پَنٕنـ̡ سارِنٕے خادمَن واپس۔ \n15.\\tبادشاہ آو واپس، تہٕ آو اردن کُن۔ تہٕ یہوداہ آو گلگل، بادشاہس سمکھنہٕ خٲطرٕ، بادشاہس اردنس پیٹھ قبضہ کرنہٕ خٲطرٕ۔ \n16.\\tتہٕ شیمی، یُس بنیامین سُند نیچو اوس، یُس بہوریمُک اوس، ووت یہوداہ کین نفرن سٍتـ̡ بادشاہ داؤدس سمکھنہٕ خٲطرٕ۔ \n17.\\tتہٕ تٔمِس سٍتـ̡ ٲس ساس بنیامین سٕندِ سٍتـ̡ ساؤل سٕندِ گرُک خادم، تہٕ تٔمِس سٍتـ̡ پنٛداہ نیچوۍ تہٕ تٔمِس سٍتـ̡ وُہ نوکر۔ تہٕ تِم گٔیہِ بادشاہس برونہہ کُن اردنس پیٹھ۔ \n18.\\tتہٕ گٔیہِ أکِس ناوِ ہٕندِس گَرٕ سٍتـ̡ نِنہٕ مۅکھہٕ، تہٕ یُس أمِس جان زانان اوس تہٕ یُس أمِس جان باسان۔ تہٕ گیرہ سُند نیچو شیمی پیوٚو بادشاہس برونہہ کُن، یُس اردن اپارِ آو ۔ {کیا...: ہیب۔ تٔمۍ سٕندِس أچھن مَنٛز نیکی}\n19.\\tتہٕ ووٚنُن بادشاہس زِ میانہِ آقا گژھِ نہٕ میانہِ سٍتـ̡ بدکاری کٔرِتھ، تہٕ تێہہ گژھہِ یاد روزُن یُس تُہٕندِس خادمَن دۅہہ یُس میانہِ آقا بادشاہ یروشلم منزٕ نیرِمُت اوس، تہٕ بادشاہ گژھہِ یہِ پننِس دِلس پیٹھ نِنہٕ۔ \n20. تێلہِ چُھس تێلہِ چُھس پتاہ زِ میہ چُھہ گۅناہ کورمُت، تێمہِ کِنـ̡ چُھس بہٕ یۆسف سٕندِس سارِنٕے گرس مَنٛز گۄڈنِچہِ لٹہِ آمُت زِ بہٕ چُھس پننِس آقا بادشاہس سمکھنہٕ خٲطرٕ بۄن نیران۔ \n21.\\tمگر زرویاہ سٕندِس نیچوِس ابیشایی ین دیت جواب تہٕ وونُن زِ شِمیعی گژھہِ نہٕ امہِ مۅکھہ مارنہٕ یُن، کیازِ تٔمۍ کٔر خداوند سٕندِس مسح کرنہٕ آمتس لعنت؟ \n22.\\tتہٕ داؤدَن ووٚن، اے زرویاہ سٕندِ نیچو، میہ کیا چُھہ ژے سٍتـ̡ یُس از دۅہہ میانہِ سٍتـ̡ دُشمن بٔنـ̡ ۔ کیا از دۅہہ گژھہِ اسرٲیلـ̡ سٍتـ̡ کانہہ انسان مارنہٕ یُن؟ تێکیازِ بہٕ چُھس نہٕ پتاہ زِ بہٕ چُھس از دۅہہ اسرٲیلُک بادشاہ؟ \n23.\\tتَمہِ کِنۍ ووٚن بادشاہَن شِمیعی یَس زِ ژٕ گژھ نہٕ مَرُن۔ تہٕ بادشاہَن کٔر أمِس سٍتـ̡ قَسم۔ \n24.\\tتہٕ ساؤل سُند نیچو میفیبوشیث آو بادشاہس سمکھنہٕ خٲطرٕ، تہٕ بادشاہ سٕندِ نیرنہٕ کہِ دۅہہٕ پیٹھٕ اوسُن نہٕ پَنٕنِس کھۅر تہٕ داڑھ ژٹنہٕ تہٕ نہ پَنٕنۍ پلو چھلاون، ییمہِ دۅہہ سُہ دُبارٕ یِنہٕ سٍتـ̡ سُہ دُبارٕ یِنہٕ وٲلِس دۅہہٕ سٍتـ̡ یِنہٕ وٲلِس دۅہہٕ س� \n25.\\tتہٕ ییلہ سُہ بادشاہس سمکھنہٕ خٲطرٕ یروشلم آو تہ بادشاہن ووٚن أمِس زِ ژے کیازِ چُھکھ نہٕ میہ سٍتـ̡ میفیبوشیتھ؟ \n26. تہٕ تٔمۍ دیُت جواب، اے بادشاہ، میانہِ خادمَن کٔر مےٚ دھوکہٕ، تکیازِ تٔمۍ سٕندِس خادمَن ووٚن، بہٕ کٔرٕ پانس اکھ گَرٕ لاگُن، یُتھ بہٕ اتھ پیٹھ سوار گژھِتھ، تہٕ بادشاہس نِش گژھُن۔ تکیازِ تُہند خادم چُھ لوٚنگ۔ \n27. تہٕ تٔمۍ کٔر تُہٕندِس خادمَس مٲنِس آقا بادشاہس سٍتـ̡ بدنام۔ مگر میون آقا بادشاہ چُھہ خدایہِ سُند فرشتہٕ پٲٹھۍ: تێمہِ کِنۍ کٔرِو تۅہہِ ہٕندِس نظرس منز کیا چُھہ نیکی ۔ \n28.\\tمیانہِ مٲلہِ سُند گرٕ اوس میانِس آقا بادشاہس برونہہ کُن مٔرۍمٕتۍ، توتہِ تھووُکھ پَنُن نوکر تِمن مَنٛز یُس پننہِ دسترَس پیٹھ کھٮ۪وان اوس۔ تێلہِ کیا چُھس میہ وُنہِ تہِ بادشاہس نِش وُنُن کُنہِ تہِ حق دِنہٕ۔ {مٔرۍ...: ہیب۔ مرنٕکۍ مرد}\n29.\\tتہٕ بادشاہن ووٚن أمِس زِ ژے کیازِ چُھکھ پنٕنۍ کتھ کٔرِتھ؟ مے چُھس ووٚنمُت، ژے تہٕ زیبا چھِو زمینہٕ بٲگرٲوِتھ۔ \n30. تہٕ میفیبوشیتن ووٚن بادشاہس زِ آ، سُہ نِن سارِنٕے نِن، کیازِ میون آقا بادشاہ چُھ امن سان پننِس گرس منز یِوان۔ \n31.\\tتہٕ برزیلائی گلعاد آو روجیلیم پیٹھٕ بۄن تہٕ بادشاہس سٍتـ̡ ووت اردنس پیٹھ۔ \n32.\\tوۅنۍ اوس برزِلایی سٮ۪ٹھاہ بُزرگ شخٕص، ژۅن وُہُر تہٕ تٔمۍ اوس مہنایمس منز روزنہٕ وِزِ بادشاہ رزق فراہم کورمُت۔ تکیازِ سُہ اوس واریاہ بٔڈ انسان۔ \n33.\\tتہٕ بادشاہن ووٚن برزیلایی یس زِ ژٕ گژھ میہ سٍتـ̡ تہٕ بہٕ کرٕ ژے پانس سٍتـ̡ یروشلمس مَنٛز کھیٛان۔ \n34.\\tتہٕ برزیلایی ین ووٚن بادشاہس زِندٕ روزُن، بہٕ گژھہِ بادشاہس سٍتۍ یروشلمس تام گژھُن؟ {کتھہ پاٹھۍ...: ہیب۔ میانہِ زندگی ہندۍ کٲتیا ؤری چھہِ}\n35.\\tبہٕ چُھس از ژۅن ؤرین ہُند وٲنسہِ: {تہٕ}کیا بہٕ ہیوٚک نیکی تہٕ بدس درمیان فرق کٔرِتھ؟ کیا بہٕ چُھس یُس بہٕ کھٮ۪وان تہٕ کیا چیٚوان چُھس؟ بہٕ ہیکہٕ بییہ تہِ گٮ۪ون مردن تہٕ زنانن ہٕنز آواز بوزِتھ؟ تیلہِ کیازِ چُھس تُہند خادم میٲنِس آقا بادشاہس خٲطرٕ بوجھ؟ \n36.\\tتُہند خادم گژھِ بادشاہس سٍتـ̡ اردن کِس کُنہِ وتہِ پیٹھ، تہٕ بادشاہ کیازِ دِیہِ میہ یُتھ انعام۔ \n37.\\tچانہِ خادم، بہٕ چھُس دُعا کران زِ بہٕ گژھہٕ پننِس شہرس مَنٛز مرُن، {تہٕ گژھہٕ پننِس مٲلہِ تہٕ ماجہ ہٕنزِ قبرِ پیٹھ دفن کرنہٕ}۔ مگر وُچھو پنُن خادم چِمہم۔ سُہ گژھ میٲنِس آقا بادشاہس سٍتـ̡ نِش نیرُن۔ تہٕ أمِس کٔرِو یُس تۅہہِ سٍتـ̡ رٔٹِتھ آسہِ۔ \n38.\\tتہٕ بادشاہن دیُت جواب، چِمہم گژھِ میہ سٍتـ̡ یُس ژے رٔلِتھ تہٕ بہٕ کٔرٕ أمِس سٍتـ̡ یُس ژے رٔلِتھ آسہِ، تہٕ یُس تہٕ ژے میانہِ خٲطرٕ یُس تہِ منگناوُن آسہِ، سُہ کٔرٕ بہٕ تہٕ کٔرِتھ تہٕ بہٕ کٔرٕ ژے خٲطرٕ۔ {ضرورت: حب۔ ژٲر}\n39.\\tتہٕ سارِوٕے لُکھ گٔیہِ اردنس اپارِ۔ تہٕ ییلہ بادشاہ آو ، بادشاہن کٔر برزِلایی بوسہ تہٕ دُعا دِژ۔ تہٕ سُہ آو پننہِ جایہ واپس۔ \n40.\\tپتہٕ گوٚو بادشاہ گلگلس کُن، تہٕ چِمہام ووت أمِس سٍتـ̡ تہٕ یہوداہ کٮ۪و سارِوٕے لوکو بادشاہ تہٕ نٮ۪صف اسرٲیلٕکۍ لُکھ تہِ۔ {چِمہم: حَب۔ چِمہَن}\n41.\\tتہٕ وُچھ سارِوٕے اِسرٲیلٕکۍ مرد وٲتِتھ بادشاہس نِش تہٕ وونُن بادشاہس زِ سانٮ۪و بٲے یہوداہ ہٕندِس مردو کیازِ ژوٗرِ ژوٗرِ تہٕ بادشاہ تہٕ أمۍ سُند گرٕ تہٕ داؤد سٕندِ سارِنٕے نفر پانس سٍتـ̡ اردنس پیٹھ أنِمٕتۍ۔ \n42.\\tتہٕ یہوداہ کٮ۪و سارِوٕے مردو دِژ اسرٲیلِکۍ مردَن جواب، کیازِ بادشاہ چُھ اسہِ سٍتـ̡ رشتہٕ دار، تێلہِ کیازِ چُھہ تۅہہ اتھ معاملس پیٹھ ناراض؟ کیا أسـ̡ چُھہ بادشاہ سٕندِس سارِوٕے قٕسمس کھٮ۪وان؟ کِنہٕ چُھہ تٔمۍ اسہِ کانہہ تحفہٕ دِژمُت؟ \n43.\\tتہٕ اسرٲیلِیو دِژ یہوداہ کین لوکن جواب تہٕ وونُن، اسہِ چھِ بادشاہس مَنٛز داہ حصہٕ، تہٕ اسہِ چھُ داؤدس مَنٛز تہِ زیادٕ حق، تیلہِ کیازِ کٔر تۅہہ اسہِ حقارت زِ سون بادشاہ واپس اننہٕ خٲطرٕ گژھہِ نہٕ سون مشورٕ دِنہٕ۔ تہٕ یہوداہ کین لوکن ہٕندِ کلامَن ہٕندِس کلامَس سٍتـ̡ اوس اسرٲیلِہ کین لوکن ہٕندِس کلامَو کھۅتہٕ زیادٕ زور۔ {حقارت کٔرِو...: حب۔ اسہِ کٔرِو گاش}","1. تہٕ اَتہِ اوس بِلیالُک اَکھ شخٕص، یٔمۍ سُند ناو اوس شیبا، یُس بِکری سُند نیچو اوس، تہٕ تٔمۍ ووٚن بُرٕ تہٕ وونُن، اسہِ چُھنہٕ داؤدس سٍتـ̡ کانہہ حصہٕ، تہٕ نۂ چُھہ اسہِ یسیٰ سٕندِس نیچوِس سٍتـ̡ وراثت: اے اسرائیل۔ \n2.\\tتہ ووت پریتھ کانہہ انسان داؤد سٕندِ نیچو شیبا سٕندِ پٲٹھۍ، مگر یہوداہ ہٕکۍ مرد گٔیہِ پننِس بادشاہس سٍتۍ، اردن پیٹھٕ یروشلمس تام۔ \n3.\\tتہٕ داؤد آو یروشلمس مَنٛز پننِس گَرَس مَنٛز۔ تہٕ بادشاہن رٔٹِتھ دَہ زنانہٕ یِم گھرٕ تھاونہٕ خٲطرٕ ترٲومٕژ ٲس، تہٕ تھووُن تِمن نِش کھٮ۪نہٕ، مگر تِمن نِش گٔیہِ نہٕ۔ یێمہِ کِنۍ گٔیہِ تِم مرنہٕ کِس دۅہس تام بنٛد کٔرِتھ، بیواہ پٲٹھۍ۔ {وارڈ: ہیب۔ وارڈُک اکھ گرٕ} {بند...: ہیب۔ بٔنِتھ} {زندٕ...: ہیب۔ زندگی ہٕنزِ بیواہ ہٕندِس دۅہس منز}\n4.\\tاَمہِ پتہٕ ووٚن بادشاہن اماساہَس زِ مےٚ کٔرِو یہوداہ ہٕکۍ نفر ترٮ۪ن دۅہن انٛدر جمع تہٕ یێتہِ گژھِو موجود۔ {جمع کٔرِو: ہیب۔ بلاو}\n5.\\tتہ اماسا گۆو یہوداہ کین نفرن جمع کرنہِ، مگر سُہ روٗد تمہِ مقرر وقتہ کھوتہ زیادٕ کالس یُس تمس مقرر کورمُت اوس۔ {جمع: ہیب۔ بلاو}\n6. تہٕ داؤد ووٚن ابیشایی یس زِ وۅنۍ کٔرِہ شیبا بشری سٕندِ نیچو اسہِ اَبسالوم سٕندِ کھۅتہٕ زیادٕ نۄقصان دِنہٕ: پنہٕ نِس آقا سٕندِس خادمَس نِش رٔٹِتھ تہٕ أمِس پَتہٕ پَتہٕ لٔگِتھ، نتہٕ گژھہِ أمِس شہرَن ہٕندِس تارس منز، تہٕ اسہِ نِش نِش بچِتھ۔ {ژلُن...: حب۔ سانہِ نظرو نِش بچاو پان\n7.\\tتہٕ تٔمِس پَتہٕ درٛاو یوآب سٕندِ نفر، تہٕ چیریتھی، تہٕ پیلیثی تہٕ سارِنٕے طاقتور نفر، تہٕ تِم درٛاو یروشلم منزٕ نیبر، بیکری سٕندِس نیچوِس شیبا سٕندِس پتہٕ پَتہٕ پَتہٕ۔ \n8.\\tییلہ تِم گِبیونس مَنٛز {چُھ} بٔڈِس کنہِ کُن وٲتِتھ، اماسا گٔیہِ تِمن برونہہ کنہِ۔ تہٕ یُس یوآب سُند پلو لٲگِتھ اوس، سُہ اوس أمِس سٍتـ̡ لٲگِتھ تہٕ اَتھ پٲٹھـ̡ لٔگِتھ ۔ تہٕ یێلہِ سُہ درٛاو سُہ پیوٚو سُہ پیوٚو۔ \n9.\\tتہٕ یوآبن ووٚن عماسہ زِ ژیہ چھکھ صحت مند آسُن، میانہِ بٲے۔ تہٕ یوآبن رٔٹ اماسہ دچھنہِ اتھہٕ سٍتۍ داڑھی تھپھ کٔرِتھ بوسہ دِنہٕ۔ \n10.\\tمگر اماسا ہَن کٔر نہٕ تتھ تلوارس کُن کانہہ توجہ یُس یوآب سٕندِس اتھس منز ٲس، تہٕ لوٚگ أمِس پوٗنٛژمِس پٲٹھۍ، تہٕ لوٚگُن نہٕ أمِس دُبارٕ دِنہٕ۔ تہٕ سُہ موٗد۔ یِتھے پٲٹھۍ لوٚگ یوآب تہٕ ابیشایی تٔمۍ سٕندِس بٲے بِچری سٕندِس نیچوِس شیبا سٕندِس پتہٕ پَتہٕ۔ {مار...: ہیب۔ دوٚگنہٕ نہٕ تٔمۍ سُند ٹاس دوٚگنہٕ}\n11.\\tتہٕ یوآب سُند اکھ نفر کھڑا تہٕ وونُن، یُس یوآبس سٍتـ̡ چُھہ تہٕ یُس داؤد سٕندِ خٲطرٕ چُھ، سُہ گژھہِ یوآبس پَتہٕ نیرُن۔ \n12.\\tتہٕ اماسا ووت شاہراہس منز خونس منز روٚس۔ تہٕ ییلہ أمس وُچھ زِ سٲری لُکھ چھہِ رُکاونہٕ آمٕتۍ، تٔمۍ کٔر اماسا شاہراہ منزہ کھاہس منز، تہٕ ترووُن أمِس پیٹھ اکھ پلو، ییلہ تس وُچھ زِ أمِس نِش یِنہٕ وول پرٮ۪تھ کانہہ شخص کھڑا کھڑا اوس۔ \n13.\\tییلہ سُہ شاہراہ منزہ نیبر کڈنہٕ آو، سٲری لُکھ گٔیہِ جوآب سٕندِس نیچوِس شیبا سٕندِس پَتہٕ۔ \n14.\\tتہٕ سُہ ووت اسرائیلٕکۍ سارِنٕے قبیلو مٔنزۍ ہابیلس تام، تہٕ بیت ماخہ تہٕ سارِنٕے بیرِس تام، تہٕ تِم گٔیہِ اَکہٕ وٹہٕ جمع تہٕ گٔیہِ أمِس پتہٕ۔ \n15.\\tتہٕ تِمو آیہِ تہٕ أمِس بیت ماخاہ کِس ہابیلس مَنٛز گھیرٕ کٔرِتھ تہٕ تِمو ترٛوو شہرس خلاف اکھ بٔٹھہِ، تہٕ سُہ کھڑا خندقس مَنٛز۔ {خندقس منز: یا، نیبرِمِس دیوارس پیٹھ} {لٔٹِتھ: ہیب۔ دِنہٕ خٲطرٕ گٔیہِ}\n16.\\tاَمہِ پَتہٕ دِژ شہرٕ منزٕ أکِس عقلمند زنانہِ ہٕندِس دُعا سٍتـ̡ بوزو، بوزو۔ ونُن، بہٕ چُھس ژے جوآبس نِش دُعا کٔرِتھ یُتھ بہٕ ژے سٍتـ̡ کتھ کرٕنـ̡ ۔ \n17.\\tتہٕ ییلہ سُہ أمِس نِش ووت، زنانہِ ووٚن، {آرٹ} ژے یوآب؟ تہٕ تٔمۍ دیُت جواب، بہٕ چھُس سُہ چھُس۔ پتہٕ ووٚن أمِس زِ بوز پننہِ خادمہِ ہٕنز کلام۔ تہٕ تٔمۍ دیُت جواب، بہٕ چُھس بوزان۔ \n18.\\tاَمہ پتہٕ وونُن تِم ٲسۍ پرانہِ زمانس منز کتھ کران تہٕ ونان زِ تِم پرژھن ہابیلس نِش مشورہٕ، تہٕ یِتھٕ پٲٹھۍ کٔر تِمو {معاملہ} ختم۔ {تِم ٲسۍ...: یا، تِمو ٲسۍ ابتداہس منز سیدِ سیود کتھ کٔرِتھ، یێلہِ کرِ تِم ہابیلس پرژھن، تہٕ یِتھٕ پٲٹھۍ کرِ خاتمہٕ}\n19. بہٕ چُھس تِمن مَنٛز اَکھ یُس اسرٲیلس مَنٛز امن تھاوان چُھ، تہٕ تُہۍ چُھہ اِسرٲیلِس مَنٛز اکھ شہر تہٕ اکھ ماجہ تباہ کرنٕچ یژھان: ژٕ کیازِ چُھہ خداوند سُند وراثت نِنہٕ یِوان؟ \n20.\\tتہٕ یوآبن دیُت جواب تہٕ وونُن، میہ نِش دور گژھُن، بہٕ گِلہٕ نِش یا تباہ کرُن۔ \n21.\\tیہِ معاملہٕ چُھ نہٕ یِتھ: مگر کُنہِ نفر، یُس بیکری سُند نیچو چھُ، تُل بادشاہس خٕلاف اتھہٕ تُلُن، حتیٰ کہ داؤدس خٕلاف۔ تہٕ زنانہِ ووٚن یوآبس زِ وچھ تٔمۍ سُند کلہٕ یِیہِ دیوارس پیٹھ ژے کُن تراونہٕ۔ {ناو: ہیب۔ تٔمۍ سٕندِس ناوٕ سٍتۍ}\n22. تێمہِ پَتہٕ گٔیہِ زنانہٕ سارنٕے لُکن نِش۔ تہٕ تِمو ژٔٹِتھ ژٔٹِتھ بیکری سٕندِس نیچوِس شیبا سُند کلہٕ، تہٕ دِژُن یوآبس کُن۔ تہٕ تٔمۍ وُپھ بُن، تہٕ تِم گٔیہِ شہرٕ منزٕ پَنٕنِس خیمہٕ کُن۔ تہٕ یوآب آو یروشلم بادشاہس نِش واپس۔ {ریٹائرڈ: ہیب۔ گٔیہِ بکھرِتھ}\n23.\\tوۅنۍ اوس یوآب سارِنٕے اسرٲیلِس پیٹھ: تہٕ یہوعیدہ سُند نیچو بنیاہ اوس چیریتھین تہٕ پیلتھین پیٹھ: \n24.\\tتہٕ ادورم اوس خراج دِنس پیٹھ: تہٕ یہوشفات نیچو احلود سُند نیچو {اوس} ریکارڈر: {ریکارڈر: یا، یادداشت}\n25.\\tتہٕ شیوا اوس کاتب تہٕ زادوک تہٕ ابیاتھر ٲسۍ پادٕرۍ: \n26.\\tتہٕ ایرا تہِ اوس داؤدس متعلق اکھ اہم حکمران۔ {اکھ سردار...: یا، اکھ شہزادہ}","1. پَتہٕ گۆو داؤد سٕندِس دۅہس منز ؤری پتہٕ ؤری پتہٕ ؤری قحط۔ تہٕ داؤد کٔر خداوند سٕندِس سوال۔ تہٕ خداوند دیُت جواب، {یہ} چُھہ ساؤل سٕندِ خٲطرٕ، تہٕ {تٔمِس} خونریز گرٕ خٲطرٕ، کیازِ تٔمۍ مارۍ گِبعونی ۔ {پرژھہ...: حب۔ بُتھ ژھانڈُن، بیترِ}\n2. تہٕ بادشاہن بُلوو گِبعونی تہٕ وونُن تِم۔ (وُنہِ ٲس نہٕ گِبعونی یِمن ہٕندِس بٔلِس سٍتـ̡ ، بٔلکہِ امورِین ہٕندِس باقٕے سٍتـ̡ ۔ تہٕ بنی اسرٲیلِیو اوس تِمن سٍتـ̡ قَسم کٔرمُت، تہٕ ساؤلن کٔر تِمن ہٕندِس جوشس سٍتـ̡ اسرٲیلـ̡ تہٕ یہوداہ کِس بُلِس سٍتـ̡ مارنٕچ کوٗشش۔\n3. کیازِ ووٚن داؤدن گِبعونیس سٍتـ̡ بہٕ کیا کٔرِتھ تہٕ بہٕ کٔرِتھ تہٕ بہٕ کٔرِتھ تہٕ کٔرِتھ کُنہِ خٲطرٕ؟ تہٕ بہٕ کَمہِ سٍتـ̡ کفارہٕ کٔرِتھ، یُتھ تُہۍ خداوند سٕندِس وٲرثس برکت دِتھ؟ \n4. تہٕ گبعونی ووٚن أمِس زِ اسہِ آسہِ نہٕ ساؤل سُند رۄپہٕ تہٕ سۄن، تہٕ نہ تٔمۍ سٕندِس گرس سٍتـ̡ ۔ تہٕ اسہِ خٲطرٕ کٔرٕکھ نہٕ اسرٲیلِس مَنٛز کٲنسہ تہِ نفرس مٲرِتھ۔ تہٕ تٔمۍ ووٚن، یێلہِ تہٕ ژے کیا وَنُن، {سُہ کَرٕ بہٕ تہٕ تہٕ سُہ کرُن}۔ {أسـ̡ کرِ...: یا یہ چُھہ نہٕ رۄپہٕ تہٕ سۄنہٕ یُس اسہِ ساؤلس سٍتـ̡ یا تٔمۍ سٕندِس گرس سٍتـ̡ کرُن، تہٕ نہ چُھہ اسہِ سٍتـ̡ مارُن وغیرہ}\n5.\\tتہٕ تِمو دِژ بادشاہس جواب، یُس انسان یُس اسہِ کھٮ۪وان اوس، تہٕ یُس اسہِ خلاف سازش کورمُت {زِ}أسۍ گژھِ اسرٲیلِس کِس کُنہِ تہِ ساحلس منز روزنہٕ نِش تباہ کرنہٕ یُن، {ساز...: یا ژٔٹِتھ ژٔٹِو}\n6.\\tتٔمۍ سٕندِس سَتھ نیچوۍ یِن اسہِ نِش حوالہٕ کرنہٕ، تہٕ أسۍ کرو تِم خداوند سٕندِس ساؤلس سٍتـ̡ پھٲنسی دِنہٕ، یُس خداوند سُند ژٲرمُت چُھ۔ تہٕ بادشاہن ووٚن، بہٕ دِیہٕ تِمن دِنہٕ۔ {کُس...: یا، خداوند سٕندِ طرفہٕ ژارنہٕ آمُت}\n7. مگر بادشاہن بچٲو ساؤل سٕندِس نیچو یوناتھن سُند نیچو میفیبوشیتھ، تکیازِ خداوند سُند حلف اوس یُس تمن درمِیان اوس داؤد تہٕ ساؤل سٕندِس نیچوِس یوناتھن درمِیان اوس۔ \n8. مگر بادشاہن نِیہِ رِزپا سٕندِ زٕ نیچوۍ، یُس ساؤل، آرمونی تہٕ میفیبوشیتھس نِش زٲو۔ تہٕ ساؤل سٕنزِ کورِ میخال سٕندِ پانژھ نیچِوۍ، یُس تٔمۍ برزیلائی سٕندِس نیچوِس ادریلس خٲطرٕ پرورش کٔرِتھ: {میخال: یا، میکل سٕنز بینہِ} {أنِو...: ہیب۔ ادریلس کُن بٔرِتھ\n9. تہٕ تِمو دِژ تِم گِبعونی ہٕندِس اتھس مَنٛز، تہٕ تِمو دِژ خداوند سٕندِس برونہہ کُن بالہٕ پٲٹھۍ، تہٕ تِم گٔیہِ سَتھ اِکہٕ وٹہٕ، تہٕ یِم گٔیہِ فصلہٕ کِس دۅہہَس مَنٛز، گۄڑنِکِس دۅہَس مَنٛز، جوہٕ کِس فصلہٕ کِس آغازس مَنٛز۔ \n10.\\tتہٕ آیہ سٕنزِ کورِ رزپاہ تُل کُنہِ پتھرس پیٹھ، یێلہِ ووت تِمن پیٹھ آب وُسنہٕ پیٹھ، تہٕ دِژ نہ ہوہٕکۍ جاناوار دۅہلہٕ تہٕ نہ رٲژ کھاہن ہٕندِس درندَس سٍتـ̡ آرام کٔرِتھ۔ \n11.\\tتہٕ داؤدس آو وننہ زِ ساؤل سٕنزِ لونڈی آیہ آیہ سٕنزِ کورِ رزپاہَن کیا کورمُت۔ \n12.\\tتہٕ داؤد گۆو تہٕ یُس ساؤل سٕنزِ أڈجہِ تہٕ پننِس نیچوِس یوناتھن سٕنزِ أڈجہِ یِمو تِم بیت شان چہِ سڑکہِ پیٹھٕ ژوٗرِ نِمٕژ، یێتہِ فلسطینیو ساؤل گلبوا ہس مَنٛز قتل کٔرۍمٕتۍ۔ \n13. تہٕ تٔمۍ کٔر تتہِ ساؤل سٕنزِ أڈجہِ تہٕ پننِس نیچوِس یوناتھن سٕنزِ أڈجہِ۔ تہٕ تِمو کٔر تِمن ہٕنزِ أڈجہِ یِم پھٲنسی دِنہٕ آیہ۔ \n14. تہٕ ساؤل تہٕ تٔمۍ سٕندِس نیچِوِ جوناتھن سٕنزِ أڈجہِ کٔر تِم زیلاہَس مَنٛز بنیامین سٕندِس مُلکَس مَنٛز، یُس تٔمۍ سٕندِس مٲلِس کِش سٕندِس قبرس مَنٛز دفن کٔرِتھ، تہٕ یِمو کٔر بادشاہ سٕندِ حُکُم سٍتـ̡ سٲرۍسٕے کٔرِتھ۔ تہٕ اَمہِ پتہٕ آو خدایہ سٕندِ زمینہٕ خٲطرٕ درخواست کرنہٕ۔ \n15.\\tامہِ علاوہ گۆو فلسطینیو بییہ اسرٲیلِس سٍتـ̡ جنگ۔ تہٕ داؤد گۆو تہٕ تٔمۍ سٕندِس نوکرس سٍتـ̡ لوٚگ فلسطینن سٍتـ̡ تہٕ لوٚگ فلسطینن سٍتـ̡ تہٕ داؤد گۆو بے ہوش۔ \n16.\\tتہٕ اشبیبینوب، یُس دیو سٕندِس نیچوِس {اوس}، یٔمۍ سٕندِ نیزُک وزن {اوس} تریہ ہتھ {شیکل} پیتلُک وزن، أمِس اوس نوِ {تلوار} سٍتۍ لٔگِتھ، یہِ اوس خیال کرنہٕ آمُت زِ تٔمِس اوس داؤد مٲرِتھ۔ {دیو: یا، رافا} {نیزہ: ہیب۔ عصا، یا، کلہ}\n17.\\tمگر زرویاہ سٕندِس نیچوِس ابیشایی کٔر أمِس مدد، تہٕ دِتُن فلسطینس تھپھ کٔرِتھ مارُن۔ اَمہِ پَتہٕ کٔر داؤد سٕندِ نفرو أمِس سٍتـ̡ قسم، یہِ وَنُن زِ ژٕ گژھ نہٕ اسہِ سٍتـ̡ جنگہٕ خٲطرٕ نیرُن، یُتھ نہٕ اسرٲیلُک گاش ژھیتہٕ کٔرِتھ۔ {گاش: حب۔ شَمَبتی، یا چراغ}\n18.\\tتہٕ امہِ پتہٕ سپُد گوبَس مَنٛز فلسطینن سٍتـ̡ دُبارٕ جنگ، تمہ پتہٕ گۆو سِبیچایی ہُشتِین مٲرِتھ صف، یُس دیو سٕندِس نیچوِس سٍتـ̡ اوس۔ {دیو: یا، رافا} {سف: یا، سِپائی}\n19.\\tتہٕ گوبس مَنٛز گۆو فلسطینن سٍتـ̡ دُبارٕ جنگ، یَتھ مَنٛز بیت اللحمی سٕندِس نیچوِس الہانانَن مٲرِتھ گولیات سُند بوے ، یٔمۍ سُند نیزٕ {اوس} وُننہٕ وٲلِس بیمہٕ ہیوٗ اوس۔ {جاریوریجم: یا، جیر}\n20.\\tتہٕ گاتھس منز اوس وُنہِ تہِ اکھ جنگ، ییتہِ اکھ {بٔڈ} قد وول انسان اوس، ییمِس پریتھ اتھس پیٹھ شیہ اونگجہ تہٕ پرٮ۪تھ کھورِ پیٹھ شیہ کھورِ ٲس، ژور تہٕ وُہن تعداد۔ تہٕ سُہ تہِ اوس دیو سٕندِس سٍتـ̡ زامُت۔ {دیو: یا، رافا}\n21.\\tییلہ تٔمۍ اسرٲیلٕچ نافرمانی کٔر، داؤد سٕندِ بٲے شیمعہ سٕندِ نیچو جوناتھن مار۔ {مخالفت: یا ملامت کٔرِتھ} {شمعہ: شمیعہ تہِ ونان چھِ}\n22.\\tیِم ژۅشوے گٔیہِ گاتھس منز دیو سٕندِ دٔسۍ زامٕتۍ، تہٕ گٔیہِ داؤد سٕندِ اتھہٕ سٍتـ̡ تہٕ تٔمۍ سٕندِس خادمَن ہٕندِ اتھہٕ سٍتـ̡ پیوٚو۔","1. تہٕ داؤد کٔر خداوند سٕندِ امہِ بٲتُک کلام تمہِ دۅہہٕ {یُس} خداوند سُہ پنہٕ نِس سارِنٕے دُشمنن ہٕندِ اتھہٕ نِش تہٕ ساؤل سٕندِ اتھہٕ نِش نجات دِژمُت: \n2. تہٕ ووٚن خداوند میٲنۍ کَنہِ تہٕ میٲنۍ قعلہٕ تہٕ میٲنۍ نجات دِنہٕ وول۔ \n3. میانہِ کٔنہِ ہُند خدا؛ بہٕ چُھس تس پیٹھ بھروسہ کرُن: {سُہ چُھ} میٲنۍ ڈھال، تہٕ میانہِ نجات ہُند سینگ، میون تھدِ مینار، تہٕ میون پناہ گاہ، میون نجات دِنہٕ وول چُھ؛ ژے چُھکھ مے تشددٕ نِش بچاو۔ \n4. بہٕ کَرٕ خداوند سٕندِس سٍتـ̡ یُس تعریفس لایق چُھ، یێلہِ بہٕ گژھہٕ پننین دُشمنن نِش بچاوُن۔ \n5.\\tییلہ موتٕچ لہرٕ میہ اندۍ پکھۍ، بے دینی انسانن ہٕندِ سٔلابن کٔر میہ خوف۔ {لہر: یا، دکھ} {بے دین...: حب۔ بلیال}\n6.\\tجہنم کین غمن رُکٲوۍ میہ اندۍ پکھۍ۔ موتکۍ پھیپھ رُکٲوۍ میہ {غم: یا، ڈور}\n7. مُصیبت سٍتـ̡ کٔر میہ خدایہِ سٍتـ̡ بُل، تہٕ تٔمۍ بوز میٲنۍ آواز پننہِ مندرٕ منز، تہٕ میٲنۍ فریاد ژاو تٔمۍ سٕندِس کنن مَنٛز۔ \n8.\\tپَتہٕ لٔج زمینہٕ تھرتھر تہٕ تھرتھر۔ اسمانٕچ بُنیاد گٔیہِ ہلکان تہٕ لٔگِتھ، تکیازِ أمِس اوس شرارت۔ \n9.\\tتٔمۍ سٕنزِ نستہٕ منزٕ ووٚتھ دوٚپ تہٕ ٲسس منز نار دِنہٕ۔ {تسٕنزِ نستہٕ منزٕ: ہیب۔ بے، بیترِ}\n10.\\tتٔمۍ کٔر آسمانس تہِ نم، تہٕ ووت بۄن۔ تہٕ انہِ گوٚٹ اوس تٔمۍ سٕندِس قدمن تل۔ \n11.\\tتہٕ سُہ اوس أکِس کروبس پیٹھ سوار تہٕ وُڑان تہٕ سُہ آو واو ہٕندِس پکھس پیٹھ وُچھنہٕ۔ \n12.\\tتہ بنوو پانس اندۍ پکھۍ گٔنۍ، {تہٕ} آسمانن ہند گٔنۍ اوٚبر۔ {اندھیر...: ہیب۔ آبُک بند}\n13.\\tأمِس برونہہ کُن گاشہٕ سٍتۍ گٔیہِ نارٕکۍ کولہٕ دزنہٕ۔ \n14.\\tخداوند دِژ آسمانہٕ سٍتـ̡ گرٛیٚز، تہٕ اعلیٰ ترین کٔر پَنٕنۍ آواز۔ \n15.\\tتہٕ تٔمۍ سوٗزۍ تیر تہٕ پھٔٹِتھ پھِرِتھ۔ بجلی تہٕ دِژٕن تِم پریشان۔ \n16.\\tتہٕ سمندرٕچ نالہٕ گٔیہٕ ظٲہر، دنیاہٕچ بُنیاد گٔیہٕ دریافت کرنہٕ، خداوند سٕندِ ملامت سٍتـ̡ تہٕ تٔمۍ سٕنزِ نستہٕ ہٕندِس پھٹنہٕ سٍتـ̡ ۔ \n17.\\tتٔمۍ سوٗز ہیرِ پیٹھ، تٔمۍ نِش مے نِنہٕ۔ تٔمۍ کٔر میہ واریاہو آبو منزٕ نیبر۔ {واریاہ : یا، عظیم}\n18.\\tتٔمۍ بچٲو میہ میٲنس مضبوط دُشمن نِش، تہٕ تِمو نِش یِم میہ نفرت کران ٲسۍ، تکیازِ تِم ٲسۍ میانہِ خٲطرٕ واریاہ مضبوط۔ \n19.\\tیِمو رُکٲوۍ میہ مُصیبت ہٕندِس دۅہہٕ مگر خداوند اوس میون قیام ۔ \n20.\\tتٔمۍ اوٚن میہ أکِس بٔڈِس جایہ تہِ، تکیازِ سُہ اوس میہ سٍتـ̡ خۅش کران۔ \n21.\\tخداوند دیت میہ میانہِ نیکی مطٲبق انعام: میانین اتھن ہنز پاکیزگی مطٲبق دیت میہ بدلہٕ۔ \n22. تکیازِ میہ چُھہ خداوند سٕنزِ وتہٕ رژھرٲومٕژ، تہٕ چُھس نہٕ بدکار سٍتـ̡ پننِس خداہس نِش دور گومُت۔ \n23.\\tتٔمۍ سٕندِس سارِنٕے فٲصلن مۅکھہٕ تہٕ تٔمۍ سٕندِس قونونس متعلق، بہٕ ووت نہٕ تِمن نِش دور۔ \n24.\\tبہٕ تہِ اوسُس أمِس برونہہ کُن سیدٕ تہٕ پنُن پان پننہِ بدکاری نِش بچاومُت۔ {برونہہ: ہیب۔ تو}\n25. تێمہِ کِنۍ چُھ خداوند میانہِ نیکی مُطٲبق بدلہٕ دِژمُت۔ تٔمۍ سٕنزِ نظرِ مُطٲبق چُھہ میانہِ پاکیزگی مُطٲبق۔ {منز...: ہیب۔ تٔمۍ سٕنزِ أچھن برونہہ کُن}\n26.\\tرحم کرن وٲلس سٍتۍ کٔرِو توے پان رحم کٔرِتھ تہٕ نیک انسانس سٍتۍ کٔرِو پنُن پان سیدِ سیود ہاونہٕ۔ \n27.\\tپاکیزگی سٍتۍ کٔرِو ژے پنُن پان پاک ہاوُن۔ تہٕ بدمعاشس سٍتۍ کٔرِو پنُن پان ناپسندیدگی ہاونہٕ۔ {پنُن پان ہٲوِو ناپسندیدہ: یا کُشتی کٔرِو}\n28.\\tتہٕ یِمن مُتٲثِر لُکن ہٕندِس بچاونہٕ خٲطرٕ تہٕ تُہٕنزِ نظر چھے مغرورس کُن، یُتھ تہٕ تُہۍ ہێکہِ تِمن ہٕندِس سٍتـ̡ بٔرِتھ۔ \n29.\\tتۂ چُھہ میٲنۍ چراغ، اے خداوند، تہٕ خداوند کرِ میٲنۍ تاریک گاش۔ {چراغ: یا، شمع}\n30. تکیازِ ژے سٍتـ̡ چُھس بہٕ أکِس لشکر منزٕ ژوٚلمُت: خدایہ سٍتـ̡ ووت بہٕ دیوارس پیٹھ وۄٹھ دِنہٕ۔ {ژلُن: یا، پھُٹمُت}\n31. {یوتام زَن} خدایہ، تٔمۍ سٕنز وتھ {چُھ} کامل۔ خداوند سُند کلام {چُھ} آزماونہٕ آمُت: سُہ چُھ تِمن سارِنٕے خٲطرٕ یُس أمِس پیٹھ بھروسہٕ کران چُھ۔ {آزمٲیش: یا، نَفذ}\n32.\\tخدا کُس چُھہ، یُس خداوند بچاوان چُھ؟ تہٕ کُس چُھہ کُس چُھہ کُنہِ سٍتـ̡ خدایہِ س� \n33.\\tخدا چُھ میٲنۍ طاقت {تہٕ} طاقت: تہٕ سُہ چُھ میٲنۍ وتھ کامل بناوان۔ {بناوُن: حب۔ رِدِتھ، یا، لول}\n34.\\tسُہ چُھ میانین قدمن ہٕندۍ پٲٹھۍ، تہٕ میانین تھزرن پیٹھ بِہناوُن۔ {بناوُن: حب۔ برابر}\n35. سُہ چُھ میانین اتھن جنگ ہیچھناوان۔ یُتھ زن میٲنۍ نرِ سٍتۍ فولادی کمان پھُٹراونہٕ ییہِ۔ {جنگہٕ خٲطرٕ: ہیب۔ جنگہٕ خٲطرٕ}\n36. ژے دِژ مے پننہِ نجات ہٕنز ڈھال تہِ: تہٕ چانہِ نرمی چھے میہ عظیم بنٲومٕژ۔ {بنوو...: ہیب۔ میہ کٔر ضرب }\n37.\\tژے کٔر میانہِ قدمہ میانہِ تلہ کنہِ بٔڈۍ۔ یُتھ نہ میانہِ کھۅر رٔسِتھ گٔیہِ۔ {کھۅرٕ: ہیب۔ گۅپھ﴾\n38.\\tمیہ کٔر پننین دُشمن ہُند تعاقب تہٕ تِم تباہ کٔرۍمٕتۍ۔ تہٕ دُبارٕ پھیُر نہٕ توٚت تام یوٚت تام نہٕ مے تِم کھٮ۪نہٕ۔ \n39. تہٕ مے چُھس تِم کھٮ۪مٕتۍ، تہٕ زخمی کٔرۍمٕتۍ، یُس نہٕ تِم ہیوٚک نہٕ وۅتھنہٕ یِتھ، آ، تِم گٔیہِ میانٮ۪ن قدمن تَل ۔ \n40.\\tکیازِ ژے چُھہ مے جنگہٕ خٲطرٕ طاقت دِژمُت: یِمو میہ خلاف کھڑا گٔیہ، تِمو کٔر میہ تل زیر۔ {زیر کٔرِتھ: ہیب۔ کٔرِتھ کٔرِتھ}\n41. ژے دِژ میہ میانین دُشمنن ہٕنز گردن تہِ، یُتھ بہٕ تِم تباہ کٔرِتھ یِم مےٚ نفرت کران چھِ۔ \n42.\\tتِمو وُچھ، مگر رژھراونہٕ خٲطرٕ اوس نہٕ کانہہ تہِ۔ {حتی} خداوند سٕندِس نِش، مگر تٔمۍ دِژ نہٕ تِمن جواب۔ \n43.\\tامہ پتہ کٔر میہ یمن زمینہِ ہنزِ گردِ ہیو لۅکٹۍ، میہ دِژ سڑکہِ ہنزِ رۅخہِ ہندۍ پاٹھۍ ٹھپہ لگٲوتھ، {تہٕ} پھٔہلٲوِتھ پھٔہلۍ۔ \n44. ژے تہِ کٔر میہ میانین لوکن ہٕنزِ کوششو نِش بچاو، ژے تھووُکھ میہ کافرن ہُند سردار: اکھ قوم یُس نہٕ میہ زانان اوس زِ سُہ کرِ میانہِ خدمت۔ \n45.\\tاجنبی گژھن میہ برونہہ کُن پان پیش کرُن: ییلہ تم بوزان چھہِ، تم گژھن میانہِ فرمانبردار۔ {اجنبی: ہیب۔ اجنبی سٕندِ فرزند} {تابع...: یا، فرضی فرمانبرداری: حب۔ اپُز}\n46.\\tاجنبی گژھن ختم گژھن تہٕ تِم گژھن پننیو نزدیکی مقامو نِش کھوژان۔ \n47. خداوند چُھ زندٕ روزان؛ تہٕ میانہِ کُنہِ سٍتـ̡ برکت دِن؛ تہٕ میانہِ نجات ہٕندِس پتھرِ ہُند خدا چُھہ بلند۔ \n48.\\tیہِ چُھہ خدا یُس میہ بدلہٕ چُھ، تہٕ یُس میانہِ تل لوکن ہُند انتقام دِوان چُھ، {بدلہٕ: عبرانی۔ بدلہٕ دِیُن}\n49. تہٕ یُس میہ میانیو دُشمنن نِش نیران چُھ، تہٕ ژے چُھکھ میہ تِمن ہٕندِس تھزرس پیٹھ تھوٚد تھوٚد کٔرمٕژ یِم میانہِ خلاف کھڑا گٔیہِ، تہٕ ژے کٔر مے تشددٕ انسانس نِش بچاو۔ \n50. تَمہِ کِنۍ کَرٕ بہٕ تُہُند شُکر ادا کَرُن، اے خدا، کُلٮ۪ن مَنٛز، تہٕ بہٕ گٮ۪وٕ تُہٕندِس ناوٕچ تعریف۔ \n51. {سُہ چُھ} پننِس بادشاہس خٲطرٕ نجات ہُند مینار تہٕ چُھ پننِس مسح شدٕ سٕندِس خٲطرٕ، داؤدس تہٕ تٔمۍ سٕندِس اولادس خٲطرٕ ہمیشہٕ خٲطرٕ رحمت۔","1.\\tوۅنۍ چھہِ یِم داؤد سٕندِ ٲخری کلام۔ یسیٰ سٕندِ نیچو داؤد ووٚن تہٕ یعقوب سٕندِ خدایہ سُند مسح کرنہٕ آمُت تہٕ اسرٲیلُک میٹھۍ زبور لیکھن وول شخص ووٚن، \n2. خداوند سُند روح کٔر میانہِ ذریعہ، تہٕ تٔمۍ سُند کلام اوس میانہِ زبانہِ مَنٛز۔ \n3.\\tاسرٲیلٕکۍ خداین ووٚن زِ یُس انسانس پیٹھ حکومت کرِ، سُہ گژھہِ خدایہ سٕندِس خوفس سٍتـ̡ حکومت کرُن، سُہ گژھہِ عادل آسُن۔ {سُہ...: یا، تُہۍ بٔنِو حُکُمران، وغیرہ}\n4.\\tتہٕ {سُہ آسہِ}صُبحُک گاش، {ییلہ}آفتاب کھسُن، {حتیٰ کہ} صبحس یُس اوٚبرٕ ورٲے آسہِ۔ {یِتھ} نرم گاسہٕ {یِتھ} روٗد پتہٕ صاف چمکاونہٕ سٍتۍ زمینہٕ منزٕ نیرِتھ۔ \n5. یۆدوَے میون گرٕ چُھہ نہٕ خدایہِ سٍتـ̡ یێلہِ چُھہ یێلہِ چُھہ یێلہِ سٍتـ̡ چُھہ یێلہِ سٍتـ̡ چُھہ یێلہِ سٍتـ̡ پى۪ٹھـ� \n6.\\tمگر ﴿بِلیال﴾ سٍتـ̡ یِم سارِنٕے کُنہِ سٍتـ̡ کٔرِتھ، تکیازِ تِم ہیکن نہٕ اَتھٕ سٍتـ̡ نِتھ: \n7.\\tمگر یُس انسان یُس تِمن اتھہٕ لاگہِ سُہ گژھہِ ششتر تہٕ نیزہٕ سٍتـ̡ لٔگِتھ لٔگـ̡ ۔ تہٕ یِم گژھن {أتھۍ} جایہِ نار سٍتـ̡ زالنہٕ یُن۔ {باڑ لٔگِتھ: ہیب۔ بٔرِتھ}\n8.\\tیِم چھِ تِمن طاقتور نفرن ہٕندۍ ناو یِم ڈیوڈس ٲسۍ: سُہ ٹیچمونایٹ یُس سیٹس پیٹھ بِہتھ اوس، کپتانن مَنٛز سردار۔ یۅہے اوس اڈینو دی ایزنیٹ: {تٔمۍ تُل پنُن نیزٕ تُل} ٲٹھن ہتن خلاف، یُس تٔمۍ اکی ساتہٕ مار۔ {The Tachmonite...: یا، Joshebbassebat the Tachmonite، ترٮن ہُند سر} {یُس سُہ ...: Heb. مارُن} {سُہ تُلُن...: (1ch:) سُہ کُس سُہ ...: Heb. مارُن}\n9.\\tتہٕ أمِس پَتہٕ اوس اَلعازر یُس ڈوڈو آہوہیت سُند نیچو اوس، یُس داؤدس سٍتـ̡ ترٚیو طاقتور نفرو منزٕ اکھ، ییلہ تِمو فلسطینن ہٕنز مخالفت کٔرِتھ {یِم} تتہِ ٲسۍ جنگہٕ خٲطرٕ جمع گٔمٕتۍ، تہٕ اسرٲیلٕکۍ مرد گٔیہِ ژٔلِتھ: \n10. سُہ ووٚتھ، تہٕ لوٚگ فلسطینن ہٕندِس اتھہٕ سٍتـ̡ تھوٚک، تہٕ تٔمۍ سُند اَتھٕ لٔگِتھ تلوارس سٍتـ̡ تھپھ کٔرِتھ، تہٕ خداوند کٔر تمہِ دۅہہ اکھ بٔڈ فتح۔ تہٕ لُکھ دِژ أمِس پَتہٕ لوُکھ واپس یِمن ہٕندِس سٍتـ̡ بُلاونہٕ خٲطرٕ۔ \n11.\\tتہٕ أمِس پَتہٕ اوس شمہ یُس ایجی ہرارتی سُند نیچو اوس۔ تہٕ فلسطینی گٔیہِ أکِس لشکرس مَنٛز جمع کرنہٕ، یَتھ مَنٛز دالَو سٍتـ̡ بٔرِتھ زمینہٕ ہُند اکھ ٹُکرٕ اوس، تہٕ لُکھ ژٔل فلسطینن نِش۔ {into...: یا، چارہ ژھارنہٕ خٲطرٕ}\n12.\\tمگر سُہ کھڑا زمینس منز، تہٕ کوٚرُن أمِس بچاو، تہٕ مٲرِن فلسطینی تہٕ خداوندَن کٔر اکھ بٔڈ فتح۔ \n13.\\tتہٕ ترہ سردارو منزٕ تریہ گٔیہِ بۄن، تہٕ ووت داؤدس نِش فصلہٕ وِزِ عدُلام کِس غارس مَنٛز۔ تہٕ فلسطینن ہُند لشکر دراو رفیم کِس وادی مَنٛز۔ {ترے...: یا، تریہ کپتان}\n14. تہٕ داؤد اوس تمہ وقتہٕ أکِس قبضس منٛز، تہٕ فلسطینن ہٕنٛز چھاونی {اوس} پتہٕ {منز}بیت اللحمس منٛز۔ \n15.\\tتہٕ داؤد گوو حسرت تہٕ وونُن، اے کاش میہ دِیہِ بیت اللحم کِس کیورُک آب، یُس دروازس پیٹھ چُھہ! \n16.\\tتہٕ تریہ طاقتور نفر ژٔلِتھ تہٕ بیت اللحم کِس کۅرٕ منزٕ آب کٔڈِتھ یُس دروازس نِش اوس، تہٕ نِتھ داودس نِش آب دِنہٕ۔ \n17.\\tتہٕ تٔمۍ ووٚن، اے خداوند، میہ نِش گژھ یہ کرُن: {کیا یہ} چُھہ نہٕ تِمن نفرن ہُند خون یُس تِمن ہُند زُو خطرس منز گٔیہِ؟ تێمہِ کِنۍ اوس نہٕ سُہ چُھہ نہٕ۔ یِمو چیزو کٔر یِمو تریہ طاقتور نفر۔ \n18.\\tتہٕ زرویاہ سُند نیچو یوآب سُند بوے ابیشایی اوس ترٮن منز سردار۔ تہٕ تٔمۍ تُل پنُن نیزٕ ترٚین ہتن پیٹھ تہٕ مارُن تِمن تہٕ کوٚرُن ترٮ۪ن منز ناو۔ {تہٕ مارُن تِم: حب۔ مارُن}\n19.\\tسُہ اوسا نہٕ ترٮ۪ن منز سارِوٕے کھۄتہٕ زیادٕ عزت؟ تَمہِ کِنۍ اوس سُہ تِہُند کپتان۔ \n20.\\tتہٕ کبزیلُک أکِس بہادر سُند نیچو بنیاہ یُس أکِس بہادر سُند نیچو اوس، یٔمۍ واریاہ کٲم کٔرمٕژ، تٔمۍ مارۍ موآبٕکۍ زٕ شیر ہِش نفر: سُہ تہِ ووت تہٕ شینہٕ وِزِ أکِس کھۅڈس مَنٛز اکھ شیر مٲرِتھ: {کُس...: حب۔ عظیم اعمال} {شیر ہیوٗ...: حب۔ خدایہ سُند شیر}\n21.\\tتہٕ تٔمۍ مور اکھ مصری یُس اکھ نیک انسان اوس، تہٕ مصری سندس اتھس منز اوس نیزٕ۔ مگر سُہ ووت أمِس نِش لٔرِتھ تہٕ لٔگِن مصری سٕندِ اتھہٕ منزٕ نیزٕ تہٕ مارُن پنٕنہِ نیزٕ سٍتـ̡ ۔ {اَکھ اصل...: ہیب۔ بُتھِ ہُند انسان، یا، نظر: یتھ بٔڈ قد وول انسان تہِ ونان چھِ}\n22.\\tیِمو {چیز} کٔر یہویادا سُند نیچو بنیاہ تہٕ تِمن ہُند ناو اوس ترٮ۪ن طاقتور نفرن مَنٛز ناو۔ \n23.\\tسُہ اوس ترہن کھۅتہٕ زیادٕ عزتدار، مگر سُہ ہیوٚک نہٕ {گۄڈنِکِس ترے} تام وٲتِتھ۔ تہٕ داؤد تھووُن سُہ پنہٕ نِس رٲچھ کُن۔ {زیادٕ...: یا، ترہن مَنٛز عزت} {گارڈ: یا، کونسل: ہیب۔ تٔمۍ سٕندِس حکمس پیٹھ}\n24.\\tجواب سُند بوے اوس اَسہل ترہن مَنٛز اکھ۔ بیت اللحمُک ڈوڈو سُند نیچو الہانان، \n25. شمہ ہاروڈائٹ، ایلیکا ہاروڈائٹ، \n26. ہیلیز دی پالٹائٹ، اِکیش سُند نیچو ایرا، \n27. ابیزر دی انیتھوتھیٹ، میبونائی دی ہشاطیت، \n28.\\tزلمون آہوہیت، مہارائی نیٹوفیتھ، \n29.\\tحلب یُس بَنَہ سُند نیچو یُس نیتوپھِتھ، اِتایی یُس رِبائی سُند نیچو یُس بنیامین سٕندِس شُرین ہٕندِس گیبیاہ سٍتـ̡ نیچو \n30.\\tبیناہ پیراتھونائٹ، گاش کِس نالہِ ہُند حدائی، {بروکس: یا، وادی}\n31. ابیالبون دی ارباتھیٹ، عزماویت دی برہومائٹ، \n32.\\tالیابا شالبونائٹ، یشین سٕندِس نیچوِس منز، جوناتھن، \n33.\\tشمہ ہراری، احیم شرار ہرارتی سُند نیچو، \n34.\\tالیفلیٹ، احسبائی سُند نیچو، اِلیام یُس احیتھوفیل سُند نیچو چھُ، \n35. ہیزرائی دی کارمیلیٹ، پارائی دی اربائٹ، \n36.\\tزوبہ کِس ناتھن سُند نیچو ایگل، بنی گدیت، \n37.\\tزیلیک عمونی، نہرایی بیروتھیٹ، زرویاہ سٕندِس نیچوِس یوآب سٕندِس ہتھیار بردار، \n38.\\tایرا ان اِتھرائٹ، گریب اِتھرائٹ، \n39.\\tاوریاہ حتی: کل ترہ تہ ست۔","1. تہٕ بییہِ گۆو خداوند سُند غصہٕ اسرٲیلِس سٍتـ̡ دِنہٕ، تہٕ تٔمۍ کٔر داؤد تِمن خلاف ونُن زِ گٔژھِو اسرٲیلِس تہٕ یہوداہ ہُند شُمار کرنہٕ۔ \n2.\\tکیازِ بادشاہن ووٚن لشکرُک کپتان، یُس أمِس سٍتـ̡ اوس، وۅنۍ گژھ اسرٲیلٕکۍ سارِنٕے قبیلہٕ منز، دان پیٹھٕ بیرشبع تام تہٕ لوکن ہُند گنزرٲوِو، یُتھ بہٕ زانہٕ لوکن ہُند تعداد زانہٕ۔ {گژھو: یا، کمپاس}\n3.\\tتہٕ یوآبن ووٚن بادشاہس زِ وۅنۍ چُھہ تُہند خدایہ لوکن منز ہتھ گنہٕ ہُرراوُن، تہٕ یُتھ میانہِ آقا بادشاہ سٕنزِ نظرن ہُند وُچھُن: مگر میانہِ آقا کیازِ چُھ اتھ چیزس پیٹھ خۅش گژھان؟ \n4.\\tبادشاہ سُند کلام اوس یوآبس تہٕ لشکرن ہٕندِس کپتانن خٕلاف۔ تہٕ یوآب تہٕ لشکرٕکۍ سردار دراو بادشاہ سٕندِ حٲضِری منز، اسرٲیلٕکۍ لوکن ہُند شمار کرنہٕ خٲطرٕ۔ \n5. تہٕ تِم گٔیہِ اردن کِس دٔچھنِس طرفہٕ یُس دریائے گاد کِس درمِس مَنٛز، تہٕ یَزرس کُن گٔیہِ: {دٔریاو: یا، وادی}\n6. پتہٕ آیہِ تِم گِلعادس تہٕ تہِ تٔحِمہودشی کِس سرزمینس کُن۔ تہٕ تِم آیہِ دانجان، تہٕ زیدون کُن، {تحتِمہودشی ہٕنٛز سرزمین: یا، نٔوۍ بَساونہٕ آمٕژ}\n7.\\tتہٕ ووت صور کِس مضبوطس منز، تہٕ حِوی تہٕ کنعانین ہٕندِس سارنٕے شہرن مَنٛز، تہٕ تِم گٔیہِ یہوداہ کِس جنوبس کُن، {حتیٰ کہ} بیرشبع کُن۔ \n8.\\tتێلہِ ییلہ تِم سارِنٕے زمینہٕ مٔنزۍ گٔیہِ، تِم آیہ نَو رٮ۪تن تہٕ وُہن دۅہن مۅکھہٕ یروشلمس کُن۔ \n9. تہٕ یوآبن دِژ بادشاہس لوکن ہُند تعداد تہٕ اسرائیلس مَنٛز ٲسۍ ٲٹھ لچھ بہادر نفر یِمو تلوار تُلِتھ۔ تہٕ یہوداہٕکۍ مرد ٲسۍ پانژھ لچھ ساس نفر۔ \n10.\\tتہٕ داؤد سُند دِل دِژ أمِس لُکن ہُند گنزراونہٕ پتہٕ۔ تہٕ داؤدَن ووٚن خداوند سٍتـ̡ یُس میہ کورمُت چُھ، تێمہِ سٍتـ̡ چُھہ واریاہ گۅناہ کورمُت، تہٕ وُنـ̡ چُھس ژے کُن التجا کٔرِتھ زِ اے خداوند، پنہٕ نـ̡ خادمُک گناہ نِش کٔرِ۔ تکیازِ مے چُھہ واریاہ بیوقوفی کٔرمٕژ۔ \n11.\\tییلہ داؤد صبحس وۅتھان اوس، خداوند سُند کلام آو داؤد سُند غیب پیغمبر گادس نِش وونُن، \n12. گژھ تہٕ داؤدس ونُن، یِتھٕ پٲٹھـ̡ خداوند چُھہ ونان زِ بہٕ چُھس ژے تریہ {چیز} پیش کران۔ تِمو منزٕ کٔرِو ژے اکھ ژٲرِتھ، یُتھ بہٕ ژے کٔرِتھ {یہ} کٔرِتھ۔ \n13.\\tیێلہِ آو گاد داؤدس نِش، تہٕ ووٚنُن تٔمِس تہٕ وونُن، کیا ژے واتہِ سَتھ ؤری قحطہٕ؟ نتہٕ ژیہ ژلہٕ پننین دُشمن برونہہ تریہ ریتھ ژلِتھ، ییلہ تِم تۅہہِ ہُند پیچھا کران چھِ؟ یا تۅہہِ ہٕندِس سرزمینس مَنٛز گژھہِ تریہ دۅہن ہُند وباء؟ وۅنۍ کٔرِو مشورٕ تہٕ وُچھکھ بہٕ کُس جواب یُس میہ سوزمُت اوس۔ \n14. تہٕ داؤدن ووٚن گاڈس زِ بہٕ چُھس سٮ۪ٹھاہ مُشکِلس مَنٛز: أسـ̡ وۅنۍ پۯاوُن خداوند سٕندِس اتھس مَنٛز۔ تٔمۍ سٕنزِ رحمتَن ہٕندِس اَتھَس مَنٛز، تہٕ بہٕ گٔژھ نہٕ اِنسان سٕندِس اتھس مَنٛز۔ {چُھہ عظیم: یا، واریاہ چھِ}\n15.\\tیێلہِ سوٗز خداوند صُبحہ پیٹھٕ مُقرر وقتس تام اِسرٲیلِس پیٹھ وُپھ وُپھ، تہٕ دٲن پیٛٹھٕ بیرشبع تام لُکن ہٕندِس لُکن ہٕندِ سٍتـ̡ ستتھ ساس نفر موٗدۍ۔ \n16.\\tتہٕ ییلہ فرشتہٕ یروشلمس پیٹھ اتھہٕ بڑٲوِتھ یُس تباہ کرنہٕ خٲطرٕ، خداوند کٔر أمِس بدی نِش توبہٕ تہٕ وونُن یُس لُکھ تباہ کٔرِ، یہِ چُھ کٲفی: وُنۍ روزُن پنُن اتھہٕ۔ تہٕ خداوند سُند فرشتہ اوس ارونہٕ یبوسی سٕندِس تھزرس پیٹھ۔ {آروناہ: تہِ ونان اورنان}\n17. تہٕ داؤدَن کٔر خداوند سٍتـ̡ کتھ ییلہ تٔمۍ سُہ فرشتہٕ وُچھمُت یُس لُکن ہُند مارٕ چُھ، تہٕ وونُن، لو، مے چُھہ گۅناہ کورمُت، تہٕ مے چُھہ بدکار کورمُت، مگر یِمو کیا چُھہ یِمو کٔرمٕتۍ؟ بہٕ چُھس دُعا کران زِ تُہُند اَتھٕ گژھہِ میانہِ خلاف تہٕ میٲنِس مٲلہِ سٕندِس گرس خٕلاف۔ \n18.\\tتہٕ گاد آو تمہِ دۅہہ داؤدس نِش، تہٕ وونُن أمِس زِ ہیوٚر گژھ، ارونا یبوسی سٕندِس تھریشنگس مَنٛز رٔلِتھ خداوند سٕندِ خٲطرٕ اکھ قربان گاہ۔ {آروناہ: عبرانی۔ آرانیا}\n19.\\tتہٕ داؤد ووت گاد سٕندِ قولہٕ مُطٲبق، خداوند سٕندِ حُکُم مُطٲبِق۔ \n20. تہٕ ارونا وُچھ تہٕ وُچھ بادشاہ تہٕ تٔمۍ سٕندِس نوکر أمِس کُن یِوان، تہٕ ارونا دراو نیبر، تہٕ کٔرٕن بادشاہس برونہہ کُن بُتھِس پیٹھ نمُن۔ \n21. تہٕ ارونن ووٚن، میون آقا بادشاہ کیازِ چُھ پننِس خادمس نِش آمُت؟ تہٕ داؤد ووٚن، تۅہہِ ہُند تھریشِنگ فلور ہیٚنہٕ خٲطرٕ، خداوند سٕندِ خٲطرٕ اکھ قربان گاہ بناونہٕ خٲطرٕ، یُتھ وبا لوکن نِش رُکاونہٕ ییہِ۔ \n22.\\tتہٕ ارونن ووٚن ڈیوڈس زِ میانہِ آقا بادشاہ نِن تہٕ دِیُن یُس أمِس خٲطرٕ نیرُن تہٕ پیش کرُن: وُچھِو، دزنہٕ خٲطرٕ بیل تہٕ لٔکرِ ہٕندِ خٲطرٕ دِنہٕ آمٕتۍ اوزار تہٕ بیلن ہٕندِ باقٕے آلات۔ \n23.\\tیِم سارِنٕے {چیز} کٔر اروناہ، یُس بادشاہ اوس، بادشاہس دِیُت۔ تہٕ ارونن ووٚن بادشاہس زِ خداوند تُہند خدا، چُھہ ژے قبول۔ \n24.\\tتہٕ بادشاہن ووٚن اروناہَس نہٕ۔ مگر بہٕ ہیوٚک ژے نِش یُس قٲمتس پیٹھ ہیوٚت، تہٕ بہٕ ہیوٚک نہٕ خداوند پننِس خداہس سٍتـ̡ زٲلِتھ نذرانہ پیش کرنہٕ یُس نہٕ مےٚ کانہہ خرچہٕ چُھ۔ چنانچہ داؤد ہیوٚت تھٕرِ تہٕ بیل پنژاہ شیکل رۄپہٕ ہٕندِس بدلس منز۔ \n25.\\tتہٕ داؤدَن بَنوو اَتہِ خداوند سٕندِ خٲطرٕ اکھ قربان گاہ، تہٕ دِتُن زٲلِتھ نذرانہ تہٕ امن پیش کرنہٕ۔ یێمہِ کِنۍ آو خداوند سٕندِ زمینہٕ خٲطرٕ درخواست کرنہٕ، تہٕ بُعا آو اسرٲیلِس نِش رُکاونہٕ۔"];
